import React, { useState } from 'react';
import { Moon, Sun, User, ChevronDown, Menu, X, ShieldCheck } from 'lucide-react';
import { Language } from '../types';

interface NavbarProps {
  lang: Language;
  setLang: (l: Language) => void;
  darkMode: boolean;
  setDarkMode: (d: boolean) => void;
  currentPage: string;
  setPage: (p: string) => void;
  onDemoLogin?: () => void;
}

export const SurePathLogo = ({ className = "w-10 h-10" }: { className?: string }) => (
  <svg viewBox="0 0 400 400" className={`${className} transition-transform duration-500 hover:scale-110`} fill="none" xmlns="http://www.w3.org/2000/svg">
    <defs>
      <linearGradient id="shieldGrad" x1="0%" y1="0%" x2="100%" y2="100%">
        <stop offset="0%" stopColor="#10b981" />
        <stop offset="100%" stopColor="#059669" />
      </linearGradient>
    </defs>
    <path 
      d="M200 40C200 40 80 70 80 160C80 260 200 340 200 340C200 340 320 260 320 160C320 70 200 40 200 40Z" 
      fill="url(#shieldGrad)" 
    />
    <path 
      d="M190 320C190 320 120 250 120 180C120 120 180 120 200 80C220 120 280 120 280 180C280 250 210 320 210 320" 
      stroke="white" 
      strokeWidth="25" 
      strokeLinecap="round" 
    />
    <path d="M200 80C200 80 170 50 200 70C230 50 200 80 200 80Z" fill="#aed581" />
  </svg>
);

const Navbar: React.FC<NavbarProps> = ({ lang, darkMode, setDarkMode, currentPage, setPage }) => {
  const [isOpen, setIsOpen] = useState(false);

  const menuItems = [
    { id: 'home', label: lang === Language.EN ? 'Home' : 'Beranda' },
    { id: 'products', label: lang === Language.EN ? 'Products' : 'Produk' },
    { id: 'claim', label: lang === Language.EN ? 'Claim AI' : 'Klaim AI' },
    { id: 'about', label: lang === Language.EN ? 'About Us' : 'Tentang Kami' },
  ];

  return (
    <nav className="fixed top-0 left-0 right-0 z-[100] bg-white/80 dark:bg-black/80 backdrop-blur-xl border-b border-slate-100 dark:border-white/5 transition-all duration-500">
      <div className="max-w-7xl mx-auto px-6 lg:px-12">
        <div className="flex justify-between h-20 items-center">
          <div className="flex items-center cursor-pointer gap-4 group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-10 h-10" />
            <div className="flex flex-col justify-center">
              <span className="font-black text-xl tracking-tighter text-slate-800 dark:text-white leading-none">
                Sure<span className="text-brand-500">Path</span>
              </span>
              <span className="text-[0.45rem] text-slate-400 dark:text-gray-500 font-black tracking-[0.2em] uppercase mt-1">
                Your Path to Protection
              </span>
            </div>
          </div>

          <div className="hidden xl:flex space-x-10">
            {menuItems.map((item) => (
              <button
                key={item.id}
                onClick={() => {
                  setPage(item.id);
                  if (['home', 'products', 'about'].includes(item.id)) {
                    document.getElementById(item.id)?.scrollIntoView({ behavior: 'smooth' });
                  }
                }}
                className={`${
                  currentPage === item.id
                    ? 'text-brand-500 font-black'
                    : 'text-slate-500 dark:text-gray-400 hover:text-brand-500 font-bold'
                } transition-all text-[0.7rem] uppercase tracking-[0.2em] relative py-2 group`}
              >
                {item.label}
                <span className={`absolute bottom-0 left-0 h-0.5 bg-brand-500 transition-all ${currentPage === item.id ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
              </button>
            ))}
          </div>

          <div className="hidden md:flex items-center space-x-6">
            <button
              onClick={() => setDarkMode(!darkMode)}
              className="p-2.5 bg-slate-50 dark:bg-white/5 rounded-2xl text-slate-400 hover:text-brand-500 transition-all"
            >
              {darkMode ? <Sun size={18} /> : <Moon size={18} />}
            </button>

            <button 
              className="bg-slate-900 dark:bg-white text-white dark:text-black hover:bg-brand-500 hover:scale-105 px-8 py-2.5 rounded-full text-[0.65rem] font-black uppercase tracking-[0.2em] transition-all shadow-xl active:scale-95 flex items-center gap-2 border border-white/10"
              onClick={() => setPage('auth')}
            >
              {lang === Language.EN ? 'Log In' : 'Masuk'}
            </button>
          </div>

          <div className="xl:hidden flex items-center gap-4">
             <button onClick={() => setIsOpen(!isOpen)} className="text-slate-900 dark:text-white">
                {isOpen ? <X size={24}/> : <Menu size={24}/>}
             </button>
          </div>
        </div>
      </div>

      {isOpen && (
        <div className="xl:hidden bg-white dark:bg-slate-900 border-b border-slate-100 dark:border-white/5 animate-fade-in absolute w-full shadow-2xl">
          <div className="px-6 py-8 space-y-6">
            <div className="space-y-4">
              {menuItems.map((item) => (
                <button
                  key={item.id}
                  onClick={() => { 
                    setPage(item.id); 
                    setIsOpen(false);
                    if (['home', 'products', 'about'].includes(item.id)) {
                      setTimeout(() => document.getElementById(item.id)?.scrollIntoView({ behavior: 'smooth' }), 100);
                    }
                  }}
                  className="block w-full text-left text-sm font-black uppercase tracking-widest text-slate-500 hover:text-brand-500"
                >
                  {item.label}
                </button>
              ))}
            </div>
            <div className="pt-6 border-t border-slate-100 dark:border-white/5">
               <button 
                 className="w-full bg-slate-900 dark:bg-white text-white dark:text-black py-4 rounded-2xl font-black uppercase tracking-widest flex items-center justify-center gap-3 shadow-xl"
                 onClick={() => { setIsOpen(false); setPage('auth'); }}
               >
                 {lang === Language.EN ? 'Log In' : 'Masuk'}
               </button>
            </div>
          </div>
        </div>
      )}
    </nav>
  );
};

export default Navbar;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  Home as HomeIcon, Zap, Wallet as WalletIcon, 
  UserCircle, LogOut, Sun, Moon, CheckCircle2, 
  QrCode, Bell, Plus, ChevronRight, ArrowRight,
  ShieldCheck, Info, Sparkles, Timer, Car, Plane,
  ShoppingBag, Shield, Cpu, Radio, LayoutGrid,
  Package, MessageCircle, Heart, ShieldAlert,
  Search, BellRing, Smartphone, Award, Lightbulb, Bot,
  CreditCard, TrendingUp, History
} from 'lucide-react';
import DesktopWebsite from './components/DesktopWebsite';
import Navbar, { SurePathLogo } from './components/Navbar';
import AuthGate from './components/AuthGate';
import ClaimManager from './ClaimManager';
import UserProfile from './UserProfile';
import AgentsWallet from './AgentsWallet';
import CarInsuranceWizard from './CarInsuranceWizard';
import TravelInsuranceWizard from './TravelInsuranceWizard';
import PAInsuranceWizard from './PAInsuranceWizard';
import MPARInsuranceWizard from './MPARInsuranceWizard';
import PortalHero from './PortalHero';
import AdminPortal from './admin/AdminPortal';
import HealthChat from './components/HealthChat';
import { Language, UserRole } from './types';
import { NeuralBot, PageTransition } from './components/car-wizard/WizardUI';
import { db, seedDatabase, Policy } from './db';

const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Menyapa Server...",
    "Menyiapkan Proteksi Pintar...",
    "Mengecek Penawaran Terbaik...",
    "Koneksi Aman...",
    "Selesai!"
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2)), 30);
    const msgTimer = setInterval(() => setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i)), 700);
    const finishTimer = setTimeout(onFinish, 3200);
    return () => { clearInterval(timer); clearInterval(msgTimer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-[#fafaf9] dark:bg-[#0c0a09] flex flex-col items-center justify-center overflow-hidden transition-colors duration-700">
      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-14 relative group">
           <div className="absolute inset-0 bg-primary-500/25 rounded-full blur-[70px] animate-pulse scale-150"></div>
           <NeuralBot className="w-56 h-56 relative drop-shadow-[0_0_20px_rgba(249,115,22,0.3)]" mood="happy" />
        </div>
        <div className="text-center space-y-8">
          <h1 className="text-5xl font-black tracking-[-0.05em] text-slate-900 dark:text-white uppercase">
            SURE<span className="text-primary-500">PATH</span>
          </h1>
          <div className="space-y-5">
            <div className="flex items-center justify-center gap-3">
               <div className="w-2 h-2 rounded-full bg-emerald-500 animate-ping"></div>
               <p className="text-[0.75rem] font-black text-gray-500 dark:text-gray-400 uppercase tracking-[0.4em] h-4 transition-all duration-500">
                  {messages[messageIdx]}
               </p>
            </div>
            <div className="w-72 h-1.5 bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden mx-auto shadow-inner">
                <div className="h-full bg-gradient-to-r from-primary-400 to-primary-600 transition-all duration-300 shadow-[0_0_10px_#f97316]" style={{ width: `${progress}%` }}></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const INITIAL_PRODUCTS = [
  { id: 'car', title: 'Asuransi Mobil', label: 'Asuransi Mobil', icon: Car, color: 'text-blue-500', active: true, cat: 'Retail', tech: 'AI Foto Kerusakan' },
  { id: 'travel', title: 'Asuransi Perjalanan', label: 'Asuransi Perjalanan', icon: Plane, color: 'text-emerald-500', active: true, cat: 'Retail', tech: 'Otomatis & Cepat' },
  { id: 'pa', title: 'Kecelakaan Diri', label: 'Kecelakaan Diri', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: 'Proteksi Penuh' },
  { id: 'mpar', title: 'Proteksi Barang', label: 'Proteksi Barang', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: 'Peralatan & Gadget' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  const timeGreeting = useMemo(() => {
    const hour = new Date().getHours();
    if (hour < 11) return "Selamat Pagi";
    if (hour < 15) return "Selamat Siang";
    if (hour < 19) return "Selamat Sore";
    return "Selamat Malam";
  }, []);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleDemoLogin = async () => {
    const user = await db.users.where('email').equals('user@surepath.ai').first();
    if (user) handleAuthSuccess(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  // PUBLIC VIEW ROUTING
  if (!isMobile && !appMode && !currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar 
          lang={lang} 
          setLang={setLang} 
          darkMode={darkMode} 
          setDarkMode={setDarkMode} 
          currentPage={currentPage} 
          setPage={setPage}
          onDemoLogin={handleDemoLogin}
        />
        <main className="pt-20">
          {currentPage === 'auth' ? (
             <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />
          ) : currentPage === 'claim' ? (
             <div className="max-w-xl mx-auto py-12 px-6">
                <ClaimManager onComplete={() => setPage('home')} />
             </div>
          ) : (
             <DesktopWebsite 
               onEnterPortal={() => setPage('auth')} 
               onAdminAccess={() => setPage('auth')} 
               currentLang={lang} 
               onLangChange={setLang} 
               section={currentPage}
             />
          )}
        </main>
      </div>
    );
  }

  // MOBILE LOGIN ROUTE
  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home':
        return (
          <PageTransition>
            <div className="space-y-10 pb-32 relative z-10 transition-all duration-700">
              <div className="flex items-center justify-between px-2">
                 <div className="flex items-center gap-5">
                    <div className="relative group cursor-pointer" onClick={() => setPage('profile')}>
                      <div className="w-16 h-16 bg-white dark:bg-slate-900 rounded-[2rem] shadow-2xl flex items-center justify-center border border-slate-100 dark:border-white/5 overflow-hidden transition-all duration-700 group-hover:scale-105 active:scale-95">
                         <div className="w-full h-full bg-gradient-to-tr from-slate-100 to-white dark:from-slate-800 dark:to-slate-900 flex items-center justify-center text-2xl font-black text-slate-300 dark:text-slate-600">
                           {currentUser?.name?.[0]}
                         </div>
                      </div>
                      <div className="absolute -bottom-1 -right-1 w-7 h-7 bg-emerald-500 rounded-full border-4 border-[#fafaf9] dark:border-[#0a0a0a] flex items-center justify-center text-[0.6rem] text-white font-black shadow-lg">
                         {currentUser?.trustScore || 85}
                      </div>
                    </div>
                    <div className="space-y-1">
                       <h3 className="text-2xl font-black tracking-tighter text-slate-900 dark:text-white leading-none">{timeGreeting}, {currentUser?.name.split(' ')[0]}!</h3>
                       <p className="text-[0.65rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-2">
                          <ShieldCheck size={12} className="animate-pulse"/> Jaringan Terproteksi
                       </p>
                    </div>
                 </div>
                 <button onClick={() => setPage('profile')} className="p-4 bg-white dark:bg-slate-900 rounded-2xl border border-slate-100 dark:border-white/5 text-slate-400 dark:text-gray-500 shadow-xl hover:text-primary-500 transition-all relative active:scale-90">
                    <Bell size={22}/>
                    <span className="absolute top-4 right-4 w-2 h-2 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>
                 </button>
              </div>

              <PortalHero onAction={(p) => setPage(p)} />

              <div className="grid grid-cols-4 gap-4 px-1">
                 {[
                   { id: 'products', label: 'Beli', icon: ShoppingBag, color: 'text-blue-500', bg: 'bg-blue-500/10' },
                   { id: 'claim', label: 'Klaim AI', icon: Zap, color: 'text-rose-500', bg: 'bg-rose-500/10' },
                   { id: 'wallet', label: 'Dompet', icon: WalletIcon, color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
                   { id: 'profile', label: 'Akun', icon: UserCircle, color: 'text-amber-500', bg: 'bg-amber-500/10' },
                 ].map(action => (
                   <div key={action.id} onClick={() => setPage(action.id)} className="flex flex-col items-center gap-3 cursor-pointer group active:scale-90 transition-all">
                      <div className={`w-16 h-16 ${action.bg} ${action.color} rounded-2xl flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform duration-500`}>
                         <action.icon size={28} strokeWidth={2.5}/>
                      </div>
                      <span className="text-[0.65rem] font-black uppercase tracking-widest text-slate-500 dark:text-slate-400 text-center leading-tight">{action.label}</span>
                   </div>
                 ))}
              </div>

              {latestPolicy && (
                <div className="px-1">
                  <div className="p-8 bg-slate-900 rounded-[3rem] text-white relative overflow-hidden shadow-[0_30px_60px_rgba(15,23,42,0.3)] border border-white/5 group">
                     <div className="absolute top-0 right-0 p-10 opacity-10 rotate-12 group-hover:rotate-0 transition-transform duration-1000">
                        {latestPolicy.type === 'CAR' ? <Car size={160}/> : <Plane size={160}/>}
                     </div>
                     <div className="relative z-10 space-y-8">
                        <div className="flex justify-between items-start">
                           <div className="space-y-1">
                              <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-[0.4em]">Polis Kamu</p>
                              <h4 className="text-2xl font-black uppercase tracking-tighter">{latestPolicy.coverageDetails?.vehicle?.brand} {latestPolicy.coverageDetails?.vehicle?.model}</h4>
                           </div>
                           <div className="p-3 bg-white/10 rounded-2xl border border-white/10 backdrop-blur-md shadow-xl"><ShieldCheck size={24} className="text-emerald-400"/></div>
                        </div>
                        <div className="flex justify-between items-end">
                           <div className="space-y-1">
                              <p className="text-[0.5rem] font-black text-slate-500 uppercase tracking-widest">Aktif Sampai</p>
                              <p className="text-sm font-black text-emerald-400">{new Date(latestPolicy.endDate).toLocaleDateString('id-ID', { month: 'long', year: 'numeric' })}</p>
                           </div>
                           <button onClick={() => setPage('profile')} className="px-6 py-2.5 bg-white text-slate-900 rounded-xl font-black uppercase text-[0.6rem] tracking-widest shadow-xl active:scale-95 transition-all">Lihat Detail</button>
                        </div>
                     </div>
                  </div>
                </div>
              )}

              <div className="px-1">
                 <div className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 flex gap-6 group transition-all duration-700 shadow-lg dark:shadow-none">
                    <div className="w-14 h-14 bg-amber-500/10 rounded-2xl flex items-center justify-center text-amber-500 flex-shrink-0 shadow-inner group-hover:rotate-6 transition-transform">
                       <Lightbulb size={28}/>
                    </div>
                    <div className="space-y-1.5">
                       <p className="text-[0.6rem] font-black uppercase text-amber-600 dark:text-amber-400 tracking-[0.2em]">Tahukah Kamu?</p>
                       <p className="text-xs font-bold text-slate-700 dark:text-slate-300 leading-relaxed">
                          Kamu bisa lapor klaim cuma lewat <span className="text-primary-600 dark:text-primary-400 font-black italic">foto HP</span>. AI kami bakal bantu prosesnya cuma dalam hitungan menit.
                       </p>
                    </div>
                 </div>
              </div>

              <div className="space-y-4 px-1 pt-2">
                  <div className="flex justify-between items-center px-4">
                     <h3 className="text-xl font-black uppercase tracking-tight text-slate-800 dark:text-white">Aktivitas Terakhir</h3>
                     <button onClick={() => setPage('wallet')} className="text-[0.65rem] font-black uppercase text-primary-500 flex items-center gap-1">Lihat Semua <ChevronRight size={14}/></button>
                  </div>
                  <div className="space-y-3">
                     <div className="p-5 bg-white dark:bg-slate-900 rounded-[2rem] border border-slate-100 dark:border-white/5 flex items-center justify-between shadow-sm">
                        <div className="flex items-center gap-4">
                           <div className="w-12 h-12 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500"><History size={20}/></div>
                           <div>
                              <p className="text-xs font-black uppercase text-slate-900 dark:text-white">Login Berhasil</p>
                              <p className="text-[0.5rem] font-bold text-gray-400 uppercase tracking-widest">Hari ini, 10:24 WIB</p>
                           </div>
                        </div>
                        <CheckCircle2 size={18} className="text-emerald-500"/>
                     </div>
                  </div>
              </div>
            </div>
          </PageTransition>
        );
      case 'products':
        return (
          <PageTransition>
            <div className="space-y-8 pb-24 pt-2">
              <h2 className="text-4xl font-black uppercase tracking-tighter px-2 text-slate-900 dark:text-white leading-none">Pilih <span className="text-primary-500">Asuransi</span></h2>
              <div className="grid gap-4">
                {products.map(p => (
                  <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 flex items-center justify-between active:scale-[0.98] transition-all duration-500 cursor-pointer shadow-xl dark:shadow-none hover:border-primary-500/30 group">
                    <div className="flex items-center gap-6">
                      <div className={`w-16 h-16 bg-gray-50 dark:bg-white/5 ${p.color} rounded-2xl flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform`}><p.icon size={32} strokeWidth={2.5}/></div>
                      <div>
                        <h4 className="font-black text-xl uppercase text-slate-900 dark:text-white leading-none mb-2">{p.title}</h4>
                        <p className="text-[0.65rem] text-gray-400 dark:text-gray-500 font-bold uppercase tracking-[0.2em]">{p.tech}</p>
                      </div>
                    </div>
                    <div className="w-12 h-12 rounded-full border border-slate-100 dark:border-white/10 flex items-center justify-center group-hover:bg-primary-500 group-hover:text-white group-hover:border-primary-500 transition-all"><ChevronRight size={24}/></div>
                  </div>
                ))}
              </div>
            </div>
          </PageTransition>
        );
      case 'claim': return <PageTransition><ClaimManager onComplete={() => setPage('home')} /></PageTransition>;
      case 'wallet': return <PageTransition><AgentsWallet /></PageTransition>;
      case 'profile': return <PageTransition><UserProfile currentUser={currentUser} onStartClaim={startClaimFromPolicy} /></PageTransition>;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'bot': return <HealthChat onBack={() => setPage('home')} />;
      case 'about': return <div className="max-w-4xl mx-auto py-12"><DesktopWebsite section="about" onEnterPortal={() => setPage('auth')} /></div>;
      default: return null;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');
  const navItems = [
    { id: 'home', icon: HomeIcon, label: 'Beranda' },
    { id: 'products', icon: ShoppingBag, label: 'Produk' }, 
    { id: 'bot', icon: Bot, label: 'Tanya AI' },
    { id: 'claim', icon: Zap, label: 'Klaim' },
    { id: 'profile', icon: UserCircle, label: 'Akun' }
  ];

  return (
