  const [extractedStnk, setExtractedStnk] = useState<any>(null);
  const [showManualForm, setShowManualForm] = useState(false);

  const isVinValid = useMemo(() => REGEX.VIN.test(vehicle.vin), [vehicle.vin]);
  const isPlateValid = useMemo(() => REGEX.PLATE.test(vehicle.plate), [vehicle.plate]);

  const handleStnkAutofill = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const mimeType = file.type;
    setLoading(true);
    setLoadingType('STNK');
    setExtractedStnk(null);
    setShowManualForm(false);

    const reader = new FileReader();
    reader.onload = async () => {
        const base64 = reader.result as string;
        const response = await extractStnkData(base64, mimeType);
        setLoading(false);
        setLoadingType(null);

        if (response.success && response.data) {
            const data = response.data;
            const cleanData = {
                ownerName: data.owner || '',
                plate: data.plate || '',
                brand: data.brand || '',
                model: data.model || '',
                color: data.color || '',
                year: data.year || '',
                vin: data.vin || '',
                engine: data.engine || '',
                status: data.status || 'OK'
            };

            setExtractedStnk(cleanData);
            if (setStnkResult) setStnkResult(cleanData);

            const match = CAR_DATABASE.find(c => 
                data.brand.toUpperCase().includes(c.brand) || 
                (c.modelName && data.brand.toUpperCase().includes(c.modelName))
            );

            const yearInt = parseInt(data.year) || 2025;
            const price = match ? (match.yearPrices[yearInt] || match.yearPrices[2024] || 0) * 1000000 : 0;

            setVehicle((prev: any) => ({
                ...prev,
                brand: match?.brand || data.brand.split(' ')[0] || prev.brand,
                model: match?.modelName || data.model || prev.model,
                year: yearInt || prev.year,
                plate: data.plate || prev.plate,
                vin: data.vin || prev.vin,
                engine: data.engine || prev.engine,
                price: price || prev.price,
                manualPrice: !price,
                condition: yearInt < new Date().getFullYear() ? 'USED' : 'NEW'
            }));

            if (!match) setEntryMode('MANUAL');
            else setEntryMode('DATABASE');
            setShowManualForm(true);
        } else {
            alert('AI gagal membaca STNK. Silakan isi data secara manual.');
            setEntryMode('MANUAL');
            setShowManualForm(true);
        }
    };
    reader.readAsDataURL(file);
  };

  return (
    <div className="space-y-8 animate-fade-in relative">
      {loading && loadingType === 'STNK' && <ScannerOverlay label="Sedang Membaca STNK..." />}

      {!extractedStnk && !showManualForm && (
        <div className="space-y-6">
            <div className="text-center space-y-2 mb-8">
                <h2 className="text-3xl font-black uppercase tracking-tighter">Data <span className="text-primary-500">Mobil</span></h2>
                <p className="text-xs text-gray-500 font-medium uppercase tracking-widest px-8">Foto STNK agar data terisi otomatis</p>
            </div>

            <label className="block w-full p-2 bg-gradient-to-br from-emerald-500 via-teal-500 to-blue-500 rounded-[3rem] cursor-pointer shadow-2xl hover:scale-[1.02] transition-all active:scale-95 group relative overflow-hidden">
                <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-20 transition-opacity"></div>
                <div className="bg-white dark:bg-black/40 rounded-[2.8rem] py-16 flex flex-col items-center justify-center text-center gap-6 relative z-10 border border-white/20">
                    <div className="w-24 h-24 bg-emerald-500/10 rounded-[2rem] flex items-center justify-center text-emerald-500 shadow-inner group-hover:scale-110 transition-transform duration-500">
                        <UploadCloud size={48} className="animate-bounce" />
                    </div>
                    <div>
                        <h4 className="text-xl font-black uppercase tracking-tight text-gray-900 dark:text-white">Ambil Foto STNK</h4>
                        <p className="text-[0.65rem] font-bold text-emerald-600 dark:text-emerald-400 uppercase tracking-widest mt-2 flex items-center justify-center gap-2">
                           <Sparkles size={12}/> Proses Cepat dengan AI
                        </p>
                    </div>
                </div>
                <input type="file" accept="image/*" className="hidden" onChange={handleStnkAutofill} />
            </label>

            <button 
                onClick={() => setShowManualForm(true)}
                className="w-full py-4 text-[0.6rem] font-black uppercase text-gray-400 hover:text-primary-500 transition-all tracking-[0.3em]"
            >
                Atau Isi Data Secara Manual
            </button>
        </div>
      )}

      {(extractedStnk || showManualForm) && (
        <div className="space-y-6 animate-pop-in">
           <div className="flex bg-gray-100 dark:bg-white/[0.03] p-1.5 rounded-[2rem] border border-black/5 dark:border-white/5 shadow-inner">
                <button onClick={() => setEntryMode('DATABASE')} className={`flex-1 py-4 rounded-[1.8rem] text-[0.65rem] font-black uppercase tracking-widest transition-all ${entryMode === 'DATABASE' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500 scale-100' : 'text-gray-400 scale-95'}`}><Database size={16} className="inline mr-2"/> Pilih Merk</button>
                <button onClick={() => setEntryMode('MANUAL')} className={`flex-1 py-4 rounded-[1.8rem] text-[0.65rem] font-black uppercase tracking-widest transition-all ${entryMode === 'MANUAL' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500 scale-100' : 'text-gray-400 scale-95'}`}><Edit3 size={16} className="inline mr-2"/> Ketik Manual</button>
           </div>

           <div className="space-y-5">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-[0.2em]">Merk Mobil</label>
                    <div className="relative group">
                        {entryMode === 'DATABASE' ? (
                            <select 
                                className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm appearance-none transition-all text-primary-500 uppercase"
                                value={vehicle.brand}
                                onChange={(e) => setVehicle({...vehicle, brand: e.target.value})}
                            >
                                <option value="">Pilih Merk</option>
                                {Array.from(new Set(CAR_DATABASE.map(c => c.brand))).sort().map(b => <option key={b} value={b}>{b}</option>)}
                            </select>
                        ) : (
                            <input className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm text-primary-500 uppercase" value={vehicle.brand} onChange={e => setVehicle({...vehicle, brand: e.target.value.toUpperCase()})} />
                        )}
                        {entryMode === 'DATABASE' && <ChevronDown size={20} className="absolute right-5 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>}
                    </div>
                </div>
                <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-[0.2em]">Tipe / Model</label>
                    <input className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 dark:border-white/5 outline-none focus:border-primary-500 font-black text-sm text-primary-500 uppercase" value={vehicle.model} onChange={e => setVehicle({...vehicle, model: e.target.value.toUpperCase()})} />
                </div>
              </div>

              <div className="grid grid-cols-2 lg:grid-cols-3 gap-5">
                 <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Tahun</label>
                    <div className="relative">
                        <select className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 outline-none focus:border-primary-500 font-black text-sm appearance-none" value={vehicle.year} onChange={e => setVehicle({...vehicle, year: parseInt(e.target.value)})}>
                            {Array.from({ length: 11 }, (_, i) => 2025 - i).map(y => (<option key={y} value={y}>{y}</option>))}
                        </select>
                        <ChevronDown size={18} className="absolute right-4 top-1/2 -translate-y-1/2 text-gray-400 pointer-events-none"/>
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Harga Mobil (Rp)</label>
                    <div className="relative">
                        <span className="absolute left-5 top-1/2 -translate-y-1/2 font-black text-gray-400 text-sm">Rp</span>
                        <input className="w-full pl-12 pr-5 py-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 focus:border-primary-500 outline-none font-black text-lg text-primary-500 shadow-inner" value={formatInputCurrency(vehicle.price.toString())} onChange={e => setVehicle({...vehicle, price: parseInt(e.target.value.replace(/\D/g, "") || "0"), manualPrice: true})} />
                    </div>
                 </div>
                 <div className="space-y-2 col-span-2 lg:col-span-1">
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Plat Nomor</label>
                    <div className="relative h-[72px] rounded-[1.8rem] bg-white dark:bg-[#0a0a0a] border-2 p-1 flex items-center justify-center shadow-inner group transition-all overflow-hidden" style={{ borderColor: vehicle.plate.length > 0 ? (isPlateValid ? '#10b98144' : '#f43f5e44') : 'rgba(0,0,0,0.1)' }}>
                        <input placeholder="B 1234 XYZ" className={`w-full bg-transparent text-center font-black text-2xl tracking-[0.2em] uppercase outline-none ${vehicle.plate.length > 0 ? (isPlateValid ? 'text-emerald-500' : 'text-rose-500') : 'text-black dark:text-white'}`} value={vehicle.plate} onChange={handlePlateChange} />
                        {isPlateValid && <CheckCircle2 size={16} className="absolute right-4 text-emerald-500 animate-pop-in"/>}
                    </div>
                 </div>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-2 gap-5">
                 <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Nomor Rangka (VIN)</label>
                    <div className="relative">
                        <input maxLength={17} placeholder="Cek di STNK" className={`w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 outline-none focus:border-primary-500 font-mono font-bold text-sm uppercase transition-all ${vehicle.vin.length > 0 ? (isVinValid ? 'border-emerald-500/20 text-emerald-500' : 'border-rose-500/20 text-rose-500') : 'border-black/5'}`} value={vehicle.vin} onChange={e => setVehicle({...vehicle, vin: e.target.value.toUpperCase().replace(/[^A-Z0-9]/g, "")})} />
                        {isVinValid && <CheckCircle2 size={18} className="absolute right-5 top-1/2 -translate-y-1/2 text-emerald-500 animate-pop-in"/>}
                    </div>
                 </div>
                 <div className="space-y-2">
                    <label className="text-[0.6rem] font-black uppercase text-gray-400 ml-2 tracking-widest">Nomor Mesin</label>
                    <input placeholder="Cek di STNK" className="w-full p-5 rounded-[1.8rem] bg-white dark:bg-white/[0.03] border-2 border-black/5 outline-none focus:border-primary-500 font-mono font-bold text-sm uppercase transition-all" value={vehicle.engine} onChange={e => setVehicle({...vehicle, engine: e.target.value.toUpperCase().replace(/[^A-Z0-9-]/g, "")})} />
                 </div>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default StepVehicle;

import React, { useState } from 'react';
import { 
  ShieldCheck, Car, Smartphone, Shield, 
  AlertCircle, Hash, Palette, User, FileText, 
  Scale, Building2, Wallet, Zap, Layers,
  CheckCircle2, Plus, Package, Calendar, Users,
  BadgePercent, ArrowDown, FileDown, Loader2
} from 'lucide-react';
import { formatIDR, Badge } from './WizardUI';
import { jsPDF } from 'jspdf';

interface StepPreSummaryProps {
  vehicle: any;
  coverage: any;
  premiumBreakdown: any;
  showBreakdown: boolean;
  setShowBreakdown: (b: boolean) => void;
  stnkResult: any;
  kycData: any;
}

const StepPreSummary: React.FC<StepPreSummaryProps> = ({
  vehicle, coverage, premiumBreakdown, showBreakdown, setShowBreakdown, stnkResult, kycData
}) => {
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  // Filter proteksi tambahan yang aktif
  const activeExpansions = [
    { id: 'authorized', label: 'Bengkel Resmi', active: coverage.authorized },
    { id: 'flood', label: 'Banjir & Badai', active: coverage.flood },
    { id: 'earthquake', label: 'Gempa & Tsunami', active: coverage.earthquake },
    { id: 'srcc', label: 'Kerusuhan (SRCC)', active: coverage.srcc },
    { id: 'terrorism', label: 'Terorisme & Sabotase', active: coverage.terrorism },
  ].filter(e => e.active);

  const InfoRow = ({ label, value, icon: Icon, color = "text-primary-500", mono = false }: any) => (
    <div className="flex justify-between items-center py-3.5 border-b border-black/5 dark:border-white/5 last:border-0">
      <div className="flex items-center gap-3">
        <Icon size={14} className={`${color} opacity-70`} />
        <span className="text-[0.65rem] font-bold uppercase text-gray-400 tracking-wider">{label}</span>
      </div>
      <span className={`text-[0.75rem] font-black uppercase text-slate-900 dark:text-gray-200 ${mono ? 'font-mono text-primary-500' : ''}`}>
        {value || '-'}
      </span>
    </div>
  );

  const generatePDF = async () => {
    setIsGeneratingPdf(true);
    try {
      const doc = new jsPDF();
      const pageWidth = doc.internal.pageSize.getWidth();
      const date = new Date().toLocaleDateString('id-ID');
      const quoteNo = `QT-${Date.now().toString().slice(-6)}`;

      // Header
      doc.setFillColor(15, 23, 42); // slate-900
      doc.rect(0, 0, pageWidth, 40, 'F');

      doc.setTextColor(255, 255, 255);
      doc.setFontSize(24);
      doc.setFont('helvetica', 'bold');
      doc.text("SUREPATH", 20, 20);

      doc.setFontSize(10);
      doc.setFont('helvetica', 'normal');
      doc.text("ASURANSI PINTAR & CEPAT", 20, 28);

      doc.text(`Tanggal: ${date}`, pageWidth - 20, 20, { align: 'right' });
      doc.text(`No. Penawaran: ${quoteNo}`, pageWidth - 20, 28, { align: 'right' });

      // Title
      doc.setTextColor(15, 23, 42);
      doc.setFontSize(16);
      doc.text("PENAWARAN ASURANSI KENDARAAN", 20, 55);
      doc.setDrawColor(249, 115, 22); // primary-500
      doc.setLineWidth(1);
      doc.line(20, 58, 60, 58);

      // Section: Data Nasabah
      doc.setFontSize(11);
      doc.setFont('helvetica', 'bold');
      doc.text("DATA NASABAH", 20, 75);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      doc.text(`Nama Tertanggung: ${kycData?.name || '-'}`, 25, 85);
      doc.text(`NIK: ${kycData?.ktp || '-'}`, 25, 92);
      doc.text(`Email: ${kycData?.email || '-'}`, 25, 99);

      // Section: Data Kendaraan
      doc.setFontSize(11);
      doc.setFont('helvetica', 'bold');
      doc.text("DATA KENDARAAN", 20, 115);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      doc.text(`Merk & Model: ${vehicle.brand} ${vehicle.model}`, 25, 125);
      doc.text(`Tahun: ${vehicle.year}`, 25, 132);
      doc.text(`Nomor Polisi: ${vehicle.plate}`, 25, 139);
      doc.text(`Warna: ${stnkResult?.color || '-'}`, 25, 146);

      // Section: Rincian Pertanggungan
      doc.setFontSize(11);
      doc.setFont('helvetica', 'bold');
      doc.text("RINCIAN PERTANGGUNGAN", 20, 162);
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      doc.text(`Tipe Paket: ${coverage.type === 'COMPREHENSIVE' ? 'All Risk (Lengkap)' : 'TLO (Kehilangan)'}`, 25, 172);

      let expansionText = activeExpansions.map(e => e.label).join(", ");
      if (coverage.tpl > 0) expansionText += `, TPL ${formatIDR(coverage.tpl)}`;
      doc.text("Manfaat Tambahan:", 25, 179);
      doc.setFontSize(9);
      doc.text(expansionText || "Tidak ada tambahan", 30, 186, { maxWidth: 160 });

      // Section: Biaya
      doc.setFontSize(11);
      doc.setFont('helvetica', 'bold');
      doc.text("IKHTISAR BIAYA", 20, 205);

      doc.setFont('helvetica', 'normal');
      doc.setFontSize(10);
      doc.text("Premi Dasar", 25, 215);
      doc.text(formatIDR(premiumBreakdown?.basicPremium || 0), pageWidth - 20, 215, { align: 'right' });

      doc.text("Proteksi Tambahan", 25, 222);
      const addOnVal = (premiumBreakdown?.totalPayable || 0) - (premiumBreakdown?.basicPremium || 0) + (premiumBreakdown?.discountAmount || 0) - (premiumBreakdown?.adminFee || 0) - (premiumBreakdown?.stampDuty || 0);
      doc.text(formatIDR(addOnVal), pageWidth - 20, 222, { align: 'right' });

      doc.text("Biaya Admin & Materai", 25, 229);
      doc.text(formatIDR((premiumBreakdown?.adminFee || 0) + (premiumBreakdown?.stampDuty || 0)), pageWidth - 20, 229, { align: 'right' });

      if (premiumBreakdown?.discountAmount > 0) {
        doc.setTextColor(16, 185, 129); // emerald-500
        doc.text(`Potongan Komisi (${premiumBreakdown.discountPercent}%)`, 25, 236);
        doc.text(`-${formatIDR(premiumBreakdown.discountAmount)}`, pageWidth - 20, 236, { align: 'right' });
      }

      // Total
      doc.setDrawColor(200, 200, 200);
      doc.line(20, 242, pageWidth - 20, 242);
      doc.setTextColor(15, 23, 42);
      doc.setFontSize(14);
      doc.setFont('helvetica', 'bold');
      doc.text("TOTAL PREMI BERSIH", 20, 252);
      doc.setTextColor(249, 115, 22);
      doc.text(formatIDR(premiumBreakdown?.totalPayable || 0), pageWidth - 20, 252, { align: 'right' });

      // Footer
      doc.setTextColor(150, 150, 150);
      doc.setFontSize(8);
      doc.setFont('helvetica', 'italic');
      doc.text("Diterbitkan secara digital oleh SurePath Engine.", pageWidth / 2, 275, { align: 'center' });
      doc.text("Terdaftar dan diawasi oleh OJK.", pageWidth / 2, 280, { align: 'center' });

      doc.save(`SurePath_Penawaran_${vehicle.plate.replace(' ', '_')}.pdf`);
    } catch (error) {
      console.error("PDF generation error:", error);
      alert("Gagal menyimpan PDF. Silakan coba lagi.");
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  return (
    <div className="space-y-6 animate-fade-in pb-10">
       <div className="px-2 flex justify-between items-end">
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter">Cek <span className="text-primary-500">Pesananmu</span></h2>
            <p className="text-xs text-gray-500 font-medium mt-1">Pastikan data sudah sesuai sebelum kita lanjut.</p>
          </div>

          <button 
            onClick={generatePDF}
            disabled={isGeneratingPdf}
            className="flex items-center gap-2 px-4 py-2 bg-white dark:bg-white/5 border border-black/5 rounded-xl text-[0.6rem] font-black uppercase tracking-widest hover:bg-primary-50 transition-colors shadow-sm disabled:opacity-50"
          >
            {isGeneratingPdf ? <Loader2 size={14} className="animate-spin"/> : <FileDown size={14}/>}
            {isGeneratingPdf ? 'Memproses...' : 'Simpan PDF'}
          </button>
       </div>

       {/* KELOMPOK 1: DATA MOBIL */}
       <div className="p-6 bg-white dark:bg-white/5 rounded-[2.5rem] border border-black/5 shadow-sm relative overflow-hidden group">
          <div className="flex items-center gap-3 mb-6 relative z-10">
             <div className="w-10 h-10 bg-blue-500/10 rounded-xl flex items-center justify-center text-blue-500 shadow-inner">
                <Car size={20}/>
             </div>
             <h4 className="text-sm font-black uppercase tracking-tight text-gray-900 dark:text-white">Data Mobil</h4>
          </div>

          <div className="space-y-0 relative z-10">
             <InfoRow label="Merk & Tipe" value={`${vehicle.brand} ${vehicle.model}`} icon={Layers} color="text-blue-500" />
             <InfoRow label="Tahun" value={vehicle.year} icon={Calendar} color="text-blue-500" />
             <InfoRow label="Plat Nomor" value={vehicle.plate} icon={Smartphone} color="text-blue-500" mono />
             <InfoRow label="Warna (STNK)" value={stnkResult?.color || 'Sesuai STNK'} icon={Palette} color="text-blue-500" />
          </div>
       </div>

       {/* KELOMPOK 2: DATA PEMILIK */}
       <div className="p-6 bg-white dark:bg-white/5 rounded-[2.5rem] border border-black/5 shadow-sm relative overflow-hidden">
          <div className="flex items-center gap-3 mb-6 relative z-10">
             <div className="w-10 h-10 bg-emerald-500/10 rounded-xl flex items-center justify-center text-emerald-500 shadow-inner">
                <User size={20}/>
             </div>
             <h4 className="text-sm font-black uppercase tracking-tight text-gray-900 dark:text-white">Data Pemilik</h4>
          </div>

          <div className="space-y-4 relative z-10">
             <div className="p-4 rounded-2xl bg-gray-50 dark:bg-black/20 border border-black/5">
                <p className="text-[0.5rem] font-black uppercase text-gray-400 mb-1">Nama di KTP</p>
                <p className="text-sm font-black text-slate-900 dark:text-white uppercase">{kycData?.name || '-'}</p>
             </div>
             <div className="p-4 rounded-2xl bg-gray-50 dark:bg-black/20 border border-black/5">
                <p className="text-[0.5rem] font-black uppercase text-gray-400 mb-1">Nama di STNK</p>
                <p className="text-sm font-black text-slate-900 dark:text-white uppercase">{stnkResult?.ownerName || '-'}</p>
             </div>
          </div>
       </div>

       {/* KELOMPOK 3: PILIHAN PROTEKSI */}
       <div className="p-6 bg-white dark:bg-white/5 rounded-[2.5rem] border border-black/5 shadow-sm">
          <div className="flex items-center gap-3 mb-6">
             <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner">
                <Shield size={20}/>
             </div>
             <h4 className="text-sm font-black uppercase tracking-tight text-gray-900 dark:text-white">Paket Proteksi</h4>
          </div>

          <div className="space-y-4">
             <div className="flex justify-between items-center p-4 bg-primary-500/5 rounded-2xl border border-primary-500/10">
                <div>
                   <p className="text-[0.5rem] font-black uppercase text-primary-500">Tipe Asuransi</p>
                   <p className="text-base font-black text-primary-600 dark:text-primary-400 uppercase">{coverage.type === 'COMPREHENSIVE' ? 'All Risk (Lengkap)' : 'TLO (Hanya Kehilangan)'}</p>
                </div>
                <Zap size={20} className="text-primary-500"/>
             </div>

             <div className="space-y-2">
                <p className="text-[0.55rem] font-black uppercase text-gray-400 ml-1">Manfaat Tambahan</p>
                <div className="flex flex-wrap gap-2">
                   {activeExpansions.map(e => (
                     <div key={e.id} className="px-3 py-1.5 bg-gray-50 dark:bg-white/5 rounded-full border border-black/5 flex items-center gap-2">
                        <CheckCircle2 size={10} className="text-emerald-500"/>
                        <span className="text-[0.55rem] font-bold uppercase text-gray-600 dark:text-gray-300">{e.label}</span>
                     </div>
                   ))}

                   {coverage.tpl > 0 && (
