            <button 
              className="w-full bg-slate-900 dark:bg-white text-white dark:text-black py-5 rounded-[2rem] font-black uppercase tracking-[0.2em] text-xs flex items-center justify-center gap-3 shadow-2xl active:scale-95 transition-all"
              onClick={() => { setIsOpen(false); setPage('auth'); }}
            >
              <User size={18}/>
              {lang === Language.EN ? 'Access Account' : 'Masuk Akun'}
              <ArrowRight size={16} className="text-brand-500"/>
