          )}
        </g>

        {/* Antenna */}
        <path d="M 100 45 L 100 25" stroke="#94a3b8" strokeWidth="6" strokeLinecap="round" />
        <circle cx="100" cy="20" r="7" fill={accentColor} className="animate-ping" />
