  const [products] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  const timeGreeting = useMemo(() => {
    const hour = new Date().getHours();
    if (hour < 11) return "Selamat Pagi";
    if (hour < 15) return "Selamat Siang";
    if (hour < 19) return "Selamat Sore";
    return "Selamat Malam";
  }, []);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleDemoLogin = async () => {
    const user = await db.users.where('email').equals('user@surepath.ai').first();
    if (user) handleAuthSuccess(user);
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  const startClaimFromPolicy = (policy: Policy) => setPage('claim');

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  if (!isMobile && !appMode && !currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar lang={lang} setLang={setLang} darkMode={darkMode} setDarkMode={setDarkMode} currentPage={currentPage} setPage={setPage} onDemoLogin={handleDemoLogin} />
        <DesktopWebsite onEnterPortal={() => { setAppMode(true); setPage('auth'); }} onAdminAccess={() => { setAppMode(true); setPage('auth'); }} currentLang={lang} onLangChange={setLang} />
      </div>
    );
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home':
        return (
          <PageTransition>
            <div className="space-y-8 pb-32 relative z-10">
              {/* Profile Header Card */}
              <div className="flex items-center justify-between px-2">
                 <div className="flex items-center gap-4">
                    <div className="relative cursor-pointer" onClick={() => setPage('profile')}>
                      <div className="w-14 h-14 bg-white dark:bg-slate-900 rounded-2xl shadow-xl flex items-center justify-center border border-gray-100 dark:border-white/5 overflow-hidden transition-all hover:scale-105 active:scale-95">
                         <div className="w-full h-full bg-gradient-to-tr from-slate-100 to-white dark:from-slate-800 dark:to-slate-900 flex items-center justify-center text-xl font-black text-slate-400">
                           {currentUser?.name?.[0]}
                         </div>
                      </div>
                      <div className="absolute -bottom-1 -right-1 w-6 h-6 bg-emerald-500 rounded-lg border-2 border-white dark:border-slate-950 flex items-center justify-center text-[0.5rem] text-white font-black">
                         {currentUser?.trustScore || 85}
                      </div>
                    </div>
                    <div className="space-y-0.5">
                       <h3 className="text-xl font-black tracking-tight text-slate-900 dark:text-white">{timeGreeting}, {currentUser?.name.split(' ')[0]}!</h3>
                       <p className="text-[0.65rem] font-bold text-gray-500 dark:text-gray-400 uppercase tracking-widest flex items-center gap-1.5">
                          <ShieldCheck size={12} className="text-primary-500"/> Node Aktif: {currentUser?.nodeId}
                       </p>
                    </div>
                 </div>
                 <button onClick={() => setPage('profile')} className="p-3 bg-white dark:bg-slate-900 rounded-xl border border-gray-100 dark:border-white/5 text-slate-400 shadow-md transition-all active:scale-90 relative">
                    <Bell size={20}/>
                    <span className="absolute top-2.5 right-2.5 w-1.5 h-1.5 bg-rose-500 rounded-full border border-white dark:border-slate-900"></span>
                 </button>
              </div>

              {/* Slider Component */}
              <PortalHero onAction={(p) => setPage(p)} />

              {/* Action Grid (Premium Glass Cards) */}
              <div className="grid grid-cols-4 gap-4 px-1">
                 {[
                   { id: 'products', label: 'Beli', icon: ShoppingBag, color: 'text-blue-500', bg: 'bg-blue-500/10' },
                   { id: 'claim', label: 'Klaim AI', icon: Zap, color: 'text-primary-500', bg: 'bg-primary-500/10' },
                   { id: 'wallet', label: 'Dompet', icon: WalletIcon, color: 'text-emerald-500', bg: 'bg-emerald-500/10' },
                   { id: 'profile', label: 'Akun', icon: UserCircle, color: 'text-indigo-500', bg: 'bg-indigo-500/10' },
                 ].map(action => (
                   <div key={action.id} onClick={() => setPage(action.id)} className="flex flex-col items-center gap-2 cursor-pointer group active:scale-90 transition-all">
                      <div className={`w-14 h-14 ${action.bg} ${action.color} rounded-2xl flex items-center justify-center shadow-inner group-hover:scale-105 transition-transform`}>
                         <action.icon size={26} strokeWidth={2.5}/>
                      </div>
                      <span className="text-[0.65rem] font-black uppercase tracking-widest text-slate-500 dark:text-gray-400">{action.label}</span>
                   </div>
                 ))}
              </div>

              {/* Latest Policy Card (Framer-like visual) */}
              {latestPolicy ? (
                <div className="px-1">
                  <div className="p-7 bg-slate-900 rounded-[2.5rem] text-white relative overflow-hidden shadow-2xl group border border-white/5">
                     <div className="absolute top-0 right-0 p-8 opacity-10 rotate-12 group-hover:rotate-0 transition-transform duration-1000">
                        <ShieldCheck size={140} className="text-primary-500"/>
                     </div>
                     <div className="relative z-10 space-y-6">
                        <div className="flex justify-between items-start">
                           <div className="space-y-1">
                              <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-[0.3em]">Polis Aktif</p>
                              <h4 className="text-xl font-black uppercase tracking-tight">{latestPolicy.policyNumber}</h4>
                           </div>
                           <div className="p-2.5 bg-white/10 rounded-xl border border-white/10 backdrop-blur-md shadow-lg"><QrCode size={20} className="text-primary-400"/></div>
                        </div>
                        <div className="p-4 bg-white/5 rounded-2xl border border-white/5 flex justify-between items-center">
                           <div className="flex items-center gap-3">
                              <div className="w-9 h-9 bg-blue-500/10 rounded-xl flex items-center justify-center text-blue-400"><Car size={18}/></div>
                              <p className="text-[0.7rem] font-black text-gray-200 uppercase tracking-tight">{latestPolicy.coverageDetails?.vehicle?.brand} {latestPolicy.coverageDetails?.vehicle?.model}</p>
                           </div>
                           <p className="text-[0.65rem] font-black text-emerald-400 uppercase">{new Date(latestPolicy.endDate).toLocaleDateString('id-ID', { month: 'short', year: 'numeric' })}</p>
                        </div>
                     </div>
                  </div>
                </div>
              ) : (
                <div className="px-1">
                   <div className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-gray-100 dark:border-white/5 shadow-sm text-center space-y-4">
                      <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 mx-auto shadow-inner"><ShieldAlert size={24}/></div>
                      <div className="space-y-1">
                        <h4 className="font-black text-slate-900 dark:text-white uppercase tracking-tight">Belum Ada Proteksi</h4>
                        <p className="text-[0.65rem] text-gray-500 font-bold uppercase tracking-widest leading-relaxed">Cari paket asuransi yang pas untuk mobil atau perjalanan kamu hari ini.</p>
                      </div>
                      <button onClick={() => setPage('products')} className="px-6 py-3 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.6rem] tracking-widest shadow-lg shadow-primary-500/20 active:scale-95 transition-all">Lihat Produk</button>
                   </div>
                </div>
              )}

              {/* AI Insight Highlight */}
              <div className="px-1">
                 <div className="p-6 bg-emerald-50 dark:bg-emerald-950/20 rounded-[2.2rem] border border-emerald-100 dark:border-emerald-900/30 flex gap-5 group shadow-sm transition-all hover:bg-emerald-100/50">
                    <div className="w-12 h-12 bg-white dark:bg-slate-800 rounded-2xl flex items-center justify-center text-emerald-500 shadow-sm flex-shrink-0 group-hover:rotate-12 transition-transform">
                       <Lightbulb size={24} className="fill-emerald-100 dark:fill-emerald-900/50"/>
                    </div>
                    <div className="space-y-1">
                       <p className="text-[0.6rem] font-black uppercase text-emerald-600 dark:text-emerald-400 tracking-[0.2em]">Tips Cerdas AI</p>
                       <p className="text-[0.75rem] font-bold text-slate-700 dark:text-gray-300 leading-relaxed">
                          Gunakan <span className="text-primary-500 font-black">Scan Visual AI</span> untuk klaim instan. Proses verifikasi kerusakan cuma butuh 60 detik!
                       </p>
                    </div>
                 </div>
              </div>
            </div>
          </PageTransition>
        );
      case 'products':
        return (
          <PageTransition>
            <div className="space-y-8 pb-24 pt-2">
              <div className="px-2">
                 <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-900 dark:text-white leading-none">Matriks <span className="text-primary-500">Proteksi</span></h2>
                 <p className="text-xs font-bold text-gray-500 uppercase tracking-widest mt-2">Pilih simpul asuransi kamu</p>
              </div>
              <div className="grid gap-4">
                {products.map(p => (
                  <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-6 glass-card rounded-[2.5rem] border border-gray-100 dark:border-white/5 flex items-center justify-between active:scale-[0.98] transition-all cursor-pointer shadow-sm hover:border-primary-500/30 group">
                    <div className="flex items-center gap-6">
                      <div className={`w-14 h-14 bg-gray-50 dark:bg-white/5 ${p.color} rounded-2xl flex items-center justify-center shadow-inner group-hover:scale-110 transition-transform`}><p.icon size={28} strokeWidth={2.5}/></div>
                      <div>
                        <h4 className="font-black text-base uppercase text-slate-900 dark:text-white leading-none mb-1.5">{p.title}</h4>
                        <p className="text-[0.6rem] text-gray-400 dark:text-gray-500 font-bold uppercase tracking-widest">{p.tech}</p>
                      </div>
                    </div>
                    <div className="w-10 h-10 rounded-xl bg-gray-100 dark:bg-white/5 flex items-center justify-center text-gray-400 group-hover:bg-primary-500 group-hover:text-white group-hover:border-primary-500 transition-all shadow-sm"><ChevronRight size={18}/></div>
                  </div>
                ))}
              </div>
            </div>
          </PageTransition>
        );
      case 'claim': return <PageTransition><ClaimManager onComplete={() => setPage('home')} /></PageTransition>;
      case 'wallet': return <PageTransition><AgentsWallet /></PageTransition>;
      case 'profile': return <PageTransition><UserProfile currentUser={currentUser} onStartClaim={startClaimFromPolicy} /></PageTransition>;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} />;
      case 'auth': return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
      case 'bot': return <HealthChat onBack={() => setPage('home')} />;
      default: return null;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');

  const navItems = [
    { id: 'home', icon: HomeIcon, label: 'Home' },
    { id: 'products', icon: ShoppingBag, label: 'Store' }, 
    { id: 'bot', icon: Bot, label: 'AI Bot' },
    { id: 'claim', icon: Zap, label: 'Claim' },
    { id: 'profile', icon: User, label: 'Me' }
  ];

  return (
    <div className={`${darkMode ? 'dark bg-slate-950' : 'bg-[#fafaf9]'} h-full transition-all duration-700 font-sans flex flex-col relative overflow-hidden`}>
      {/* Background Decor */}
      <div className="absolute inset-0 pointer-events-none z-0 overflow-hidden">
        <div className="absolute top-[-10%] left-[-20%] w-[100%] h-[100%] bg-gradient-to-br from-primary-500/5 via-transparent to-indigo-500/5 blur-[120px]"></div>
      </div>

      {!isWizardFlow && currentUser && (
        <header className="flex-shrink-0 h-22 glass-card px-8 flex items-center justify-between border-b border-gray-100 dark:border-white/5 z-[100] relative bg-white/70 dark:bg-slate-950/40 backdrop-blur-xl">
          <div className="flex items-center gap-3.5 cursor-pointer group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-10 h-10 group-hover:rotate-12 transition-transform" />
            <span className="font-black text-xl tracking-tighter uppercase leading-none text-slate-900 dark:text-white">MyInsure<span className="text-primary-500">Path</span></span>
          </div>
          <div className="flex items-center gap-2.5">
            <button onClick={() => setDarkMode(!darkMode)} className="p-2.5 bg-gray-100 dark:bg-white/5 rounded-xl text-slate-400 hover:text-primary-500 transition-colors shadow-sm">
              {darkMode ? <Sun size={18} className="text-yellow-400"/> : <Moon size={18}/>}
            </button>
            <button onClick={handleLogout} className="p-2.5 bg-slate-900 dark:bg-white text-white dark:text-slate-900 rounded-xl hover:bg-rose-500 dark:hover:bg-rose-500 transition-all shadow-md active:scale-95 group">
               <LogOut size={18} className="group-hover:translate-x-0.5 transition-transform"/>
            </button>
          </div>
        </header>
      )}

      {/* Main Content Area */}
      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative transition-all duration-500 ${isWizardFlow ? 'p-0 h-screen' : 'px-6 py-8'} bg-gradient-to-b from-transparent to-slate-50 dark:to-slate-900/10`}>
        {renderPortalContent()}
      </main>

      {/* Bottom Floating Navigation (App-like UX) */}
      {!isWizardFlow && currentUser && (
        <nav className="flex-shrink-0 fixed bottom-6 inset-x-6 h-18 bg-white/90 dark:bg-slate-900/90 backdrop-blur-2xl z-[200] flex items-center justify-around px-4 rounded-[2.5rem] shadow-[0_25px_50px_-12px_rgba(0,0,0,0.2)] border border-gray-100 dark:border-white/10 max-w-lg mx-auto transition-all duration-700">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-1.5 flex-1 py-3 transition-all duration-500 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1.5' : 'text-gray-400 dark:text-gray-600'}`}>
              <item.icon size={22} strokeWidth={currentPage === item.id ? 3 : 2} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(140,198,63,0.5)]' : ''} />
              <span className={`text-[0.45rem] font-black uppercase tracking-[0.25em] ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

