export const NeuralBot = ({ 
  className = "w-24 h-24", 
  mood = "scanning",
  color = "lime" 
}: { 
  className?: string, 
  mood?: 'happy' | 'thinking' | 'scanning' | 'wave',
  color?: 'lime' | 'blue' | 'rose' | 'amber' | 'indigo'
}) => {
  const colorMap = {
    lime: '#8CC63F',
    blue: '#3b82f6',
    rose: '#f43f5e',
    amber: '#f59e0b',
    indigo: '#6366f1'
  };

  const accentColor = colorMap[color] || colorMap.lime;

  return (
    <svg viewBox="0 0 200 200" className={className} fill="none" xmlns="http://www.w3.org/2000/svg">
      <defs>
        <linearGradient id="botChassis" x1="0" y1="0" x2="200" y2="200">
          <stop offset="0%" stopColor="#ffffff" />
          <stop offset="100%" stopColor="#f7fee7" />
        </linearGradient>
        <filter id="botShadow" x="-20%" y="-20%" width="140%" height="140%">
          <feDropShadow dx="0" dy="10" stdDeviation="15" floodColor="rgba(140, 198, 63, 0.15)" />
        </filter>
      </defs>

      <g className="animate-float" filter="url(#botShadow)">
        {/* Rounded Modern Chassis */}
        <rect x="35" y="45" width="130" height="110" rx="50" fill="url(#botChassis)" stroke="#d1d5db" strokeWidth="1" />

        {/* Organic Screen Shape */}
        <rect x="50" y="70" width="100" height="60" rx="25" fill="#020617" />

        {/* Eyes & Mood */}
        <g>
          {(mood === 'happy' || mood === 'wave') && (
            <>
              <circle cx="80" cy="95" r="6" fill={accentColor} className="animate-pulse" />
              <circle cx="120" cy="95" r="6" fill={accentColor} className="animate-pulse" />
              <path d="M 85 115 Q 100 125 115 115" stroke={accentColor} strokeWidth="4" strokeLinecap="round" />
            </>
          )}
          {mood === 'scanning' && (
            <>
               <rect x="65" y="92" width="25" height="4" rx="2" fill={accentColor} />
               <rect x="110" y="92" width="25" height="4" rx="2" fill={accentColor} />
               <line x1="60" y1="105" x2="140" y2="105" stroke={accentColor} strokeWidth="1" opacity="0.4" className="animate-pulse" />
            </>
          )}
          {mood === 'thinking' && (
             <g className="fill-amber-400">
                <circle cx="75" cy="100" r="5" className="animate-bounce" />
                <circle cx="100" cy="100" r="5" className="animate-bounce delay-75" />
                <circle cx="125" cy="100" r="5" className="animate-bounce delay-150" />
             </g>
          )}
        </g>

        {/* Antenna */}
        <path d="M 100 45 L 100 25" stroke="#94a3b8" strokeWidth="6" strokeLinecap="round" />
        <circle cx="100" cy="20" r="7" fill={accentColor} className="animate-ping" />
      </g>
    </svg>
  );
};

