    "Menghubungkan Jaringan...",
    "Mengamankan Koneksi...",
    "Sinkronisasi Data...",
    "Membuka Gerbang..."
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2)), 35);
