const PortalHero = ({ onAction }: { onAction: (id: string) => void }) => {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrent((prev) => (prev + 1) % SLIDES.length);
    }, 6000);
    return () => clearInterval(timer);
  }, []);

  return (
    <div className="relative h-[25rem] rounded-[3.5rem] overflow-hidden shadow-2xl border border-white/20 transition-all duration-1000">
      {SLIDES.map((slide, i) => (
        <div 
          key={i} 
          className={`absolute inset-0 transition-all duration-1000 ease-in-out ${i === current ? 'opacity-100 scale-100' : 'opacity-0 scale-105'}`}
        >
          <img 
            src={slide.image} 
            className="absolute inset-0 w-full h-full object-cover" 
            alt={slide.title} 
          />
          <div className="absolute inset-0 bg-gradient-to-t from-slate-900/90 via-slate-900/30 to-transparent"></div>

          <div className="absolute inset-0 p-10 flex flex-col justify-end items-start text-left">
            <div className={`space-y-5 transition-all duration-700 delay-300 ${i === current ? 'translate-y-0 opacity-100' : 'translate-y-8 opacity-0'}`}>
              <div className="inline-flex items-center gap-2.5 bg-white/15 backdrop-blur-md px-4 py-2 rounded-full border border-white/20">
                 <Sparkles size={14} className="text-amber-400 fill-amber-400" />
                 <span className="text-[10px] font-black text-white uppercase tracking-widest">Saran Untukmu</span>
              </div>

              <h2 className="text-4xl lg:text-5xl font-black text-white leading-[1] tracking-tight uppercase">
                {slide.title} <br/> 
                <span className={`text-${slide.color}-400`}>{slide.highlight}</span>
              </h2>

              <p className="text-[13px] text-gray-200 max-w-[280px] font-medium leading-relaxed opacity-80">
                {slide.desc}
              </p>

              <button 
                onClick={() => {
                  const target = slide.cta.toLowerCase().includes('travel') ? 'buy-travel' : 
                                 slide.cta.toLowerCase().includes('mobil') ? 'buy-car' : 
                                 slide.cta.toLowerCase().includes('klaim') ? 'claim' : 'products';
                  onAction(target);
                }}
                className="mt-3 px-8 py-4 bg-white text-slate-900 rounded-2xl font-black uppercase text-[11px] tracking-widest shadow-2xl flex items-center gap-3 transition-all active:scale-95 group hover:bg-primary-500 hover:text-white"
              >
                {slide.cta} <ArrowRight size={16} className="group-hover:translate-x-1 transition-transform"/>
              </button>
            </div>
          </div>
        </div>
      ))}

      {/* Indicators */}
      <div className="absolute bottom-10 right-10 flex gap-2.5 z-20">
        {SLIDES.map((_, i) => (
          <button 
            key={i} 
            onClick={() => setCurrent(i)}
            className={`transition-all duration-500 rounded-full ${i === current ? 'w-10 h-1.5 bg-white' : 'w-1.5 h-1.5 bg-white/40'}`}
          />
        ))}
      </div>
    </div>
  );
};

