const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Menyiapkan Dashboard...",
    "Mengamankan Koneksi...",
    "Sinkronisasi Akun...",
    "Hampir Selesai...",
    "Selamat Datang!"
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 4)), 30);
    const msgTimer = setInterval(() => setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i)), 700);
    const finishTimer = setTimeout(onFinish, 2500);
    return () => { clearInterval(timer); clearInterval(msgTimer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-white flex flex-col items-center justify-center overflow-hidden">
      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-10 p-6 bg-slate-50 border border-slate-100 rounded-3xl shadow-xl">
           <SurePathLogo className="w-20 h-20" />
        </div>
        <div className="text-center space-y-6">
          <h1 className="text-3xl font-black tracking-tight text-slate-900 uppercase">
            SURE<span className="text-emerald-500">PATH</span>
          </h1>
          <div className="space-y-4">
            <p className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em] h-4">
               {messages[messageIdx]}
            </p>
            <div className="w-56 h-1 bg-slate-100 rounded-full overflow-hidden mx-auto">
                <div className="h-full bg-emerald-500 transition-all duration-300" style={{ width: `${progress}%` }}></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={[]} setProducts={() => {}} userRole={currentUser.role} />;
  }

  if (!isMobile && !appMode && !currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar lang={lang} setLang={setLang} darkMode={darkMode} setDarkMode={setDarkMode} currentPage={currentPage} setPage={setPage} />
        <DesktopWebsite onEnterPortal={() => { setAppMode(true); setPage('auth'); }} onAdminAccess={() => { setAppMode(true); setPage('auth'); }} currentLang={lang} onLangChange={setLang} />
      </div>
    );
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  const renderContent = () => {
    switch(currentPage) {
      case 'home':
        return (
          <PageTransition>
            <div className="space-y-8 pb-32">
              {/* Profile Header */}
              <div className="flex items-center justify-between px-2">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-slate-900 rounded-2xl flex items-center justify-center text-xl font-bold text-white shadow-xl">
                      {currentUser?.name?.[0]}
                    </div>
                    <div>
                       <h3 className="text-xl font-black text-slate-900 tracking-tight">Halo, {currentUser?.name.split(' ')[0]}!</h3>
                       <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest flex items-center gap-1.5">
                          Node ID: {currentUser?.nodeId}
                       </p>
                    </div>
                 </div>
                 <button onClick={() => setPage('profile')} className="p-3 bg-slate-50 border border-slate-100 rounded-2xl text-slate-400 hover:text-emerald-500 transition-all relative">
                    <Bell size={20}/>
                    <span className="absolute top-3 right-3 w-1.5 h-1.5 bg-emerald-500 rounded-full border border-white"></span>
                 </button>
              </div>

              {/* Slider Hero */}
              <PortalHero onAction={(p) => setPage(p)} />

              {/* Quick Services */}
              <div className="grid grid-cols-4 gap-2">
                 {[
                   { id: 'products', label: 'Beli', icon: ShoppingBag, color: 'text-blue-500', bg: 'bg-blue-50' },
                   { id: 'claim', label: 'Klaim', icon: Zap, color: 'text-rose-500', bg: 'bg-rose-50' },
                   { id: 'wallet', label: 'Dompet', icon: WalletIcon, color: 'text-emerald-500', bg: 'bg-emerald-50' },
