            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-2 flex-1 py-4 transition-all duration-500 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-600'}`}>
              <item.icon size={26} strokeWidth={2.5} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.5)]' : ''} />
              <span className={`text-[0.5rem] font-black uppercase tracking-[0.2em] ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket, Users, HeartPulse, Receipt, Building2, Stethoscope } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, analyzeHealthReceipt, ClaimAnalysisData, DocumentSummary, HealthClaimData } from '../services/geminiService';
import { db, Claim } from '../db';
import { NeuralBot, NeuralProcessingView } from './car-wizard/WizardUI';
import { Language } from '../types';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const ClaimManager = ({ onComplete, lang }: { onComplete: () => void, lang: Language }) => {
  const [claimType, setClaimType] = useState<'AUTO' | 'HEALTH' | null>(null);
  const [step, setStep] = useState<'select' | 'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('select');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [healthResult, setHealthResult] = useState<HealthClaimData | null>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [photoBase64, setPhotoBase64] = useState<string>('');

  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));
  }, []);

  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);

      if (claimType === 'AUTO') {
        const response = await analyzeClaimPhoto(base64);
        if (response.success && response.data) {
          setClaimResult(response.data);
          setStep('result');
        } else {
          alert(t('Audit failed. Please use a clearer photo.', 'Analisa gagal. Mohon gunakan foto yang lebih jelas.'));
          setStep('upload');
        }
      } else if (claimType === 'HEALTH') {
        const response = await analyzeHealthReceipt(base64);
        if (response.success && response.data) {
          setHealthResult(response.data);
          setStep('result');
        } else {
          alert(t('Receipt audit failed.', 'Analisa kuitansi gagal.'));
          setStep('upload');
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert(t("Provide more details (min. 20 chars).", "Berikan kronologi lebih detail (min. 20 karakter)."));
      return;
    }

    if (!currentUser) return;
    setIsSubmitting(true);

    try {
        const amount = claimType === 'AUTO' ? (claimResult?.totalEstimasi || 0) : (healthResult?.totalAmount || 0);

        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            thirdPartyInvolved: reportForm.thirdPartyInvolved,
            status: 'SUBMITTED',
            amountEstimated: amount,
            photos: [photoBase64],
            aiAnalysis: claimType === 'AUTO' ? claimResult : healthResult,
            createdAt: new Date().toISOString()
        };

        await db.claims.add(newClaim);
        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        alert(t("Failed to save claim.", "Gagal menyimpan klaim."));
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center gap-3 mb-3">
      {showBack && (
        <button onClick={onBack} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:text-primary-500 transition-colors">
          <ChevronRight className="rotate-180" size={16}/>
        </button>
      )}
      <div className="w-7 h-7 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500">
        <ShieldCheck size={16}/>
      </div>
      <h3 className="text-lg font-black uppercase tracking-tight">{title}</h3>
    </div>
  );

  if (step === 'select') {
    return (
      <div className="space-y-6 animate-fade-in flex flex-col h-full justify-center px-4">
        <div className="text-center mb-6">
           <h2 className="text-2xl font-black uppercase tracking-tighter text-slate-800 dark:text-white">
             {t('Smart', 'Lapor')} <span className="text-primary-500">{t('Claim', 'Klaim')}</span>
           </h2>
           <p className="text-xs text-gray-500 font-bold uppercase mt-2 tracking-widest">{t('Select your insurance type', 'Pilih tipe asuransi kamu')}</p>
        </div>
        <div className="grid gap-4">
           <button 
             onClick={() => { setClaimType('AUTO'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 shadow-lg flex items-center gap-6 group hover:border-primary-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-blue-50 dark:bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500"><Smartphone size={32}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight">{t('Vehicle Claim', 'Klaim Kendaraan')}</h3>
                 <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest mt-1">{t('AI Photo Audit', 'Analisa Foto AI')}</p>
              </div>
           </button>
           <button 
             onClick={() => { setClaimType('HEALTH'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 shadow-lg flex items-center gap-6 group hover:border-primary-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-rose-50 dark:bg-rose-500/10 rounded-2xl flex items-center justify-center text-rose-500"><HeartPulse size={32}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight">{t('Health Claim', 'Klaim Kesehatan')}</h3>
                 <p className="text-[0.6rem] font-bold text-gray-400 uppercase tracking-widest mt-1">{t('Medical Receipt Scan', 'Scan Kuitansi Medis')}</p>
              </div>
           </button>
        </div>
      </div>
    );
  }

  if (step === 'upload') {
    return (
      <div className="space-y-3 animate-fade-in flex flex-col h-full justify-center">
        <Header title={claimType === 'AUTO' ? t("Vehicle Claim", "Klaim Mobil") : t("Health Claim", "Klaim Kesehatan")} showBack onBack={() => setStep('select')} />
        <div className="aspect-[4/3] relative rounded-[2rem] overflow-hidden bg-gray-100 dark:bg-white/5 border-2 border-dashed border-primary-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-14 h-14 bg-primary-500/10 rounded-full flex items-center justify-center text-primary-500 mb-2 group-hover:scale-110 transition-transform">
            <Camera size={28} />
          </div>
          <p className="text-base font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">
            {claimType === 'AUTO' ? t("Snap Photos", "Foto Kerusakan") : t("Upload Receipt", "Foto Kuitansi RS")}
          </p>
          <p className="text-[0.5rem] text-gray-400 mt-1 font-bold uppercase tracking-widest text-center px-4">
            {claimType === 'AUTO' ? t("Show us where it hurts.", "Ambil foto bagian yang rusak.") : t("Upload hospital bills.", "Unggah tagihan rumah sakit.")}
          </p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleUpload} />
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[2.5rem] h-full flex flex-col items-center justify-center animate-pop-in bg-white dark:bg-midnight overflow-hidden">
        <NeuralProcessingView 
          label={t("AI Analyzing...", "AI Sedang Cek...")} 
          sublabel={t("Calculating costs and verifying data.", "Menghitung biaya dan cek data.")}
        />
      </div>
    );
  }

  if (step === 'result') {
    return (
      <div className="space-y-4 animate-pop-in h-full flex flex-col pb-2">
        <Header title={t("AI Results", "Hasil Audit AI")} showBack onBack={() => setStep('upload')} />

        <div className="p-6 bg-primary-500/5 rounded-[2rem] border-2 border-primary-500/20 relative flex-shrink-0">
           <p className="text-[0.55rem] font-black uppercase text-primary-500 tracking-[0.3em] mb-1">{t('ESTIMATED AMOUNT', 'ESTIMASI BIAYA')}</p>
           <h3 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white">
             {formatIDR(claimType === 'AUTO' ? claimResult!.totalEstimasi : healthResult!.totalAmount)}
           </h3>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar space-y-4">
           <div className="p-5 bg-white dark:bg-white/5 rounded-2xl border border-black/5">
              <p className="text-[0.5rem] font-black text-gray-400 uppercase mb-2">{t('AI INSIGHT', 'ANALISA PINTAR')}</p>
              <p className="text-xs font-medium leading-relaxed italic text-slate-700 dark:text-gray-300">
                "{claimType === 'AUTO' ? claimResult!.aiInsight : healthResult!.diagnosisSummary}"
              </p>
           </div>
        </div>

        <button onClick={() => setStep('reporting')} className="py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.65rem] tracking-widest shadow-lg flex items-center justify-center gap-3">
          {t('Next Step', 'Lanjut Lapor')} <ArrowRight size={16}/>
        </button>
      </div>
    );
  }

  if (step === 'reporting') {
    return (
      <div className="animate-fade-in flex flex-col h-full">
        <Header title={t("Final Report", "Laporan Akhir")} showBack onBack={() => setStep('result')} />
        <form onSubmit={handleFinalReport} className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-3">
          <div className="grid grid-cols-2 gap-2">
            <div className="space-y-1">
              <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">{t('Date', 'Tanggal')}</label>
              <input type="date" required className="w-full px-4 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] font-bold" value={reportForm.date} onChange={(e) => setReportForm({...reportForm, date: e.target.value})} />
            </div>
            <div className="space-y-1">
              <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">{t('Time', 'Waktu')}</label>
              <input type="time" required className="w-full px-4 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] font-bold" value={reportForm.time} onChange={(e) => setReportForm({...reportForm, time: e.target.value})} />
            </div>
          </div>

          <div className="space-y-1">
            <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">{t('Location', 'Lokasi Kejadian')}</label>
            <input type="text" required placeholder={t("Where did it happen?", "Di mana kejadiannya?")} className="w-full px-4 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.65rem] font-bold" value={reportForm.location} onChange={(e) => setReportForm({...reportForm, location: e.target.value})} />
          </div>

          <div className="space-y-1">
            <label className="text-[0.45rem] font-black uppercase tracking-widest text-gray-400 ml-1">{t('Chronology', 'Kronologi Singkat')}</label>
            <textarea required rows={3} placeholder={t("Describe the incident...", "Ceritakan singkat kejadiannya...")} className="w-full px-3 py-2.5 rounded-xl bg-white dark:bg-white/5 border border-black/5 text-[0.6rem] font-medium leading-tight" value={reportForm.chronology} onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})} />
          </div>
        </form>

        <button onClick={handleFinalReport} disabled={isSubmitting} className="mt-2 w-full py-4 bg-primary-500 text-white rounded-xl font-black uppercase text-[0.55rem] tracking-[0.2em] shadow-xl flex items-center justify-center gap-2">
          {isSubmitting ? <Loader2 className="animate-spin" size={14}/> : <Rocket size={14}/>}
          {t('Send Claim', 'Kirim Klaim Sekarang')}
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-4 py-4 animate-pop-in flex flex-col h-full justify-center">
        <div className="w-20 h-20 bg-emerald-500 rounded-full mx-auto flex items-center justify-center text-white shadow-2xl">
          <CheckCircle2 size={40} strokeWidth={3} />
        </div>
        <div className="space-y-1 px-4">
          <h3 className="text-xl font-black uppercase tracking-tighter">{t('Success!', 'Berhasil!') }</h3>
          <p className="text-[0.65rem] text-gray-500 dark:text-gray-400 font-bold uppercase tracking-widest leading-relaxed">
            {t('Claim submitted. We will notify you within 60 minutes.', 'Klaim terkirim. Kami akan kabari dalam 60 menit ke depan.')}
          </p>
        </div>
        <button onClick={onComplete} className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-xl font-black uppercase text-[0.5rem] tracking-widest shadow-xl">{t('Back Home', 'Selesai')}</button>
      </div>
    );
  }

  return null;
};

export default ClaimManager;

