              <p className="text-[0.55rem] font-black uppercase text-rose-500 tracking-[0.3em] mb-1">{t('Total Medical Cost', 'Total Biaya Medis')}</p>
              <h3 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white">{formatIDR(healthResult.totalAmount)}</h3>
