const PortalHero = ({ onAction, lang }: { onAction: (id: string) => void, lang: Language }) => {
  const [current, setCurrent] = useState(0);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrent((prev) => (prev + 1) % SLIDES.length);
    }, 8000);
    return () => clearInterval(timer);
  }, []);

  const t = (slide: any, key: 'title'|'highlight'|'desc'|'cta') => {
      if (lang === Language.EN) return slide[key];
      const idnKeys: any = { title: 'idn', highlight: 'highlightIdn', desc: 'descIdn', cta: 'ctaIdn' };
      return slide[idnKeys[key]];
  };

  return (
    <div className="relative h-[26rem] rounded-[3.5rem] overflow-hidden shadow-2xl border border-white/10 transition-all duration-1000">
      {SLIDES.map((slide, i) => (
        <div 
          key={i} 
          className={`absolute inset-0 transition-all duration-1000 ease-in-out ${i === current ? 'opacity-100 scale-100' : 'opacity-0 scale-110'} ${slide.bgClass}`}
        >
          {slide.pattern}
          <div className="absolute inset-0 bg-gradient-to-t from-slate-950/80 via-transparent to-black/20"></div>

          <div className="absolute inset-0 p-12 flex flex-col justify-end">
            <div className={`space-y-6 transition-all duration-700 delay-300 ${i === current ? 'translate-y-0 opacity-100' : 'translate-y-12 opacity-0'}`}>
              <div className="inline-flex items-center gap-3 bg-white/10 backdrop-blur-xl px-5 py-2 rounded-full border border-white/20 shadow-xl">
                 <Sparkles size={16} className="text-amber-400 fill-amber-400 animate-pulse" />
                 <span className="text-[0.65rem] font-black text-white uppercase tracking-[0.25em]">{lang === Language.EN ? 'Neural Update Active' : 'Update Neural Aktif'}</span>
              </div>

              <div className="space-y-1">
                <h2 className="text-4xl md:text-5xl font-black text-white leading-none tracking-tighter uppercase">
                  {t(slide, 'title')}
                </h2>
                <h3 className={`text-4xl md:text-5xl font-black tracking-tighter uppercase text-${slide.color}-400`}>
                   {t(slide, 'highlight')}
                </h3>
              </div>

              <p className="text-sm text-gray-200 max-w-[320px] font-medium leading-relaxed opacity-90">
                {t(slide, 'desc')}
              </p>

              <button 
                onClick={() => {
                  const ctaText = t(slide, 'cta').toLowerCase();
                  const target = ctaText.includes('travel') ? 'buy-travel' : 
                                 ctaText.includes('mobil') || ctaText.includes('car') ? 'buy-car' : 
                                 ctaText.includes('klaim') || ctaText.includes('claim') ? 'claim' : 'products';
                  onAction(target);
                }}
                className="mt-4 px-10 py-5 bg-white text-slate-950 rounded-2xl font-black uppercase text-[0.7rem] tracking-[0.3em] w-fit shadow-2xl flex items-center gap-4 transition-all hover:scale-105 active:scale-95 group relative overflow-hidden"
              >
                <slide.icon size={18} className={`text-${slide.color}-500`}/>
                <span className="relative z-10">{t(slide, 'cta')}</span>
                <ArrowRight size={18} className="group-hover:translate-x-2 transition-transform text-gray-400 relative z-10"/>
              </button>
            </div>
          </div>
        </div>
      ))}

      <div className="absolute bottom-12 right-12 flex gap-3 z-20">
        {SLIDES.map((_, i) => (
          <button 
            key={i} 
            onClick={() => setCurrent(i)}
            className={`transition-all duration-700 rounded-full h-2.5 shadow-lg border border-white/20 ${i === current ? 'w-12 bg-white' : 'w-2.5 bg-white/30 hover:bg-white/50'}`}
          />
        ))}
      </div>
    </div>
  );
};

export default PortalHero;

import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, Eye, EyeOff, Radio, Fingerprint, Sparkles, Activity,
  BellRing, X, RefreshCw, Smartphone, BadgeCheck, KeyRound, 
  Zap, ShieldCheck, Globe, AlertCircle, Shield
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, User as DBUser } from '../db';
import { hashPassword, verifyPassword, validatePasswordStrength, REGEX } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
}

const ValidationStatus: React.FC<{ met: boolean, label: string }> = ({ met, label }) => (
    <div className={`flex items-center gap-2 transition-all ${met ? 'text-emerald-500' : 'text-slate-400'}`}>
        <div className={`w-3 h-3 rounded-full flex items-center justify-center ${met ? 'bg-emerald-500/10' : 'bg-slate-100 dark:bg-white/5'}`}>
            {met && <ShieldCheck size={8} strokeWidth={4} />}
        </div>
        <span className="text-[0.6rem] font-bold uppercase tracking-widest">{label}</span>
    </div>
);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState(initialLang === Language.EN ? 'Secure Environment' : 'Lingkungan Aman');
  const [lang, setLang] = useState<Language>(initialLang);

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  // Real-time Validation
  const passwordStrength = useMemo(() => validatePasswordStrength(formData.password), [formData.password]);
  const isEmailValid = useMemo(() => REGEX.EMAIL.test(formData.email), [formData.email]);
  const isPhoneValid = useMemo(() => REGEX.PHONE.test(formData.phone), [formData.phone]);

  const canRegister = useMemo(() => {
      return formData.name.length > 2 && isEmailValid && isPhoneValid && passwordStrength.score === 4;
  }, [formData.name, isEmailValid, isPhoneValid, passwordStrength]);

  const canLogin = useMemo(() => {
      return isEmailValid && formData.password.length > 0;
  }, [isEmailValid, formData.password]);

  const handleDemoAccess = async () => {
    setLoading(true);
    setStatusMsg(t('Opening Demo Access...', 'Membuka Akses Demo...'));
    setError(null);
    try {
      const user = await db.users.where('email').equals('user@surepath.ai').first();
      if (user) {
        setStatusMsg(t('Demo Node Ready!', 'Akses Demo Terbuka!'));
        setTimeout(() => onAuthSuccess(user), 1000);
      } else {
        setError(t("Demo user not found.", "User demo belum siap."));
        setLoading(false);
      }
    } catch (err) {
      setError(t("Technical error loading demo.", "Gagal memuat demo."));
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'REGISTER' && !canRegister) return;
    if (mode === 'LOGIN' && !canLogin) return;

    setLoading(true);
    setError(null);
    setStatusMsg(t('Verifying Identity...', 'Memverifikasi Identitas...'));

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setStatusMsg(t('Authentication Success!', 'Berhasil Masuk!'));
            setTimeout(() => onAuthSuccess(user), 800);
          } else {
            setError(t("Invalid password.", "Password salah."));
            setLoading(false);
          }
        } else {
          setError(t("Email not registered.", "Email belum terdaftar."));
          setLoading(false);
        }
      } else {
        const existing = await db.users.where('email').equals(formData.email).first();
        if (existing) {
          setError(t("Email already in use.", "Email sudah digunakan."));
          setLoading(false);
          return;
        }
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setStatusMsg(t('Verification Code Sent!', 'Kode Verifikasi Dikirim!'));
        }, 1500);
      }
    } catch (err) {
      setError(t("System error. Try again.", "Gagal sistem. Coba lagi."));
      setLoading(false);
    }
  };

  const finalizeRegistration = async () => {
    setLoading(true);
    setStatusMsg(t('Initializing Your Node...', 'Menyiapkan Akun Kamu...'));
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: UserRole.CUSTOMER,
        nodeId: `SP-USER-${Math.floor(1000 + Math.random() * 9000)}`,
        verified: true,
        trustScore: 85,
        memberSince: new Date().toISOString()
      };
      const id = await db.users.add(newUser);
      onAuthSuccess({ ...newUser, id });
    } catch (err) {
      setError(t("Registration failed.", "Gagal pendaftaran."));
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-slate-50 dark:bg-[#080707] flex flex-col items-center p-6 relative overflow-hidden transition-all duration-700">

      <div className="absolute top-10 right-10 flex gap-2 z-50">
          <button onClick={() => setLang(Language.ID)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black tracking-widest border transition-all ${lang === Language.ID ? 'bg-primary-500 text-white border-primary-500 shadow-lg' : 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400'}`}>ID</button>
          <button onClick={() => setLang(Language.EN)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black tracking-widest border transition-all ${lang === Language.EN ? 'bg-primary-500 text-white border-primary-500 shadow-lg' : 'bg-white dark:bg-white/5 border-slate-200 dark:border-white/10 text-slate-400'}`}>EN</button>
      </div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10 pt-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-6">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-white/5 relative group transition-all">
               <SurePathLogo className="w-16 h-16 relative z-10" />
            </div>
            <div className="absolute -bottom-3 -right-3 w-12 h-12 bg-white dark:bg-black rounded-2xl shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5">
                <NeuralBot mood={loading ? 'thinking' : (passwordStrength.score > 2 ? 'happy' : 'scanning')} className="w-8 h-8" />
            </div>
          </div>
          <h1 className="text-3xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.3em] mt-3">{statusMsg}</p>
        </div>

        <div className="w-full bg-white dark:bg-[#0c0c0c] rounded-[3rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5 overflow-hidden transition-all">
          {mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in py-4">
              <div className="space-y-2">
                <h3 className="text-xl font-black uppercase tracking-tight">{t('Enter Code', 'Masukkan Kode')}</h3>
                <p className="text-[0.65rem] text-slate-400 font-bold uppercase tracking-widest">{t('Enter 6-digit code received.', 'Masukkan 6 digit kode verifikasi.')}</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-200 dark:border-white/10 text-center text-4xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all font-mono"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button 
                onClick={async () => otp === generatedOtp ? await finalizeRegistration() : setError(t("Incorrect code.", "Kode salah."))} 
                disabled={otp.length < 6 || loading} 
                className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 disabled:opacity-30 transition-all"
              >
                {t('Confirm Node', 'Konfirmasi Akun')}
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1.5 rounded-2xl mb-2 border border-slate-200 dark:border-white/5 shadow-inner">
                <button type="button" onClick={() => { setMode('LOGIN'); setError(null); }} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 opacity-60'}`}>{t('Login', 'Masuk')}</button>
                <button type="button" onClick={() => { setMode('REGISTER'); setError(null); }} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 opacity-60'}`}>{t('Register', 'Daftar')}</button>
              </div>

              <form onSubmit={handleAuth} className="space-y-6">
                <div className="space-y-4">
                  {mode === 'REGISTER' && (
                    <div className="space-y-1.5">
                        <label className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest ml-1">{t('Full Name', 'Nama Lengkap')}</label>
                        <div className="relative">
                          <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                          <input 
                              required placeholder={t("Name on Identity Card", "Nama Sesuai KTP")}
                              className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm"
                              value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})}
                          />
                        </div>
                    </div>
                  )}

                  <div className="space-y-1.5">
                      <label className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest ml-1">Email</label>
                      <div className="relative">
                          <Globe size={18} className={`absolute left-4 top-1/2 -translate-y-1/2 transition-colors ${formData.email.length > 0 ? (isEmailValid ? 'text-emerald-500' : 'text-rose-500') : 'text-slate-300'}`} />
                          <input 
                              required type="email" placeholder="contoh@email.com"
                              className={`w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 rounded-2xl outline-none transition-all font-bold text-sm ${formData.email.length > 0 ? (isEmailValid ? 'border-emerald-500/20' : 'border-rose-500/20') : 'border-slate-100 dark:border-white/5'}`}
                              value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})}
                          />
                      </div>
                  </div>

                  <div className="space-y-1.5">
                      <label className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest ml-1">{t('Password', 'Kata Sandi')}</label>
                      <div className="relative">
                          <KeyRound size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                          <input 
                              required type={showPass ? 'text' : 'password'} placeholder="••••••••"
                              className="w-full pl-12 pr-12 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm"
                              value={formData.password} onChange={(e) => setFormData({...formData, password: e.target.value})}
                          />
                          <button type="button" onClick={() => setShowPass(!showPass)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-primary-500 transition-colors">
                              {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
                          </button>
                      </div>
                  </div>

                  {mode === 'REGISTER' && formData.password.length > 0 && (
                      <div className="p-5 bg-slate-50 dark:bg-white/[0.02] border border-slate-100 dark:border-white/5 rounded-[2rem] space-y-4 animate-fade-in">
                          <div className="flex justify-between items-center">
                              <p className="text-[0.6rem] font-black uppercase text-gray-400 tracking-widest">{t('Password Strength', 'Keamanan Sandi')}</p>
                              <span className={`text-[0.6rem] font-black uppercase ${passwordStrength.score === 4 ? 'text-emerald-500' : 'text-amber-500'}`}>
                                  {passwordStrength.score === 4 ? t('VERY SECURE', 'SANGAT AMAN') : passwordStrength.score > 2 ? t('SECURE', 'AMAN') : t('WEAK', 'KURANG AMAN')}
                              </span>
                          </div>
                          <div className="flex gap-1.5">
                              {[1,2,3,4].map(i => (
                                  <div key={i} className={`h-1.5 flex-1 rounded-full transition-all duration-500 ${i <= passwordStrength.score ? (passwordStrength.score === 4 ? 'bg-emerald-500 shadow-[0_0_10px_#10b981]' : 'bg-amber-500') : 'bg-slate-200 dark:bg-white/10'}`}></div>
                              ))}
                          </div>
                      </div>
                  )}
                </div>

                {error && (
                  <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3 text-rose-500 text-[0.65rem] font-bold animate-pop-in">
                      <AlertCircle size={16}/>
                      {error}
                  </div>
                )}

                <button 
                  type="submit" 
                  disabled={loading || (mode === 'REGISTER' && !canRegister) || (mode === 'LOGIN' && !canLogin)} 
                  className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.3em] shadow-2xl hover:scale-[1.01] active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-30 disabled:grayscale"
                >
                  {loading ? <RefreshCw size={18} className="animate-spin text-primary-500"/> : (mode === 'LOGIN' ? t('Login Now', 'Masuk Sekarang') : t('Register Now', 'Daftar Sekarang'))} 
                </button>
              </form>

              {mode === 'LOGIN' && (
                <div className="pt-4 border-t border-slate-100 dark:border-white/5 space-y-4">
                  <button 
                    type="button"
                    onClick={handleDemoAccess}
                    disabled={loading}
                    className="w-full py-4 bg-emerald-500/10 text-emerald-600 dark:text-emerald-400 border border-emerald-500/20 rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] transition-all hover:bg-emerald-500 hover:text-white flex items-center justify-center gap-3 active:scale-95 disabled:opacity-50"
                  >
                    <Sparkles size={16} className={loading ? 'animate-spin' : ''}/> 
                    {t('Quick Demo Access', 'Gunakan Akses Demo')}
                  </button>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AuthGate;

