            <item.icon size={20} className={`transition-transform group-hover:scale-110 ${activeTab === item.id ? 'text-primary-500' : ''}`} />
            <span className="text-[0.7rem] font-black uppercase tracking-widest leading-none">{item.label}</span>
          </button>
        ))}
      </nav>
      <div className="pt-6 mt-6 border-t border-white/5 space-y-5">
