                   </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                   <StatCard label="Gross Written Premium" value={`Rp ${formatMoney(stats.totalPremium)}`} trend="+Live" icon={Wallet} color="bg-emerald-500/10 text-emerald-500" />
                   <StatCard label="Claims Matrix Flow" value={stats.claimCount} trend={`+${stats.claimCount}`} icon={Activity} color="bg-rose-500/10 text-rose-500" />
                   <StatCard label="Neural Engine Velocity" value="42.5s" trend="-2.4s" icon={Zap} color="bg-blue-500/10 text-blue-500" />
                </div>
                <BizAdminView section="transactions" isDashboard={true} userRole={userRole} />
