import { UserRole } from '../../types';
import { db } from '../../db';

const Badge = ({ children, color = "primary" }: { children?: React.ReactNode, color?: string }) => {
  const styles: any = {
    primary: "bg-primary-500/10 text-primary-500 border-primary-500/20",
    emerald: "bg-emerald-500/10 text-emerald-500 border-emerald-500/20",
    blue: "bg-blue-500/10 text-blue-500 border-blue-200",
    amber: "bg-amber-500/10 text-amber-600 border-amber-200",
  };
  return (
    <span className={`px-2 py-0.5 rounded-lg text-[0.45rem] font-black uppercase tracking-widest border ${styles[color] || styles.primary}`}>{children}</span>
  );
};

const StatCard = ({ label, value, trend, icon: Icon, color }: any) => (
  <div className="p-8 bg-white/[0.03] border border-white/5 rounded-[2.5rem] relative overflow-hidden backdrop-blur-sm group hover:border-primary-500/30 transition-all duration-500 shadow-xl">
    <div className="flex justify-between items-start mb-6">
      <div className={`w-12 h-12 rounded-2xl flex items-center justify-center shadow-inner ${color}`}>
        <Icon size={24} />
      </div>
      {trend && (
        <div className={`flex items-center gap-1 text-[0.65rem] font-black ${trend.startsWith('+') ? 'text-emerald-500' : 'text-rose-500'}`}>
          {trend} <ArrowUpRight size={14} className={trend.startsWith('-') ? 'rotate-90' : ''} />
        </div>
      )}
    </div>
    <p className="text-3xl font-black tracking-tighter leading-none mb-2">{value}</p>
    <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest">{label}</p>
  </div>
);

const AdminPortal = ({ onLogout, products, setProducts, userRole }: { onLogout: () => void, products: any[], setProducts: any, userRole: UserRole }) => {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [isProfileOpen, setIsProfileOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);

  const [stats, setStats] = useState({
    userCount: 0,
    policyCount: 0,
    claimCount: 0,
    totalPremium: 0
  });

  const fetchStats = async () => {
      const u = await db.users.count();
      const p = await db.policies.count();
      const c = await db.claims.count();
      const allPolicies = await db.policies.toArray();
      const total = allPolicies.reduce((acc, curr) => acc + curr.premium, 0);

      setStats({
          userCount: u,
          policyCount: p,
          claimCount: c,
          totalPremium: total
      });
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    fetchStats();
    const interval = setInterval(fetchStats, 10000);
    return () => {
      window.removeEventListener('resize', handleResize);
      clearInterval(interval);
    }
  }, []);

  const getMenuItems = () => {
    const common = [{ id: 'dashboard', label: 'Dasbor Utama', icon: LayoutDashboard }];
    const masterItems = [
      { id: 'security', label: 'Neural Guard (Master)', icon: ShieldAlert },
      { id: 'approvals', label: 'Semua Persetujuan', icon: ClipboardCheck },
      { id: 'claims', label: 'Monitoring Klaim', icon: Activity },
      { id: 'users', label: 'Direktori Pengguna', icon: Users },
      { id: 'settings', label: 'Registri Inti', icon: Settings },
    ];
    const surepathAdminItems = [
      { id: 'approvals', label: 'Manajemen Polis', icon: ClipboardCheck },
      { id: 'claims', label: 'Log Klaim AI', icon: Activity },
      { id: 'users', label: 'Manajemen Pengguna', icon: UserCheck },
      { id: 'transactions', label: 'Traffic Jaringan', icon: Zap },
    ];
    const insuranceAdminItems = [
      { id: 'approvals', label: 'Aplikasi Baru', icon: FileText },
      { id: 'claims', label: 'Antrean Klaim', icon: Activity },
      { id: 'inventory', label: 'Katalog Produk', icon: Building2 },
    ];
    const financeItems = [
      { id: 'ledger', label: 'Buku Besar Keuangan', icon: FileText },
      { id: 'claims', label: 'Pencairan Klaim', icon: Activity },
      { id: 'wallet', label: 'Vault Modal', icon: Wallet },
      { id: 'approvals', label: 'Audit Pembayaran', icon: ClipboardCheck },
    ];
    switch (userRole) {
      case UserRole.MASTER_ADMIN: return [...common, ...masterItems];
      case UserRole.ADMIN: return [...common, ...surepathAdminItems];
      case UserRole.INSURANCE_ADMIN: return [...common, ...insuranceAdminItems];
      case UserRole.FINANCE: return [...common, ...financeItems];
      default: return common;
    }
  };

  const SidebarContent = () => (
    <div className="flex flex-col h-full">
      <div className="flex items-center gap-3 mb-12 px-2">
        <div className="w-12 h-12 bg-primary-500 rounded-[1.2rem] flex items-center justify-center shadow-lg border border-primary-400/20"><ShieldCheck size={28} className="text-white" /></div>
        <div>
          <h1 className="font-black text-2xl tracking-tighter uppercase leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <span className="text-[0.45rem] font-bold text-emerald-500 uppercase tracking-[0.4em] mt-1 flex items-center gap-2">
             <div className="w-1 h-1 rounded-full bg-emerald-500 animate-pulse"></div> COMMAND HQ
          </span>
        </div>
      </div>
      <nav className="flex-1 space-y-2 overflow-y-auto no-scrollbar">
        {getMenuItems().map((item) => (
          <button key={item.id} onClick={() => { setActiveTab(item.id); setMobileMenuOpen(false); }} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl transition-all group ${activeTab === item.id ? 'bg-primary-500/10 text-primary-500 border border-primary-500/20 shadow-lg' : 'text-slate-500 hover:text-slate-200 hover:bg-white/5'}`}>
            <item.icon size={20} className={`transition-transform group-hover:scale-110 ${activeTab === item.id ? 'text-primary-500' : ''}`} />
            <span className="text-[0.7rem] font-black uppercase tracking-widest leading-none">{item.label}</span>
          </button>
        ))}
      </nav>
      <div className="pt-6 mt-6 border-t border-white/5 space-y-5">
        <div className="p-5 bg-white/5 rounded-[2rem] border border-white/5 relative overflow-hidden group">
           <div className="absolute top-0 right-0 p-4 opacity-5"><Server size={60}/></div>
           <p className="text-[0.5rem] font-black text-gray-500 uppercase tracking-widest mb-2">Authenticated As</p>
           <div className="flex items-center gap-3">
              <div className="w-8 h-8 rounded-lg bg-primary-500 flex items-center justify-center font-black text-xs">{userRole[0]}</div>
              <p className="text-[0.65rem] font-black uppercase text-white tracking-widest truncate">{userRole.replace('_', ' ')}</p>
           </div>
        </div>
        <button onClick={onLogout} className="w-full flex items-center gap-4 px-6 py-4 rounded-2xl text-rose-500 hover:bg-rose-500 hover:text-white transition-all font-black uppercase text-[0.6rem] tracking-[0.2em] bg-rose-500/10 border border-rose-500/20">
           <LogOut size={18} /> KELUAR SISTEM
        </button>
      </div>
    </div>
  );

  const formatMoney = (n: number) => new Intl.NumberFormat('id-ID', { notation: "compact", compactDisplay: "short" }).format(n);

  return (
    <div className="flex h-screen bg-[#050505] text-white overflow-hidden font-sans">
      {!isMobile && <aside className="w-80 border-r border-white/5 bg-black/40 backdrop-blur-xl flex flex-col p-8 flex-shrink-0 shadow-2xl"><SidebarContent /></aside>}
      {isMobile && mobileMenuOpen && (
        <div className="fixed inset-0 z-[100] animate-fade-in">
           <div className="absolute inset-0 bg-black/80 backdrop-blur-md" onClick={() => setMobileMenuOpen(false)}></div>
           <aside className="absolute top-0 left-0 bottom-0 w-80 bg-[#0a0a0a] border-r border-white/10 p-8 flex flex-col animate-slide-right"><SidebarContent /></aside>
        </div>
      )}
      <main className="flex-1 flex flex-col min-w-0 bg-grid-pattern relative overflow-hidden">

        {/* Ambient background effect */}
        <div className="absolute top-[-10%] left-[-5%] w-[60%] h-[40%] bg-primary-500/5 blur-[120px] rounded-full pointer-events-none"></div>

        <header className="h-20 border-b border-white/5 flex items-center justify-between px-6 lg:px-10 bg-black/20 backdrop-blur-md z-20">
          <div className="flex items-center gap-4 lg:gap-6 flex-1">
            {isMobile && <button onClick={() => setMobileMenuOpen(true)} className="p-3 bg-white/5 rounded-xl text-gray-400"><Menu size={20} /></button>}
            <div className="relative w-full max-w-md hidden md:block">
              <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-500" size={18} />
              <input type="text" placeholder="Scan database neural..." className="w-full bg-white/5 border border-white/10 rounded-2xl py-3.5 pl-12 pr-4 text-xs outline-none focus:border-primary-500/50 transition-all font-medium" />
            </div>
          </div>
          <div className="flex items-center gap-3 lg:gap-6">
            <div className="hidden sm:flex items-center gap-3 mr-4">
               <div className="flex flex-col items-end">
                  <span className="text-[0.55rem] font-black text-emerald-500 tracking-widest">SISTEM AKTIF</span>
                  <span className="text-[0.5rem] font-bold text-gray-500">JKT-NODE-01</span>
               </div>
               <div className="w-2 h-2 rounded-full bg-emerald-500 animate-ping"></div>
            </div>
            <button onClick={fetchStats} className="p-3 text-gray-400 hover:text-white bg-white/5 rounded-xl transition-all active:rotate-180 duration-700 hover:bg-white/10 shadow-inner border border-white/5"><RefreshCw size={20} /></button>
            <div className="relative">
              <button onClick={() => setIsProfileOpen(!isProfileOpen)} className="flex items-center gap-3 pl-2 pr-3 py-2 bg-white/5 rounded-2xl border border-white/5 hover:border-white/10 transition-all active:scale-95">
                <div className="w-9 h-9 rounded-xl bg-gradient-to-tr from-primary-600 to-primary-400 flex items-center justify-center font-black text-xs shadow-xl uppercase border border-white/20">{userRole[0]}</div>
                <ChevronDown size={14} className={`text-gray-500 transition-transform ${isProfileOpen ? 'rotate-180' : ''}`} />
              </button>
              {isProfileOpen && (
                <div className="absolute right-0 mt-3 w-56 bg-[#111] border border-white/10 rounded-3xl shadow-2xl p-2 z-50 animate-pop-in overflow-hidden">
                  <div className="p-4 border-b border-white/5 mb-1 bg-white/5">
                     <p className="text-[0.5rem] font-black text-gray-500 uppercase tracking-widest">Profile Hub</p>
                     <p className="text-xs font-bold text-white mt-1 uppercase">{userRole.replace('_', ' ')}</p>
                  </div>
                  <button onClick={onLogout} className="w-full flex items-center gap-3 px-4 py-4 rounded-2xl text-rose-500 hover:bg-rose-500/10 text-[0.65rem] font-black uppercase tracking-[0.2em]"><LogOut size={16}/> Sign Out</button>
                </div>
              )}
            </div>
          </div>
        </header>

        <div className="flex-1 overflow-y-auto p-6 lg:p-12 no-scrollbar relative z-10">
          <div className="max-w-7xl mx-auto space-y-12">
            {activeTab === 'dashboard' && (
              <div className="animate-fade-in space-y-12">
                <div className="flex flex-col lg:flex-row justify-between items-start lg:items-end gap-6">
                   <div className="space-y-2">
                      <div className="flex items-center gap-3 text-primary-500">
                         <Terminal size={18}/>
                         <p className="text-[0.75rem] font-black uppercase tracking-[0.4em]">Neural Control Interface</p>
                      </div>
                      <h2 className="text-4xl lg:text-6xl font-black uppercase tracking-tighter leading-none">Global <span className="text-gray-600">Overview</span></h2>
                   </div>
                   <div className="flex gap-3">
                      {/* Fixed: Download icon was missing from lucide-react imports */}
                      <button className="px-6 py-3 bg-white/5 rounded-2xl text-[0.65rem] font-black uppercase tracking-widest border border-white/10 hover:bg-white/10 transition-all flex items-center gap-2"><Download size={16}/> Report PDF</button>
                   </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                   <StatCard label="Gross Written Premium" value={`Rp ${formatMoney(stats.totalPremium)}`} trend="+Live" icon={Wallet} color="bg-emerald-500/10 text-emerald-500" />
                   <StatCard label="Claims Matrix Flow" value={stats.claimCount} trend={`+${stats.claimCount}`} icon={Activity} color="bg-rose-500/10 text-rose-500" />
                   <StatCard label="Neural Engine Velocity" value="42.5s" trend="-2.4s" icon={Zap} color="bg-blue-500/10 text-blue-500" />
                </div>
                <BizAdminView section="transactions" isDashboard={true} userRole={userRole} />
              </div>
            )}
            {activeTab === 'users' && <BizAdminView section="users" userRole={userRole} />}
            {activeTab === 'security' && <SecurityView />}
            {activeTab === 'approvals' && <ApprovalsView />}
            {activeTab === 'claims' && <ClaimsListView />}
            {activeTab === 'inventory' && <InventoryView />}
            {activeTab === 'settings' && <SettingsView products={products} setProducts={setProducts} />}
          </div>
        </div>
      </main>
    </div>
  );
};

export default AdminPortal;

import React, { useState } from 'react';
import { 
  ShieldCheck, Car, Smartphone, Shield, 
  AlertCircle, Hash, Palette, User, FileText, 
  Scale, Building2, Wallet, Zap, Layers,
  CheckCircle2, Plus, Package, Calendar, Users,
  BadgePercent, ArrowDown, FileDown, Loader2,
  Info, ClipboardList, ChevronDown
} from 'lucide-react';
import { formatIDR, Badge } from './WizardUI';
import { jsPDF } from 'jspdf';

interface StepPreSummaryProps {
  vehicle: any;
  coverage: any;
  premiumBreakdown: any;
  showBreakdown: boolean;
  setShowBreakdown: (b: boolean) => void;
  stnkResult: any;
  kycData: any;
}

const StepPreSummary: React.FC<StepPreSummaryProps> = ({
  vehicle, coverage, premiumBreakdown, showBreakdown, setShowBreakdown, stnkResult, kycData
}) => {
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const activeExpansions = [
    { id: 'authorized', label: 'Bengkel Resmi', active: coverage.authorized },
    { id: 'flood', label: 'Banjir & Badai', active: coverage.flood },
    { id: 'earthquake', label: 'Gempa & Tsunami', active: coverage.earthquake },
    { id: 'srcc', label: 'Kerusuhan (SRCC)', active: coverage.srcc },
    { id: 'terrorism', label: 'Terorisme & Sabotase', active: coverage.terrorism },
  ].filter(e => e.active);

  const InfoRow = ({ label, value, icon: Icon, color = "text-primary-500", mono = false }: any) => (
    <div className="flex justify-between items-center py-3.5 border-b border-black/5 dark:border-white/5 last:border-0">
      <div className="flex items-center gap-3">
        <Icon size={14} className={`${color} opacity-70`} />
        <span className="text-[0.65rem] font-bold uppercase text-gray-400 tracking-wider">{label}</span>
      </div>
      <span className={`text-[0.75rem] font-black uppercase text-slate-900 dark:text-gray-200 ${mono ? 'font-mono text-primary-500' : ''}`}>
        {value || '-'}
      </span>
    </div>
  );

  const generatePDF = async () => {
    setIsGeneratingPdf(true);
    try {
      const doc = new jsPDF('p', 'mm', 'a4');
      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const margin = 15;
      const contentWidth = pageWidth - (margin * 2);

      const primaryColor = [249, 115, 22]; // #f97316
      const secondaryColor = [15, 23, 42]; // #0f172a
      const accentColor = [16, 185, 129]; // #10b981
      const grayColor = [100, 116, 139]; // #64748b

      // 1. HEADER BRANDING
      doc.setFillColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
      doc.rect(0, 0, pageWidth, 55, 'F');

      // Abstract background element in header
      doc.setFillColor(30, 41, 59);
      doc.polygon([[pageWidth - 60, 0], [pageWidth, 0], [pageWidth, 55], [pageWidth - 30, 55]], 'F');

      doc.setTextColor(255, 255, 255);
      doc.setFontSize(28);
      doc.setFont('helvetica', 'bold');
      doc.text("SurePath", margin, 25);

      doc.setFontSize(9);
      doc.setFont('helvetica', 'normal');
      doc.text("AI-First Insurtech Distribution Ecosystem", margin, 32);
      doc.text("Certified Neutral Protection Registry", margin, 36);

      const today = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
      doc.setFontSize(8);
      doc.text(`ISSUED ON: ${today.toUpperCase()}`, pageWidth - margin, 25, { align: 'right' });
      doc.text(`QUOTE REF: SPQ-${Date.now().toString().slice(-8)}`, pageWidth - margin, 30, { align: 'right' });

      // AI Seal / Badge
      doc.setDrawColor(accentColor[0], accentColor[1], accentColor[2]);
      doc.setFillColor(accentColor[0], accentColor[1], accentColor[2], 0.1);
      doc.setLineWidth(0.5);
      doc.circle(pageWidth - margin - 15, 42, 8, 'FD');
      doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
      doc.setFontSize(6);
      doc.setFont('helvetica', 'bold');
      doc.text("NEURAL", pageWidth - margin - 15, 41, { align: 'center' });
      doc.text("VERIFIED", pageWidth - margin - 15, 44, { align: 'center' });

      // 2. MAIN TITLE
      doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
      doc.setFontSize(16);
      doc.setFont('helvetica', 'bold');
      doc.text("OFFICIAL QUOTE PROPOSAL", margin, 70);
      doc.setDrawColor(primaryColor[0], primaryColor[1], primaryColor[2]);
      doc.setLineWidth(1.5);
      doc.line(margin, 73, margin + 40, 73);

      let currentY = 85;

      // 3. SECTION BLOCKS HELPERS
      const drawSectionCard = (y: number, title: string, height: number) => {
        doc.setFillColor(250, 250, 250);
        doc.setDrawColor(230, 230, 230);
        doc.roundedRect(margin, y, contentWidth, height, 4, 4, 'FD');

        doc.setFillColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
        doc.roundedRect(margin, y, 40, 7, 2, 2, 'F');
        doc.setTextColor(255, 255, 255);
        doc.setFontSize(7);
        doc.setFont('helvetica', 'bold');
        doc.text(title.toUpperCase(), margin + 20, y + 4.5, { align: 'center' });
      };

      const drawDataRow = (y: number, label: string, value: string, isMono = false) => {
        doc.setTextColor(grayColor[0], grayColor[1], grayColor[2]);
        doc.setFontSize(8);
        doc.setFont('helvetica', 'bold');
        doc.text(label.toUpperCase(), margin + 5, y);

        doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
        doc.setFontSize(9);
        if (isMono) {
          doc.setFont('courier', 'bold');
          doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        } else {
          doc.setFont('helvetica', 'bold');
        }
        doc.text(value || '-', pageWidth - margin - 5, y, { align: 'right' });
      };

      // SECTION: CLIENT NODE
      drawSectionCard(currentY, "Subscriber Node", 35);
      currentY += 15;
      drawDataRow(currentY, "Primary Name", kycData?.name);
      currentY += 8;
      drawDataRow(currentY, "Identity ID (NIK)", kycData?.ktp || '-');
      currentY += 8;
      drawDataRow(currentY, "Contact Email", kycData?.email || '-');
      currentY += 15;

      // SECTION: ASSET CORE
      drawSectionCard(currentY, "Hardware Registry", 50);
      currentY += 15;
      drawDataRow(currentY, "Brand & Model", `${vehicle.brand} ${vehicle.model}`);
      currentY += 8;
      drawDataRow(currentY, "Manufacture Year", `${vehicle.year}`);
      currentY += 8;
      drawDataRow(currentY, "License Plate", vehicle.plate, true);
      currentY += 8;
      drawDataRow(currentY, "VIN / Chassis", vehicle.vin || '-', true);
      currentY += 8;
      drawDataRow(currentY, "Engine Node ID", vehicle.engine || '-', true);
      currentY += 15;

      // SECTION: PROTECTION MATRIX
      const expHeight = 25 + (activeExpansions.length * 6);
      drawSectionCard(currentY, "Policy Matrix", expHeight);
      currentY += 15;
      drawDataRow(currentY, "Protection Core", coverage.type);
      currentY += 10;
      doc.setTextColor(grayColor[0], grayColor[1], grayColor[2]);
      doc.setFontSize(7);
      doc.text("ACTIVE ADD-ONS & EXPANSIONS:", margin + 5, currentY);
      currentY += 5;

      doc.setFontSize(8);
      doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
      if (activeExpansions.length === 0 && coverage.tpl === 0) {
        doc.text("- Standard Coverage Only", margin + 10, currentY);
        currentY += 6;
      } else {
        activeExpansions.forEach(e => {
          doc.text(`+ ${e.label}`, margin + 10, currentY);
          currentY += 5;
        });
        if (coverage.tpl > 0) {
          doc.text(`+ TPL Limit: ${formatIDR(coverage.tpl)}`, margin + 10, currentY);
          currentY += 5;
        }
      }
      currentY += 12;

      // 4. FINANCIAL LEDGER
      doc.setFillColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
      doc.roundedRect(margin, currentY, contentWidth, 75, 6, 6, 'F');

      doc.setTextColor(255, 255, 255);
      doc.setFontSize(11);
      doc.text("FINANCIAL SUMMARY", margin + 10, currentY + 12);
      doc.setDrawColor(255, 255, 255, 0.2);
      doc.line(margin + 10, currentY + 16, pageWidth - margin - 10, currentY + 16);

      let calcY = currentY + 25;
      const drawLedgerRow = (y: number, label: string, val: number, isDiscount = false) => {
        doc.setFontSize(8);
        doc.setTextColor(200, 200, 200);
        doc.text(label, margin + 12, y);
        if (isDiscount) doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
        else doc.setTextColor(255, 255, 255);
        doc.text(isDiscount ? `-${formatIDR(val)}` : formatIDR(val), pageWidth - margin - 12, y, { align: 'right' });
      };

      drawLedgerRow(calcY, "Basic Policy Premium", premiumBreakdown?.basicPremium || 0);
      calcY += 7;

      const expansionsVal = (premiumBreakdown?.grossPremium || 0) - (premiumBreakdown?.basicPremium || 0);
      drawLedgerRow(calcY, "Expansion loadings & TPL", expansionsVal);
      calcY += 7;

      drawLedgerRow(calcY, "Administrative & OJK Fees", (premiumBreakdown?.adminFee || 0) + (premiumBreakdown?.stampDuty || 0));
      calcY += 10;

      if (premiumBreakdown?.discountAmount > 0) {
        drawLedgerRow(calcY, `Commission Discount (${premiumBreakdown.discountPercent}%)`, premiumBreakdown.discountAmount, true);
        calcY += 10;
      }

      doc.setDrawColor(255, 255, 255, 0.1);
      doc.line(margin + 12, calcY - 2, pageWidth - margin - 12, calcY - 2);

      doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
      doc.setFontSize(10);
      doc.text("TOTAL NET PAYABLE", margin + 12, calcY + 8);
      doc.setFontSize(18);
      doc.text(formatIDR(premiumBreakdown?.totalPayable || 0), pageWidth - margin - 12, calcY + 10, { align: 'right' });

      // 5. FOOTER & LEGAL
      doc.setTextColor(grayColor[0], grayColor[1], grayColor[2]);
      doc.setFontSize(7);
      doc.setFont('helvetica', 'italic');
      const footerY = pageHeight - 20;
      doc.text("Dokumen ini dihasilkan secara otomatis oleh sistem SurePath Neural Engine dan berlaku sebagai rujukan resmi.", pageWidth / 2, footerY, { align: 'center' });
      doc.text("SurePath Insurtech terdaftar dan diawasi oleh Otoritas Jasa Keuangan (OJK) Republik Indonesia.", pageWidth / 2, footerY + 4, { align: 'center' });

      // Save
      doc.save(`SurePath_Quote_${vehicle.plate.replace(/\s/g, '_')}.pdf`);
    } catch (error) {
      console.error("PDF generation error:", error);
