import React, { useState } from 'react';
import { 
  ShieldCheck, Car, Smartphone, Shield, 
  AlertCircle, Hash, Palette, User, FileText, 
  Scale, Building2, Wallet, Zap, Layers,
  CheckCircle2, Plus, Package, Calendar, Users,
  BadgePercent, ArrowDown, FileDown, Loader2,
  Info, ClipboardList, ChevronDown
} from 'lucide-react';
import { formatIDR, Badge } from './WizardUI';
import { jsPDF } from 'jspdf';

interface StepPreSummaryProps {
  vehicle: any;
  coverage: any;
  premiumBreakdown: any;
  showBreakdown: boolean;
  setShowBreakdown: (b: boolean) => void;
  stnkResult: any;
  kycData: any;
}

const StepPreSummary: React.FC<StepPreSummaryProps> = ({
  vehicle, coverage, premiumBreakdown, showBreakdown, setShowBreakdown, stnkResult, kycData
}) => {
  const [isGeneratingPdf, setIsGeneratingPdf] = useState(false);

  const activeExpansions = [
    { id: 'authorized', label: 'Bengkel Resmi', active: coverage?.authorized },
    { id: 'flood', label: 'Banjir & Badai', active: coverage?.flood },
    { id: 'earthquake', label: 'Gempa & Tsunami', active: coverage?.earthquake },
    { id: 'srcc', label: 'Kerusuhan (SRCC)', active: coverage?.srcc },
    { id: 'terrorism', label: 'Terorisme & Sabotase', active: coverage?.terrorism },
  ].filter(e => e.active);

  const InfoRow = ({ label, value, icon: Icon, color = "text-primary-500", mono = false }: any) => (
    <div className="flex justify-between items-center py-3.5 border-b border-black/5 dark:border-white/5 last:border-0">
      <div className="flex items-center gap-3">
        <Icon size={14} className={`${color} opacity-70`} />
        <span className="text-[0.65rem] font-bold uppercase text-gray-400 tracking-wider">{label}</span>
      </div>
      <span className={`text-[0.75rem] font-black uppercase text-slate-900 dark:text-gray-200 ${mono ? 'font-mono text-primary-500' : ''}`}>
        {value || '-'}
      </span>
    </div>
  );

  const generatePDF = async () => {
    if (isGeneratingPdf) return;
    setIsGeneratingPdf(true);

    try {
      // Initialize A4 PDF
      const doc = new jsPDF({
        orientation: 'p',
        unit: 'mm',
        format: 'a4',
        putOnlyUsedFonts: true
      });

      const pageWidth = doc.internal.pageSize.getWidth();
      const pageHeight = doc.internal.pageSize.getHeight();
      const margin = 15;
      const contentWidth = pageWidth - (margin * 2);

      const primaryColor = [249, 115, 22]; // #f97316
      const secondaryColor = [15, 23, 42]; // #0f172a
      const accentColor = [16, 185, 129]; // #10b981
      const grayColor = [100, 116, 139]; // #64748b

      // 1. HEADER BRANDING
      doc.setFillColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
      doc.rect(0, 0, pageWidth, 55, 'F');

      // Decorative elements (Safe rects instead of complex polygons)
      doc.setFillColor(30, 41, 59);
      doc.rect(pageWidth - 40, 0, 40, 55, 'F');

      doc.setTextColor(255, 255, 255);
      doc.setFontSize(28);
      doc.setFont('helvetica', 'bold');
      doc.text("SurePath", margin, 25);

      doc.setFontSize(9);
      doc.setFont('helvetica', 'normal');
      doc.text("AI-First Insurtech Distribution Ecosystem", margin, 32);
      doc.text("Certified Neutral Protection Registry", margin, 36);

      const today = new Date().toLocaleDateString('id-ID', { day: 'numeric', month: 'long', year: 'numeric' });
      doc.setFontSize(8);
      doc.text(`ISSUED ON: ${today.toUpperCase()}`, pageWidth - margin, 25, { align: 'right' });
      doc.text(`QUOTE REF: SPQ-${Date.now().toString().slice(-8)}`, pageWidth - margin, 30, { align: 'right' });

      // AI Seal
      doc.setDrawColor(accentColor[0], accentColor[1], accentColor[2]);
      doc.setFillColor(accentColor[0], accentColor[1], accentColor[2]);
      doc.setLineWidth(0.5);
      doc.circle(pageWidth - margin - 15, 42, 8, 'S');
      doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
      doc.setFontSize(6);
      doc.setFont('helvetica', 'bold');
      doc.text("NEURAL", pageWidth - margin - 15, 41, { align: 'center' });
      doc.text("VERIFIED", pageWidth - margin - 15, 44, { align: 'center' });

      // 2. MAIN TITLE
      doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
      doc.setFontSize(16);
      doc.setFont('helvetica', 'bold');
      doc.text("OFFICIAL QUOTE PROPOSAL", margin, 70);
      doc.setDrawColor(primaryColor[0], primaryColor[1], primaryColor[2]);
      doc.setLineWidth(1.5);
      doc.line(margin, 73, margin + 40, 73);

      let currentY = 85;

      // Helper for sections
      const drawSectionCard = (y: number, title: string, height: number) => {
        doc.setFillColor(250, 250, 250);
        doc.setDrawColor(230, 230, 230);
        // Correct jspdf roundedRect parameters
        doc.roundedRect(margin, y, contentWidth, height, 4, 4, 'FD');

        doc.setFillColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
        doc.roundedRect(margin, y, 40, 7, 2, 2, 'F');
        doc.setTextColor(255, 255, 255);
        doc.setFontSize(7);
        doc.setFont('helvetica', 'bold');
        doc.text(title.toUpperCase(), margin + 20, y + 4.5, { align: 'center' });
      };

      const drawDataRow = (y: number, label: string, value: string, isMono = false) => {
        doc.setTextColor(grayColor[0], grayColor[1], grayColor[2]);
        doc.setFontSize(8);
        doc.setFont('helvetica', 'bold');
        doc.text(label.toUpperCase(), margin + 5, y);

        doc.setTextColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
        doc.setFontSize(9);
        if (isMono) {
          doc.setFont('courier', 'bold');
          doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
        } else {
          doc.setFont('helvetica', 'bold');
        }
        doc.text(value || '-', pageWidth - margin - 5, y, { align: 'right' });
      };

      // SECTION: CLIENT NODE
      drawSectionCard(currentY, "Subscriber Node", 35);
      currentY += 15;
      drawDataRow(currentY, "Primary Name", kycData?.name || 'Guest');
      currentY += 8;
      drawDataRow(currentY, "Identity ID (NIK)", kycData?.ktp || '-');
      currentY += 8;
      drawDataRow(currentY, "Contact Email", kycData?.email || '-');
      currentY += 15;

      // SECTION: ASSET CORE
      drawSectionCard(currentY, "Hardware Registry", 50);
      currentY += 15;
      drawDataRow(currentY, "Brand & Model", `${vehicle?.brand || '-'} ${vehicle?.model || '-'}`);
      currentY += 8;
      drawDataRow(currentY, "Manufacture Year", `${vehicle?.year || '-'}`);
      currentY += 8;
      drawDataRow(currentY, "License Plate", vehicle?.plate || '-', true);
      currentY += 8;
      drawDataRow(currentY, "VIN / Chassis", vehicle?.vin || '-', true);
      currentY += 8;
      drawDataRow(currentY, "Engine Node ID", vehicle?.engine || '-', true);
      currentY += 15;

      // SECTION: PROTECTION MATRIX
      const expCount = activeExpansions.length + (coverage?.tpl > 0 ? 1 : 0);
      const expHeight = 25 + (expCount * 6);
      drawSectionCard(currentY, "Policy Matrix", expHeight);
      currentY += 15;
      drawDataRow(currentY, "Protection Core", coverage?.type || '-');
      currentY += 10;
      doc.setTextColor(grayColor[0], grayColor[1], grayColor[2]);
      doc.setFontSize(7);
      doc.text("ACTIVE ADD-ONS & EXPANSIONS:", margin + 5, currentY);
      currentY += 5;

      doc.setFontSize(8);
      doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
      if (expCount === 0) {
        doc.text("- Standard Coverage Only", margin + 10, currentY);
        currentY += 6;
      } else {
        activeExpansions.forEach(e => {
          doc.text(`+ ${e.label}`, margin + 10, currentY);
          currentY += 5;
        });
        if (coverage?.tpl > 0) {
          doc.text(`+ TPL Limit: ${formatIDR(coverage.tpl)}`, margin + 10, currentY);
          currentY += 5;
        }
      }
      currentY += 12;

      // 4. FINANCIAL LEDGER
      if (premiumBreakdown) {
          doc.setFillColor(secondaryColor[0], secondaryColor[1], secondaryColor[2]);
          doc.roundedRect(margin, currentY, contentWidth, 75, 6, 6, 'F');

          doc.setTextColor(255, 255, 255);
          doc.setFontSize(11);
          doc.text("FINANCIAL SUMMARY", margin + 10, currentY + 12);
          doc.setDrawColor(255, 255, 255);
          doc.setLineWidth(0.1);
          doc.line(margin + 10, currentY + 16, pageWidth - margin - 10, currentY + 16);

          let calcY = currentY + 25;
          const drawLedgerRow = (y: number, label: string, val: number, isDiscount = false) => {
            doc.setFontSize(8);
            doc.setTextColor(200, 200, 200);
            doc.text(label, margin + 12, y);
            if (isDiscount) doc.setTextColor(accentColor[0], accentColor[1], accentColor[2]);
            else doc.setTextColor(255, 255, 255);
            doc.text(isDiscount ? `-${formatIDR(val)}` : formatIDR(val), pageWidth - margin - 12, y, { align: 'right' });
          };

          drawLedgerRow(calcY, "Basic Policy Premium", premiumBreakdown.basicPremium || 0);
          calcY += 7;

          const expansionsVal = (premiumBreakdown.grossPremium || 0) - (premiumBreakdown.basicPremium || 0);
          drawLedgerRow(calcY, "Expansion loadings & TPL", expansionsVal);
          calcY += 7;

          drawLedgerRow(calcY, "Administrative & OJK Fees", (premiumBreakdown.adminFee || 0) + (premiumBreakdown.stampDuty || 0));
          calcY += 10;

          if (premiumBreakdown.discountAmount > 0) {
            drawLedgerRow(calcY, `Commission Discount (${premiumBreakdown.discountPercent}%)`, premiumBreakdown.discountAmount, true);
            calcY += 10;
          }

          doc.setDrawColor(255, 255, 255);
          doc.line(margin + 12, calcY - 2, pageWidth - margin - 12, calcY - 2);

          doc.setTextColor(primaryColor[0], primaryColor[1], primaryColor[2]);
          doc.setFontSize(10);
          doc.text("TOTAL NET PAYABLE", margin + 12, calcY + 8);
          doc.setFontSize(18);
          doc.text(formatIDR(premiumBreakdown.totalPayable || 0), pageWidth - margin - 12, calcY + 10, { align: 'right' });
      }

      // 5. FOOTER
      doc.setTextColor(grayColor[0], grayColor[1], grayColor[2]);
      doc.setFontSize(7);
      doc.setFont('helvetica', 'italic');
      const footerY = pageHeight - 20;
      doc.text("Dokumen ini dihasilkan secara otomatis oleh sistem SurePath Neural Engine.", pageWidth / 2, footerY, { align: 'center' });
      doc.text("SurePath Insurtech terdaftar dan diawasi oleh OJK Republik Indonesia.", pageWidth / 2, footerY + 4, { align: 'center' });

      // Save the PDF
      doc.save(`SurePath_Quote_${(vehicle?.plate || 'Unit').replace(/\s/g, '_')}.pdf`);

    } catch (error) {
      console.error("PDF generation failed:", error);
      alert("Maaf, sistem gagal membuat PDF. Mohon coba lagi atau hubungi support.");
    } finally {
      setIsGeneratingPdf(false);
    }
  };

  return (
    <div className="space-y-6 animate-fade-in pb-10">
       <div className="px-2 flex justify-between items-end">
          <div>
            <h2 className="text-2xl font-black uppercase tracking-tighter text-slate-900 dark:text-white">Cek <span className="text-primary-500">Pesananmu</span></h2>
            <p className="text-[0.65rem] text-gray-500 font-bold uppercase tracking-widest mt-1">Reviewing Data Consistency...</p>
          </div>

          <button 
            onClick={generatePDF}
            disabled={isGeneratingPdf}
            className="flex items-center gap-3 px-5 py-2.5 bg-white dark:bg-white/5 border border-black/5 dark:border-white/10 rounded-2xl text-[0.65rem] font-black uppercase tracking-widest hover:bg-primary-500 hover:text-white transition-all shadow-xl active:scale-95 disabled:opacity-50"
          >
            {isGeneratingPdf ? <Loader2 size={16} className="animate-spin text-primary-500"/> : <FileDown size={16}/>}
            {isGeneratingPdf ? 'Syncing...' : 'Simpan PDF'}
          </button>
       </div>

       {/* DATA MOBIL CARD */}
       <div className="p-8 bg-white dark:bg-white/5 rounded-[3rem] border border-black/5 dark:border-white/5 shadow-xl relative overflow-hidden group">
          <div className="absolute top-0 right-0 p-8 opacity-[0.03] rotate-12 group-hover:rotate-0 transition-transform duration-1000">
