import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, Eye, EyeOff, Radio, Fingerprint, Sparkles, Activity,
  BellRing, X, RefreshCw, Smartphone, BadgeCheck, KeyRound, 
  Zap, ShieldCheck, Globe, AlertCircle, Shield, Terminal,
  Lock, Building2, UserCheck, ShieldAlert
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, User as DBUser } from '../db';
import { hashPassword, verifyPassword, validatePasswordStrength, REGEX } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
}

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [targetRole, setTargetRole] = useState<UserRole>(UserRole.CUSTOMER);
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [lang, setLang] = useState<Language>(initialLang);

  const [formData, setFormData] = useState({ 
    name: '', 
    email: '', 
    phone: '', 
    password: '',
    adminKey: '' // Key for admin registration
  });

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  // Constants
  const ADMIN_ACCESS_KEY = "SUREPATH-ADMIN-2025";

  // Real-time Validation
  const passwordStrength = useMemo(() => validatePasswordStrength(formData.password), [formData.password]);
  const isEmailValid = useMemo(() => REGEX.EMAIL.test(formData.email), [formData.email]);
  const isPhoneValid = useMemo(() => REGEX.PHONE.test(formData.phone), [formData.phone]);

  const canRegister = useMemo(() => {
      const basic = formData.name.length > 2 && isEmailValid && isPhoneValid && passwordStrength.score === 4;
      if (targetRole === UserRole.ADMIN) {
        return basic && formData.adminKey === ADMIN_ACCESS_KEY;
      }
      return basic;
  }, [formData.name, isEmailValid, isPhoneValid, passwordStrength, targetRole, formData.adminKey]);

  const canLogin = useMemo(() => {
      return isEmailValid && formData.password.length > 0;
  }, [isEmailValid, formData.password]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'REGISTER' && !canRegister) return;
    if (mode === 'LOGIN' && !canLogin) return;

    setLoading(true);
    setError(null);

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            onAuthSuccess(user);
          } else {
            setError(t("Invalid password.", "Password salah."));
            setLoading(false);
          }
        } else {
          setError(t("Account not found.", "Akun tidak terdaftar."));
          setLoading(false);
        }
      } else {
        // Simple OTP Simulation
        const newOtp = "123456";
        setGeneratedOtp(newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
        }, 1000);
      }
    } catch (err) {
      setError(t("System error.", "Kegagalan sistem."));
      setLoading(false);
    }
  };

  const finalizeRegistration = async () => {
    if (otp !== generatedOtp) {
      setError(t("Invalid code.", "Kode OTP salah."));
      return;
    }

    setLoading(true);
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: targetRole,
        nodeId: `SP-${targetRole === UserRole.ADMIN ? 'ADM' : 'USR'}-${Math.floor(1000 + Math.random() * 9000)}`,
        verified: true,
        trustScore: targetRole === UserRole.ADMIN ? 100 : 85,
        memberSince: new Date().toISOString()
      };
      const id = await db.users.add(newUser);
      onAuthSuccess({ ...newUser, id });
    } catch (err) {
      setError("Registration failed.");
      setLoading(false);
    }
  };

  const isAdminMode = targetRole === UserRole.ADMIN;

  return (
    <div className={`min-h-screen flex flex-col items-center p-6 relative overflow-hidden transition-colors duration-1000 ${isAdminMode ? 'bg-[#0a0c1a]' : 'bg-slate-50'}`}>

      {/* Background Decor */}
      <div className={`absolute top-0 left-0 w-full h-full opacity-30 pointer-events-none transition-all duration-1000 ${isAdminMode ? 'bg-[radial-gradient(circle_at_top_right,rgba(59,130,246,0.15),transparent)]' : 'bg-[radial-gradient(circle_at_top_right,rgba(249,115,22,0.1),transparent)]'}`}></div>

      <div className="absolute top-10 right-10 flex gap-2 z-50">
          <button onClick={() => setLang(Language.ID)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black tracking-widest border transition-all ${lang === Language.ID ? (isAdminMode ? 'bg-blue-600' : 'bg-primary-500') + ' text-white border-transparent' : 'bg-white/10 text-slate-400'}`}>ID</button>
          <button onClick={() => setLang(Language.EN)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black tracking-widest border transition-all ${lang === Language.EN ? (isAdminMode ? 'bg-blue-600' : 'bg-primary-500') + ' text-white border-transparent' : 'bg-white/10 text-slate-400'}`}>EN</button>
      </div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10 pt-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-6">
            <div className={`p-6 rounded-[2.5rem] shadow-xl border relative group transition-all duration-700 ${isAdminMode ? 'bg-slate-900 border-blue-500/30' : 'bg-white border-slate-100'}`}>
               <SurePathLogo className={`w-16 h-16 relative z-10 transition-colors ${isAdminMode ? 'text-blue-500' : 'text-primary-500'}`} />
            </div>
          </div>
          <h1 className={`text-3xl font-black tracking-tighter uppercase leading-none transition-colors duration-700 ${isAdminMode ? 'text-white' : 'text-slate-900'}`}>
            Sure<span className={isAdminMode ? 'text-blue-500' : 'text-primary-500'}>{isAdminMode ? 'HQ' : 'Path'}</span>
          </h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.3em] mt-3">
            {isAdminMode ? t('Secure Admin Access', 'Akses Admin Terenkripsi') : t('Secure Member Access', 'Akses Member Aman')}
          </p>
        </div>

        <div className={`w-full rounded-[3rem] p-8 shadow-2xl overflow-hidden transition-all duration-700 border ${isAdminMode ? 'bg-slate-900/50 border-white/5' : 'bg-white border-slate-100'}`}>
          {mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in py-4">
              <div className="space-y-2">
                <h3 className={`text-xl font-black uppercase tracking-tight ${isAdminMode ? 'text-white' : 'text-slate-900'}`}>{t('Verification Code', 'Verifikasi Akun')}</h3>
                <p className="text-[0.65rem] text-slate-400 font-bold uppercase tracking-widest">{t('Enter the 6-digit simulated code: 123456', 'Masukkan kode simulasi: 123456')}</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className={`w-full bg-transparent border-b-2 text-center text-4xl font-black tracking-[0.4em] outline-none transition-all font-mono ${isAdminMode ? 'border-blue-500 text-blue-400' : 'border-primary-500 text-primary-500'}`}
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button 
                onClick={finalizeRegistration} 
                disabled={otp.length < 6 || loading} 
                className={`w-full py-4 rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 disabled:opacity-30 transition-all ${isAdminMode ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white'}`}
              >
                {t('Confirm Identity', 'Konfirmasi Identitas')}
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1.5 rounded-2xl border border-black/5 shadow-inner">
                <button type="button" onClick={() => { setMode('LOGIN'); setError(null); }} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? (isAdminMode ? 'bg-blue-600 text-white' : 'bg-white text-primary-600 shadow-sm') : 'text-slate-400'}`}>{t('Login', 'Masuk')}</button>
                <button type="button" onClick={() => { setMode('REGISTER'); setError(null); }} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${mode === 'REGISTER' ? (isAdminMode ? 'bg-blue-600 text-white' : 'bg-white text-primary-600 shadow-sm') : 'text-slate-400'}`}>{t('Register', 'Daftar')}</button>
              </div>

              {mode === 'REGISTER' && (
                <div className="flex gap-2">
                   <button 
                    onClick={() => setTargetRole(UserRole.CUSTOMER)}
                    className={`flex-1 py-2.5 rounded-xl text-[0.55rem] font-black uppercase tracking-widest border transition-all ${!isAdminMode ? 'bg-primary-500/10 border-primary-500 text-primary-600' : 'bg-white/5 border-white/10 text-slate-500'}`}
                   >
                     Member
                   </button>
                   <button 
                    onClick={() => setTargetRole(UserRole.ADMIN)}
                    className={`flex-1 py-2.5 rounded-xl text-[0.55rem] font-black uppercase tracking-widest border transition-all ${isAdminMode ? 'bg-blue-500/10 border-blue-500 text-blue-400' : 'bg-slate-100 border-slate-200 text-slate-400'}`}
                   >
                     Admin HQ
                   </button>
                </div>
              )}

              <form onSubmit={handleAuth} className="space-y-4">
                {mode === 'REGISTER' && (
                    <div className="space-y-1.5">
                        <label className="text-[0.55rem] font-black text-slate-500 uppercase tracking-widest ml-1">{t('Full Name', 'Nama Lengkap')}</label>
                        <div className="relative">
                          <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                          <input 
                              required placeholder="John Doe"
                              className={`w-full pl-12 pr-4 py-4 rounded-2xl outline-none transition-all font-bold text-sm border ${isAdminMode ? 'bg-slate-800 border-white/5 text-white focus:border-blue-500' : 'bg-slate-50 border-slate-100 focus:border-primary-500'}`}
                              value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})}
                          />
                        </div>
                    </div>
                )}

                <div className="space-y-1.5">
                    <label className="text-[0.55rem] font-black text-slate-500 uppercase tracking-widest ml-1">Email</label>
                    <div className="relative">
                        <Globe size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input 
                            required type="email" placeholder="example@surepath.ai"
                            className={`w-full pl-12 pr-4 py-4 rounded-2xl outline-none transition-all font-bold text-sm border ${isAdminMode ? 'bg-slate-800 border-white/5 text-white focus:border-blue-500' : 'bg-slate-50 border-slate-100 focus:border-primary-500'}`}
                            value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})}
                        />
                    </div>
                </div>

                <div className="space-y-1.5">
                    <label className="text-[0.55rem] font-black text-slate-500 uppercase tracking-widest ml-1">{t('Password', 'Kata Sandi')}</label>
                    <div className="relative">
                        <KeyRound size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" />
                        <input 
                            required type={showPass ? 'text' : 'password'} placeholder="••••••••"
                            className={`w-full pl-12 pr-12 py-4 rounded-2xl outline-none transition-all font-bold text-sm border ${isAdminMode ? 'bg-slate-800 border-white/5 text-white focus:border-blue-500' : 'bg-slate-50 border-slate-100 focus:border-primary-500'}`}
                            value={formData.password} onChange={(e) => setFormData({...formData, password: e.target.value})}
                        />
                        <button type="button" onClick={() => setShowPass(!showPass)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 hover:text-primary-500">
                            {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
                        </button>
                    </div>
                </div>

                {mode === 'REGISTER' && isAdminMode && (
                  <div className="space-y-1.5 animate-pop-in">
                    <label className="text-[0.55rem] font-black text-blue-400 uppercase tracking-widest ml-1">{t('Access Key', 'Kode Otoritas')}</label>
                    <div className="relative">
                      <ShieldAlert size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-blue-500" />
                      <input 
                        required placeholder="••••••••••••"
                        className="w-full pl-12 pr-4 py-4 rounded-2xl outline-none bg-blue-500/5 border border-blue-500/20 text-blue-200 font-mono text-xs"
                        value={formData.adminKey} onChange={(e) => setFormData({...formData, adminKey: e.target.value})}
                      />
                    </div>
                    <p className="text-[0.45rem] font-bold text-slate-500 uppercase ml-2 italic">Hint: SUREPATH-ADMIN-2025</p>
                  </div>
                )}

                {error && (
                  <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3 text-rose-500 text-[0.65rem] font-bold">
                      <AlertCircle size={16}/>
                      {error}
                  </div>
                )}

                <button 
                  type="submit" 
                  disabled={loading || (mode === 'REGISTER' && !canRegister) || (mode === 'LOGIN' && !canLogin)} 
                  className={`w-full py-5 rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-30 ${isAdminMode ? 'bg-blue-600 text-white' : 'bg-slate-900 text-white'}`}
                >
                  {loading ? <RefreshCw size={18} className="animate-spin"/> : (mode === 'LOGIN' ? t('Enter Portal', 'Masuk Portal') : t('Create Account', 'Buat Akun'))} 
                </button>
              </form>
            </div>
          )}
        </div>

        {/* Footer Link */}
        <div className="text-center pb-10">
           <button 
             onClick={() => setTargetRole(isAdminMode ? UserRole.CUSTOMER : UserRole.ADMIN)}
             className="text-[0.55rem] font-black uppercase text-slate-500 tracking-widest hover:text-primary-500 transition-colors"
           >
              {isAdminMode ? t('Return to Public Node', 'Kembali ke Node Publik') : t('Access HQ Terminal', 'Akses Terminal HQ')}
           </button>
        </div>
      </div>
    </div>
  );
};

