  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  const isAdmin = currentUser && [UserRole.ADMIN, UserRole.MASTER_ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role);

