    Tugas Utama: 
    1. VERIFIKASI IDENTITAS:
       Bandingkan unit di foto dengan data ekspektasi berikut:
       ${contextPrompt}
       Jika Warna, Merk, atau Plat berbeda, status WAJIB 'REJECTED'.

    2. ANALISA KUALITAS FOTO & KEBERSIHAN:
       Cek apakah mobil terlihat kotor.
       Cek kualitas pencahayaan dan fokus setiap foto.
       Kembalikan status 'DARK_PHOTO' jika pencahayaan kurang.
       Kembalikan status 'POOR_QUALITY' jika foto blur or resolusi rendah.

    3. IDENTIFIKASI KERUSAKAN:
       - Periksa panel: Bumper, Pintu, Fender, Kap Mesin, Atap, Kaca.
       - Cari: Goresan (Scratch), Penyok (Dent), Pecah (Crack).

    4. PENILAIAN SKOR (0-100):
       - Skor 100: Mulus & Bersih total.
       - Skor < 80: Ada kerusakan visual atau mobil terlalu kotor/gelap untuk diaudit.

    Output JSON Wajib:
    {
      "score": number,
      "summary": "Kesimpulan underwriting singkat (Bahasa Indonesia).",
      "underwritingReport": "Laporan naratif faktual.",
      "isDirty": boolean,
      "cleanlinessComment": "Komentar tentang kebersihan mobil.",
      "detailedIssues": [
        { "part": "Nama Bagian", "description": "Deskripsi kerusakan", "severity": "Minor" | "Moderate" | "Severe", "scorePenalty": number }
      ],
      "photoFlags": [
        { "id": "id_foto", "status": "OK" | "FRAUD_DETECTED" | "POOR_QUALITY" | "NOT_MATCHING" | "DARK_PHOTO", "reason": "Reason (In Indonesian)" }
      ],
      "auditVerdict": "CLEAN" | "REVIEW_REQUIRED" | "REJECTED",
      "rejectionReason": "Sebutkan alasan spesifik jika REJECTED"
    }`;

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { parts: [{ text: prompt }, ...imageParts] },
      config: { responseMimeType: 'application/json', temperature: 0.1 }
    });

    const text = response.text;
    if (!text) throw new Error("Empty AI response");
    const data = JSON.parse(text);

    const flagsWithIds = data.photoFlags?.map((flag: any, index: number) => ({
      ...flag,
      id: images[index]?.id || `img_${index}`
    }));

    return { success: true, ...data, photoFlags: flagsWithIds };
  } catch (e) { 
    console.error("Vehicle Survey AI Error:", e);
    return { success: false, error: "Gagal menghubungkan ke Neural Engine." }; 
  }
};

export const extractKtpData = async (base64: string): Promise<{ success: boolean; data?: any }> => {
  try {
    const ai = getAi();
    const cleanBase64 = base64.includes(',') ? base64.split(',')[1] : base64;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: { 
        parts: [
          { text: "Analyze this Indonesian KTP. Extract: Full Name (Nama), NIK (exactly 16 digits), and Full Address (Alamat). Return a JSON object with keys 'name', 'nik', and 'address'. Ensure NIK is cleaned of any non-numeric characters. Use uppercase for name and address. If a field is missing, use null." }, 
          { inlineData: { mimeType: 'image/jpeg', data: cleanBase64 } }
        ] 
      },
      config: { 
        responseMimeType: 'application/json',
        temperature: 0.1
      }
    });
    const text = response.text;
    if (!text) throw new Error("Empty AI response");
    return { success: true, data: JSON.parse(text) };
  } catch (e) { 
    console.error("KTP AI Error:", e);
    return { success: false }; 
  }
};

import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, Eye, EyeOff, Radio, Fingerprint, Sparkles, Activity,
  BellRing, X, RefreshCw, Smartphone, BadgeCheck, KeyRound, 
  Zap, ShieldCheck, Globe, AlertCircle, Shield, Phone, Check, Info
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, User as DBUser } from '../db';
import { hashPassword, verifyPassword, validatePasswordStrength, REGEX } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
}

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.EN }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState(initialLang === Language.EN ? 'Secure Environment' : 'Lingkungan Aman');
  const [lang, setLang] = useState<Language>(initialLang);

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  // Real-time Validation
  const passwordStrength = useMemo(() => validatePasswordStrength(formData.password), [formData.password]);
  const isEmailValid = useMemo(() => REGEX.EMAIL.test(formData.email), [formData.email]);
  const isPhoneValid = useMemo(() => REGEX.PHONE.test(formData.phone), [formData.phone]);

  const canRegister = useMemo(() => {
      // Minimal: Nama > 2, Email valid, Phone valid (8-13 digit), Password kuat (score 4)
      return formData.name.length > 2 && isEmailValid && isPhoneValid && passwordStrength.score === 4;
  }, [formData.name, isEmailValid, isPhoneValid, passwordStrength]);

  const canLogin = useMemo(() => {
      return isEmailValid && formData.password.length > 0;
  }, [isEmailValid, formData.password]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'REGISTER' && !canRegister) return;
    if (mode === 'LOGIN' && !canLogin) return;

    setLoading(true);
    setError(null);
    setStatusMsg(t('Processing...', 'Sedang Memproses...'));

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setStatusMsg(t('Access Granted!', 'Akses Diterima!'));
            setTimeout(() => onAuthSuccess(user), 800);
          } else {
            setError(t("Invalid password.", "Password salah."));
            setLoading(false);
          }
        } else {
          setError(t("Account not found.", "Akun tidak terdaftar."));
          setLoading(false);
        }
      } else {
        // REGISTER FLOW
        const existing = await db.users.where('email').equals(formData.email).first();
        if (existing) {
          setError(t("Email already registered.", "Email sudah terdaftar."));
          setLoading(false);
          return;
        }

        // Simulate OTP Generation
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);

        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setStatusMsg(t('Code Transmitted', 'Kode Terkirim'));
        }, 1500);
      }
    } catch (err) {
      setError(t("Registry error.", "Kesalahan sistem."));
      setLoading(false);
    }
  };

  const finalizeRegistration = async () => {
    if (otp !== generatedOtp) {
      setError(t("Invalid authentication code.", "Kode verifikasi salah."));
      return;
    }

    setLoading(true);
    setStatusMsg(t('Syncing Node...', 'Menyinkronkan Akun...'));
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: UserRole.CUSTOMER,
        nodeId: `SP-USR-${Math.floor(1000 + Math.random() * 9000)}`,
        verified: true,
        trustScore: 85,
        memberSince: new Date().toISOString()
      };
      const id = await db.users.add(newUser);
      setStatusMsg(t('Welcome to SurePath!', 'Selamat datang di SurePath!'));
      setTimeout(() => onAuthSuccess({ ...newUser, id }), 1000);
    } catch (err) {
      setError("Failed to create user node.");
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] dark:bg-[#080707] flex flex-col items-center p-6 relative overflow-hidden transition-all duration-700">

      {/* SIMULATED OTP NOTIFICATION */}
      {showIncomingOtp && (
        <div className="fixed top-6 inset-x-6 z-[1000] animate-bounce">
            <div className="max-w-md mx-auto bg-slate-900 text-white p-5 rounded-[2rem] shadow-2xl border border-white/10 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-primary-500 rounded-full flex items-center justify-center animate-pulse"><BellRing size={20}/></div>
                    <div>
                        <p className="text-[0.5rem] font-black uppercase tracking-widest text-primary-400">Pesan Masuk (Simulasi)</p>
                        <p className="text-xs font-bold">Kode Verifikasi: <span className="text-lg font-black tracking-widest text-primary-500 ml-2">{generatedOtp}</span></p>
                    </div>
                </div>
                <button onClick={() => setShowIncomingOtp(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={16}/></button>
            </div>
        </div>
      )}

      <div className="absolute top-10 right-10 flex gap-2 z-50">
          <button onClick={() => setLang(Language.ID)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black tracking-widest border transition-all ${lang === Language.ID ? 'bg-primary-500 text-white border-primary-500 shadow-lg' : 'bg-white dark:bg-white/5 border-slate-200 text-slate-400'}`}>ID</button>
          <button onClick={() => setLang(Language.EN)} className={`px-3 py-1.5 rounded-lg text-[10px] font-black tracking-widest border transition-all ${lang === Language.EN ? 'bg-primary-500 text-white border-primary-500 shadow-lg' : 'bg-white dark:bg-white/5 border-slate-200 text-slate-400'}`}>EN</button>
      </div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10 pt-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-6">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-white/5 relative group transition-all">
               <SurePathLogo className="w-16 h-16 relative z-10" />
            </div>
            <div className="absolute -bottom-3 -right-3 w-12 h-12 bg-white dark:bg-black rounded-2xl shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5">
                <NeuralBot mood={loading ? 'thinking' : 'scanning'} className="w-8 h-8" />
            </div>
          </div>
          <h1 className="text-3xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.3em] mt-3">{statusMsg}</p>
        </div>

        <div className="w-full bg-white dark:bg-[#0c0c0c] rounded-[3rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5 overflow-hidden transition-all">
          {mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in py-4">
              <div className="space-y-2">
                <h3 className="text-xl font-black uppercase tracking-tight">{t('Enter Node Key', 'Masukkan Kode Simpul')}</h3>
                <p className="text-[0.65rem] text-slate-400 font-bold uppercase tracking-widest">{t('Enter 6-digit code received.', 'Masukkan 6 digit kode verifikasi.')}</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-200 dark:border-white/10 text-center text-4xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all font-mono"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button 
                onClick={finalizeRegistration} 
                disabled={otp.length < 6 || loading} 
                className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 disabled:opacity-30 transition-all"
              >
                {t('Confirm Node', 'Konfirmasi Akun')}
              </button>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1.5 rounded-2xl mb-2 border border-slate-200 dark:border-white/5 shadow-inner">
                <button type="button" onClick={() => { setMode('LOGIN'); setError(null); }} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 opacity-60'}`}>{t('Login', 'Masuk')}</button>
                <button type="button" onClick={() => { setMode('REGISTER'); setError(null); }} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${mode === 'REGISTER' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-slate-400 opacity-60'}`}>{t('Register', 'Daftar')}</button>
              </div>

              <form onSubmit={handleAuth} className="space-y-5">
                <div className="space-y-4">
                  {mode === 'REGISTER' && (
                    <>
                    <div className="space-y-1.5">
                        <label className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest ml-1">{t('Full Name', 'Nama Lengkap')}</label>
                        <div className="relative">
                          <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                          <input 
                              required placeholder={t("Full legal name", "Nama sesuai KTP")}
                              className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm"
                              value={formData.name} onChange={(e) => setFormData({...formData, name: e.target.value})}
                          />
                        </div>
                    </div>
                    <div className="space-y-1.5">
                        <label className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest ml-1">{t('Phone Number', 'Nomor Telepon')}</label>
                        <div className="relative">
                          <Phone size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                          <input 
                              required type="tel" placeholder="0812XXXXXXXX"
                              className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm"
                              value={formData.phone} onChange={(e) => setFormData({...formData, phone: e.target.value.replace(/\D/g,'')})}
                          />
                        </div>
                    </div>
                    </>
                  )}

                  <div className="space-y-1.5">
                      <label className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest ml-1">Email</label>
                      <div className="relative">
                          <Globe size={18} className={`absolute left-4 top-1/2 -translate-y-1/2 transition-colors ${formData.email.length > 0 ? (isEmailValid ? 'text-emerald-500' : 'text-rose-500') : 'text-slate-300'}`} />
                          <input 
                              required type="email" placeholder="example@surepath.ai"
                              className={`w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 rounded-2xl outline-none transition-all font-bold text-sm ${formData.email.length > 0 ? (isEmailValid ? 'border-emerald-500/20' : 'border-rose-500/20') : 'border-slate-100 dark:border-white/5'}`}
                              value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})}
                          />
                      </div>
                  </div>

                  <div className="space-y-1.5">
                      <label className="text-[0.55rem] font-black text-slate-400 uppercase tracking-widest ml-1">{t('Password', 'Kata Sandi')}</label>
                      <div className="relative">
                          <KeyRound size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" />
                          <input 
                              required type={showPass ? 'text' : 'password'} placeholder="••••••••"
                              className="w-full pl-12 pr-12 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm"
                              value={formData.password} onChange={(e) => setFormData({...formData, password: e.target.value})}
                          />
                          <button type="button" onClick={() => setShowPass(!showPass)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-primary-500 transition-colors">
                              {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
                          </button>
                      </div>
                  </div>

                  {mode === 'REGISTER' && formData.password.length > 0 && (
                      <div className="p-4 bg-gray-50 dark:bg-white/[0.02] border border-black/5 dark:border-white/5 rounded-2xl space-y-3 animate-fade-in shadow-inner">
                          <div className="flex justify-between items-center px-1">
                              <p className="text-[0.55rem] font-black uppercase text-gray-400">{t('Neural Security Level', 'Tingkat Keamanan')}</p>
                              <span className={`text-[0.55rem] font-black uppercase ${passwordStrength.score === 4 ? 'text-emerald-500' : 'text-amber-500'}`}>
                                  {passwordStrength.score === 4 ? 'Quantum Grade' : passwordStrength.score > 2 ? 'Shielded' : 'Vulnerable'}
                              </span>
                          </div>
                          <div className="flex gap-1">
                              {[1,2,3,4].map(i => (
                                  <div key={i} className={`h-1 flex-1 rounded-full transition-all duration-500 ${i <= passwordStrength.score ? 'bg-primary-500 shadow-[0_0_8px_#f97316]' : 'bg-slate-200 dark:bg-white/10'}`}></div>
                              ))}
                          </div>
                          <div className="grid grid-cols-2 gap-x-2 gap-y-1.5 pt-1">
                              {passwordStrength.requirements.map((req, idx) => (
                                <div key={idx} className={`flex items-center gap-2 ${req.met ? 'text-emerald-500' : 'text-slate-400'}`}>
                                    <div className={`w-3 h-3 rounded-full flex items-center justify-center ${req.met ? 'bg-emerald-500/10' : 'bg-slate-200/50'}`}>
                                        {req.met && <Check size={8} strokeWidth={4}/>}
                                    </div>
                                    <span className="text-[0.45rem] font-black uppercase tracking-wider">{req.label}</span>
                                </div>
                              ))}
                          </div>
                      </div>
                  )}
                </div>

                {error && (
                  <div className="p-4 bg-rose-500/10 border border-rose-500/20 rounded-2xl flex items-center gap-3 text-rose-500 text-[0.65rem] font-bold animate-pop-in">
                      <AlertCircle size={16}/>
                      {error}
                  </div>
                )}

                <button 
                  type="submit" 
                  disabled={loading || (mode === 'REGISTER' && !canRegister) || (mode === 'LOGIN' && !canLogin)} 
                  className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.3em] shadow-2xl hover:scale-[1.01] active:scale-95 transition-all flex items-center justify-center gap-3 disabled:opacity-30 disabled:grayscale"
                >
                  {loading ? <RefreshCw size={18} className="animate-spin text-primary-500"/> : (mode === 'LOGIN' ? t('Authorize Access', 'Berikan Otoritas') : t('Establish Node', 'Buat Akun'))} 
                </button>
              </form>
            </div>
          )}
        </div>

        <div className="flex flex-col items-center gap-4 text-center pb-10">
           <p className="text-[0.55rem] font-bold text-slate-400 uppercase tracking-widest">{t('Powered by SurePath Neural Alliance', 'Didukung oleh SurePath Neural Alliance')}</p>
        </div>
      </div>
    </div>
  );
};

export default AuthGate;

import { Dexie, type Table } from 'dexie';
import { UserRole } from './types';
import { hashPassword } from './services/authService';

// --- DB INTERFACES ---

export interface User {
  id?: number;
  email: string;
  name: string;
  phone: string;
  passwordHash?: string;
  salt?: string;
  role: UserRole;
  nodeId: string;
  ktp?: string;
  address?: string;
  trustScore: number;
  memberSince: string;
  verified: boolean;
}

export interface Policy {
  id?: number;
  userId: number;
  type: 'CAR' | 'TRAVEL' | 'PA' | 'MPAR';
  status: 'ACTIVE' | 'PENDING' | 'EXPIRED' | 'CANCELLED';
  startDate: string;
  endDate: string;
  premium: number;
  coverageDetails: any; 
  providerId: string;
  policyNumber: string;
  createdAt: string;
}

export interface Claim {
  id?: number;
  policyId?: number;
  userId: number;
  date: string;
  time: string;
  location: string;
  chronology: string;
  thirdPartyInvolved: boolean;
  status: 'SUBMITTED' | 'ANALYZING' | 'APPROVED' | 'REJECTED' | 'PAID';
  amountEstimated: number;
  amountApproved?: number;
  photos: string[]; 
  aiAnalysis?: any;
  createdAt: string;
}

export interface Transaction {
  id?: number;
  userId: number;
  type: 'PAYMENT' | 'COMMISSION' | 'WITHDRAWAL' | 'CLAIM_PAYOUT' | 'POINTS';
  amount: number;
  status: 'SUCCESS' | 'PENDING' | 'FAILED';
  description: string;
  date: string;
  referenceId?: string;
}

export class SurePathDB extends Dexie {
  users!: Table<User, number>;
  policies!: Table<Policy, number>;
  claims!: Table<Claim, number>;
  transactions!: Table<Transaction, number>;

  constructor() {
    super('SurePathDB');
    (this as any).version(3).stores({
      users: '++id, &email, nodeId, role, verified',
      policies: '++id, userId, type, status, policyNumber, createdAt',
      claims: '++id, userId, policyId, status, createdAt',
      transactions: '++id, userId, type, date, referenceId'
    });
  }
}

