          lang={lang} 
          setLang={setLang} 
          darkMode={darkMode} 
          setDarkMode={setDarkMode} 
          currentPage={currentPage} 
          setPage={setPage}
          onAuthRequest={() => { setAppMode(true); setPage('auth'); }}
        />
        <DesktopWebsite 
          onEnterPortal={() => { setAppMode(true); setPage('auth'); }} 
          onAdminAccess={() => { setAppMode(true); setPage('auth'); }} 
          currentLang={lang} 
          onLangChange={setLang} 
