                     <div className="relative z-10 space-y-8">
                        <div className="flex justify-between items-start">
                           <div className="space-y-1">
                              <p className="text-[0.6rem] font-black text-primary-400 uppercase tracking-[0.4em]">{lang === Language.EN ? 'ACTIVE POLICY' : 'POLIS AKTIF'}</p>
