                    </button>
                ))}
            </div>
            <div className="grid grid-cols-2 gap-3">
                {[
                    { id: 'NEW', icon: Zap, label: 'Baru' },
                    { id: 'USED', icon: Timer, label: 'Bekas' }
                ].map(c => (
                    <button 
                        key={c.id}
