           <button onClick={() => setIsOpen(!isOpen)} className="p-3 text-slate-900 dark:text-white bg-slate-100 dark:bg-white/5 rounded-2xl shadow-sm">
            {isOpen ? <X size={24}/> : <Menu size={24}/>}
           </button>
        </div>
      </div>

      {isOpen && (
        <div className="fixed inset-0 top-[88px] z-[90] bg-white dark:bg-slate-950 flex flex-col p-10 space-y-12 lg:hidden animate-fade-in">
          <div className="flex flex-col space-y-8">
            {menuItems.map((item) => (
              <button
                key={item.id}
                className="text-left text-4xl font-black text-slate-900 dark:text-white uppercase tracking-tighter"
                onClick={() => { 
                  setIsOpen(false); 
                  if (currentPage === 'home') document.getElementById(item.id)?.scrollIntoView({ behavior: 'smooth' });
                  else setPage('home');
                }}
              >
                {t(item.en, item.idn)}
              </button>
            ))}

            <div className="h-px bg-slate-100 dark:bg-white/5 w-full my-4"></div>

            <button
                onClick={handleAuthClick}
                className="text-left py-6 px-8 bg-brand-500 rounded-[2rem] text-white flex flex-col gap-1 shadow-2xl active:scale-95 transition-all"
              >
                <div className="flex items-center gap-3">
                   <LogIn size={28}/>
                   <span className="text-3xl font-black uppercase tracking-tighter">{t('Sign In', 'Masuk')}</span>
