import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, Eye, EyeOff, Sparkles, X, RefreshCw, 
  KeyRound, ShieldCheck, Globe, AlertCircle, 
  Phone, Check, BellRing
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, User as DBUser } from '../db';
import { hashPassword, verifyPassword, validatePasswordStrength, REGEX } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
}

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>('LOGIN');
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [showIncomingOtp, setShowIncomingOtp] = useState(false);
  const [statusMsg, setStatusMsg] = useState('');
  const [lang, setLang] = useState<Language>(initialLang);

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  useEffect(() => {
    setStatusMsg(t('Your data is protected', 'Data kamu aman bersama kami'));
  }, [lang]);

  // Validasi Input Real-time
  const passwordStrength = useMemo(() => validatePasswordStrength(formData.password), [formData.password]);
  const isEmailValid = useMemo(() => REGEX.EMAIL.test(formData.email), [formData.email]);
  const isPhoneValid = useMemo(() => REGEX.PHONE.test(formData.phone), [formData.phone]);

  const canRegister = useMemo(() => {
      return formData.name.length > 2 && isEmailValid && isPhoneValid && passwordStrength.score >= 3;
  }, [formData.name, isEmailValid, isPhoneValid, passwordStrength]);

  const canLogin = useMemo(() => {
      return isEmailValid && formData.password.length > 0;
  }, [isEmailValid, formData.password]);

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setError(null);

    if (mode === 'LOGIN') {
      if (!canLogin) {
        setError(t("Please enter a valid email and password.", "Masukkan email dan kata sandi yang benar ya."));
        return;
      }
      setLoading(true);
      setStatusMsg(t('Checking your account...', 'Bentar ya, lagi ngecek akun kamu...'));

      try {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setStatusMsg(t('Welcome back!', 'Selamat datang kembali!'));
            setTimeout(() => onAuthSuccess(user), 800);
          } else {
            setError(t("Oops, wrong password. Try again!", "Aduh, kata sandinya salah. Coba diingat-ingat lagi ya!"));
            setLoading(false);
          }
        } else {
          setError(t("Account not found. Want to register instead?", "Akun belum terdaftar nih. Mau daftar dulu?"));
          setLoading(false);
        }
      } catch (err) {
        setError(t("Something went wrong. Please try again.", "Ada gangguan teknis sebentar. Coba lagi ya!"));
        setLoading(false);
      }
    } else {
      // PROSES DAFTAR
      if (!canRegister) {
        setError(t("Please fill in all details correctly.", "Lengkapi semua data dengan benar dulu ya."));
        return;
      }
      setLoading(true);
      setStatusMsg(t('Preparing your profile...', 'Sedang menyiapkan profil kamu...'));

      try {
        const existing = await db.users.where('email').equals(formData.email).first();
        if (existing) {
          setError(t("Email already used. Try logging in!", "Email ini sudah terdaftar. Masuk saja yuk!"));
          setLoading(false);
          return;
        }

        // Simulasi pengiriman kode verifikasi (OTP)
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);

        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setShowIncomingOtp(true);
          setStatusMsg(t('Verification code sent!', 'Kode verifikasi sudah dikirim!'));
        }, 1500);
      } catch (err) {
        setError(t("Registration failed. Try again.", "Gagal mendaftar. Coba sekali lagi ya!"));
        setLoading(false);
      }
    }
  };

  const finalizeRegistration = async () => {
    if (otp !== generatedOtp) {
      setError(t("Wrong verification code.", "Kode verifikasinya salah nih."));
      return;
    }

    setLoading(true);
    setStatusMsg(t('Creating your secure account...', 'Sedang membuat akun aman untukmu...'));
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: UserRole.CUSTOMER,
        nodeId: `SP-USR-${Math.floor(1000 + Math.random() * 9000)}`,
        verified: true,
        trustScore: 85,
        memberSince: new Date().toISOString()
      };
      const id = await db.users.add(newUser);
      setStatusMsg(t('Success! Welcome to the family.', 'Berhasil! Selamat bergabung di keluarga SurePath.'));
      setTimeout(() => onAuthSuccess({ ...newUser, id }), 1000);
    } catch (err) {
      setError("Ups, gagal menyimpan data. Coba lagi.");
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] dark:bg-[#080707] flex flex-col items-center p-6 relative overflow-hidden transition-all duration-700">

      {/* NOTIFIKASI KODE VERIFIKASI (SIMULASI) */}
      {showIncomingOtp && (
        <div className="fixed top-6 inset-x-6 z-[1000] animate-bounce">
            <div className="max-w-md mx-auto bg-slate-900 text-white p-5 rounded-[2.5rem] shadow-2xl border border-white/10 flex items-center justify-between">
                <div className="flex items-center gap-4">
                    <div className="w-10 h-10 bg-primary-500 rounded-full flex items-center justify-center animate-pulse"><BellRing size={20}/></div>
                    <div>
                        <p className="text-[0.5rem] font-black uppercase tracking-widest text-primary-400">Pesan SurePath (Simulasi)</p>
                        <p className="text-xs font-bold">Gunakan kode ini: <span className="text-xl font-black tracking-widest text-primary-500 ml-2">{generatedOtp}</span></p>
                    </div>
                </div>
                <button onClick={() => setShowIncomingOtp(false)} className="p-2 hover:bg-white/10 rounded-full transition-colors"><X size={16}/></button>
            </div>
        </div>
      )}

      {/* BAHASA TOGGLE */}
      <div className="absolute top-10 right-10 flex gap-2 z-50">
          <button onClick={() => setLang(Language.ID)} className={`px-4 py-2 rounded-xl text-[10px] font-black tracking-widest border transition-all ${lang === Language.ID ? 'bg-primary-500 text-white border-primary-500 shadow-lg' : 'bg-white dark:bg-white/5 border-slate-200 text-slate-400'}`}>IND</button>
          <button onClick={() => setLang(Language.EN)} className={`px-4 py-2 rounded-xl text-[10px] font-black tracking-widest border transition-all ${lang === Language.EN ? 'bg-primary-500 text-white border-primary-500 shadow-lg' : 'bg-white dark:bg-white/5 border-slate-200 text-slate-400'}`}>ENG</button>
      </div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10 pt-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-6">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.8rem] shadow-2xl border border-slate-100 dark:border-white/5 relative">
               <SurePathLogo className="w-16 h-16 relative z-10" />
            </div>
            <div className="absolute -bottom-3 -right-3 w-12 h-12 bg-white dark:bg-black rounded-2xl shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5">
                <NeuralBot mood={loading ? 'thinking' : 'scanning'} className="w-8 h-8" />
            </div>
          </div>
          <h1 className="text-4xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <p className="text-[0.65rem] font-bold text-slate-400 uppercase tracking-[0.2em] mt-3 bg-white dark:bg-white/5 px-4 py-1.5 rounded-full border border-black/5">{statusMsg}</p>
        </div>

        <div className="w-full bg-white dark:bg-[#0c0c0c] rounded-[3.5rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5 overflow-hidden transition-all">
          {mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in py-4">
              <div className="space-y-2">
                <h3 className="text-xl font-black uppercase tracking-tight">{t('Verify Your Account', 'Verifikasi Akun Kamu')}</h3>
                <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">{t('Enter the code we sent.', 'Masukkan 6 digit kode yang kami kirim.')}</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-200 dark:border-white/10 text-center text-5xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all font-mono"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              {error && <p className="text-rose-500 text-xs font-bold animate-pulse">{error}</p>}
              <button 
                onClick={finalizeRegistration} 
                disabled={otp.length < 6 || loading} 
