              <div className="space-y-2">
                <h2 className="text-5xl md:text-6xl font-black text-white leading-none tracking-tighter uppercase">
                  {t(slide, 'title')}
                </h2>
                <h3 className={`text-4xl md:text-5xl font-black tracking-tighter uppercase text-${slide.color}-400 drop-shadow-md`}>
