              <button 
                onClick={() => {
                  const ctaText = t(slide, 'cta').toLowerCase();
                  const target = ctaText.includes('travel') || ctaText.includes('pilihan') ? 'buy-travel' : 
                                 ctaText.includes('mobil') || ctaText.includes('car') || ctaText.includes('protect') ? 'buy-car' : 
                                 ctaText.includes('klaim') || ctaText.includes('claim') ? 'claim' : 'products';
                  onAction(target);
