                className="mt-4 px-12 py-5 bg-white text-slate-900 rounded-[2rem] font-black uppercase text-xs tracking-[0.3em] w-fit shadow-2xl flex items-center gap-4 transition-all hover:scale-105 active:scale-95 group relative overflow-hidden"
              >
                <span className="relative z-10">{t(slide, 'cta')}</span>
                <ArrowRight size={20} className="group-hover:translate-x-2 transition-transform text-gray-400 relative z-10"/>
              </button>
            </div>
          </div>
        </div>
      ))}

      <div className="absolute bottom-12 right-12 flex gap-3 z-20">
        {SLIDES.map((_, i) => (
          <button 
            key={i} 
