                         'text-emerald-500'
                     }`}>
                        {tx.type === 'WITHDRAWAL' ? '-' : '+'}{tx.type === 'POINTS' ? Math.floor(tx.amount).toLocaleString('id-ID') : formatIDR(tx.amount)}
