const WelcomeScreen = ({ onFinish }: { onFinish: () => void }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = [
    "Menyapa Server...",
    "Menyiapkan Proteksi Kamu...",
    "Mengecek Penawaran Terbaik...",
    "Koneksi Aman...",
    "Selesai!"
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2.5)), 35);
    const msgTimer = setInterval(() => setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i)), 700);
    const finishTimer = setTimeout(onFinish, 3200);
    return () => { clearInterval(timer); clearInterval(msgTimer); clearTimeout(finishTimer); };
  }, [onFinish]);

  return (
    <div className="fixed inset-0 z-[5000] bg-[#fafaf9] dark:bg-[#0c0a09] flex flex-col items-center justify-center overflow-hidden transition-colors duration-700">
      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-14 relative group">
           <div className="absolute inset-0 bg-primary-500/15 rounded-full blur-[70px] animate-pulse scale-150"></div>
           <NeuralBot className="w-48 h-48 relative" mood="happy" />
        </div>
        <div className="text-center space-y-8">
          <h1 className="text-5xl font-black tracking-[-0.05em] text-slate-900 dark:text-white uppercase">
            SURE<span className="text-brand-500">PATH</span>
          </h1>
          <div className="space-y-4">
            <p className="text-[0.7rem] font-black text-gray-500 dark:text-gray-400 uppercase tracking-[0.4em] h-4 transition-all duration-500">
               {messages[messageIdx]}
            </p>
            <div className="w-64 h-1.5 bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden mx-auto">
                <div className="h-full bg-brand-500 transition-all duration-300" style={{ width: `${progress}%` }}></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

const INITIAL_PRODUCTS = [
  { id: 'car', title: 'Asuransi Mobil', label: 'Asuransi Mobil', icon: Car, color: 'text-blue-500', active: true, cat: 'Retail', tech: 'Cek Foto Instan' },
  { id: 'travel', title: 'Asuransi Travel', label: 'Asuransi Travel', icon: Plane, color: 'text-emerald-500', active: true, cat: 'Retail', tech: 'Proteksi Kilat' },
  { id: 'pa', title: 'Kecelakaan Diri', label: 'Kecelakaan Diri', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: 'Santunan Cepat' },
  { id: 'mpar', title: 'Proteksi Barang', label: 'Proteksi Barang', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: 'Gadget & Elektronik' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [products] = useState(INITIAL_PRODUCTS);
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  const timeGreeting = useMemo(() => {
    const hour = new Date().getHours();
    if (hour < 11) return lang === Language.EN ? "Good Morning" : "Selamat Pagi";
    if (hour < 15) return lang === Language.EN ? "Good Afternoon" : "Selamat Siang";
    if (hour < 19) return lang === Language.EN ? "Good Afternoon" : "Selamat Sore";
    return lang === Language.EN ? "Good Evening" : "Selamat Malam";
  }, [lang]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  // PUBLIC VIEW (Website)
  if (!isMobile && !appMode && !currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar 
          lang={lang} 
          setLang={setLang} 
          darkMode={darkMode} 
          setDarkMode={setDarkMode} 
          currentPage={currentPage} 
          setPage={setPage}
          onAuthRequest={() => { setAppMode(true); setPage('auth'); }}
        />
        <DesktopWebsite 
          onEnterPortal={() => { setAppMode(true); setPage('auth'); }} 
          onAdminAccess={() => { setAppMode(true); setPage('auth'); }} 
          currentLang={lang} 
          onLangChange={setLang} 
        />
      </div>
    );
  }

  // AUTH GATE (Login/Register)
  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} />;
  }

  // APP PORTAL (Dashboard)
  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home':
        return (
          <PageTransition>
            <div className="space-y-8 pb-32 relative z-10">
              <div className="flex items-center justify-between px-2">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-white dark:bg-slate-900 rounded-[1.8rem] shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5 group active:scale-95 transition-all" onClick={() => setPage('profile')}>
                       <User className="text-slate-400 group-hover:text-brand-500" size={24}/>
                    </div>
                    <div>
                       <h3 className="text-xl font-black tracking-tight text-slate-800 dark:text-white leading-none">{timeGreeting}, {currentUser?.name.split(' ')[0]}!</h3>
                       <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1 flex items-center gap-2">
                          <CheckCircle2 size={12} className="text-emerald-500"/> {lang === Language.EN ? 'SECURE ACCOUNT' : 'AKUN TERVERIFIKASI'}
                       </p>
                    </div>
                 </div>
                 <button onClick={() => setPage('profile')} className="p-4 bg-white dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-white/5 text-slate-400 relative active:scale-90 transition-all">
                    <Bell size={22}/>
                    <span className="absolute top-4 right-4 w-2 h-2 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>
                 </button>
              </div>

              <PortalHero onAction={(p) => setPage(p)} lang={lang} />

              {latestPolicy ? (
                <div className="px-1">
                   <div className="p-8 bg-slate-900 rounded-[3rem] text-white relative overflow-hidden shadow-2xl group border border-white/5">
                      <div className="absolute top-0 right-0 p-10 opacity-5 rotate-12 group-hover:rotate-0 transition-transform duration-700">
                         {latestPolicy.type === 'CAR' ? <Car size={160}/> : <Plane size={160}/>}
                      </div>
                      <div className="relative z-10 space-y-8">
                         <div className="flex justify-between items-start">
                            <div className="space-y-1">
                               <p className="text-[10px] font-black text-brand-400 uppercase tracking-[0.3em]">{lang === Language.EN ? 'ACTIVE POLICY' : 'POLIS AKTIF'}</p>
