        </div>

        {/* Mobile Menu Button */}
        <div className="lg:hidden flex items-center">
          <button onClick={() => setIsOpen(!isOpen)} className="p-3 text-slate-900 dark:text-white bg-slate-100 dark:bg-white/5 rounded-2xl shadow-sm">
            {isOpen ? <X size={24}/> : <Menu size={24}/>}
          </button>
        </div>
      </div>

      {/* Mobile Menu Drawer */}
      {isOpen && (
        <div className="fixed inset-0 top-[88px] z-[90] bg-white dark:bg-slate-950 flex flex-col p-10 space-y-12 lg:hidden animate-fade-in h-screen overflow-y-auto">
          <div className="flex flex-col space-y-10">
            {menuItems.map((item) => (
              <button
                key={item.id}
                className="text-left text-4xl font-black text-slate-900 dark:text-white uppercase tracking-tighter"
                onClick={() => handleNavClick(item.id)}
              >
                {t(item.en, item.idn)}
