            <button
                onClick={() => setLang(lang === Language.EN ? Language.ID : Language.EN)}
                className="text-left text-4xl font-black text-brand-500 uppercase tracking-tighter flex items-center gap-4"
              >
                <Languages size={32}/>
                {lang === Language.ID ? 'English' : 'B. Indonesia'}
