const WelcomeScreen = ({ onFinish, lang }: { onFinish: () => void, lang: Language }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = lang === Language.ID ? [
    "Menyapa Server...",
    "Menyiapkan Proteksi Kamu...",
    "Mengecek Penawaran Terbaik...",
    "Koneksi Aman...",
    "Selesai!"
  ] : [
    "Greeting Server...",
    "Preparing Your Protection...",
    "Checking Best Offers...",
    "Secure Connection...",
    "Done!"
  ];

  useEffect(() => {
    const timer = setInterval(() => setProgress(p => (p >= 100 ? 100 : p + 2.5)), 35);
    const msgTimer = setInterval(() => setMessageIdx(i => (i < messages.length - 1 ? i + 1 : i)), 700);
    const finishTimer = setTimeout(onFinish, 3200);
    return () => { clearInterval(timer); clearInterval(msgTimer); clearTimeout(finishTimer); };
  }, [onFinish, messages.length]);

  return (
    <div className="fixed inset-0 z-[5000] bg-[#fafaf9] dark:bg-[#0c0a09] flex flex-col items-center justify-center overflow-hidden transition-colors duration-700">
      <div className="relative z-10 flex flex-col items-center animate-pop-in">
        <div className="mb-14 relative group">
           <div className="absolute inset-0 bg-primary-500/15 rounded-full blur-[70px] animate-pulse scale-150"></div>
           <NeuralBot className="w-48 h-48 relative" mood="happy" />
        </div>
        <div className="text-center space-y-8">
          <h1 className="text-5xl font-black tracking-[-0.05em] text-slate-900 dark:text-white uppercase">
            SURE<span className="text-primary-500">PATH</span>
          </h1>
          <div className="space-y-4">
            <p className="text-[0.7rem] font-black text-gray-500 dark:text-gray-400 uppercase tracking-[0.4em] h-4 transition-all duration-500">
               {messages[messageIdx]}
            </p>
            <div className="w-64 h-1.5 bg-gray-100 dark:bg-white/5 rounded-full overflow-hidden mx-auto">
                <div className="h-full bg-brand-500 transition-all duration-300" style={{ width: `${progress}%` }}></div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

