  { id: 'pa', title: lang === Language.ID ? 'Kecelakaan Diri' : 'Personal Accident', label: lang === Language.ID ? 'Kecelakaan Diri' : 'Personal Accident', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: lang === Language.ID ? 'Santunan Cepat' : 'Fast Payout' },
  { id: 'mpar', title: lang === Language.ID ? 'Proteksi Barang' : 'Item Protection', label: lang === Language.ID ? 'Proteksi Barang' : 'Item Protection', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: lang === Language.ID ? 'Gadget & Elektronik' : 'Gadget & Electronics' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  // Auto-detect language based on timezone location
  useEffect(() => {
    const tz = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const isIndo = tz.includes('Jakarta') || tz.includes('Makassar') || tz.includes('Jayapura') || tz.includes('Pontianak');
    setLang(isIndo ? Language.ID : Language.EN);
  }, []);

  const products = useMemo(() => INITIAL_PRODUCTS(lang), [lang]);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setAppMode(false);
    setPage('home');
  };

  const timeGreeting = useMemo(() => {
    const hour = new Date().getHours();
    if (lang === Language.ID) {
      if (hour < 11) return "Selamat Pagi";
      if (hour < 15) return "Selamat Siang";
      if (hour < 19) return "Selamat Sore";
      return "Selamat Malam";
    } else {
      if (hour < 11) return "Good Morning";
      if (hour < 15) return "Good Afternoon";
      if (hour < 19) return "Good Evening";
      return "Good Night";
    }
  }, [lang]);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen lang={lang} onFinish={() => setIsLoaded(true)} />;

  if (currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role)) {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  const t = (en: string, id: string) => lang === Language.EN ? en : id;

  if (!isMobile && !appMode && !currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
        <Navbar 
          lang={lang} 
          setLang={setLang} 
          darkMode={darkMode} 
          setDarkMode={setDarkMode} 
          currentPage={currentPage} 
          setPage={setPage}
          onAuthRequest={(mode) => { 
            setAuthMode(mode || 'LOGIN');
            setAppMode(true); 
            setPage('auth'); 
          }}
        />
        <DesktopWebsite 
          onEnterPortal={(mode) => { 
            setAuthMode(mode || 'REGISTER');
            setAppMode(true); 
            setPage('auth'); 
          }} 
          onAdminAccess={() => { 
            setAuthMode('LOGIN');
            setAppMode(true); 
            setPage('auth'); 
          }} 
          currentLang={lang} 
          onLangChange={setLang} 
        />
      </div>
    );
  }

  if (!currentUser && (isMobile || appMode)) {
    return <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} initialMode={authMode} />;
  }

  const renderPortalContent = () => {
    switch(currentPage) {
      case 'home':
        return (
          <PageTransition>
            <div className="space-y-8 pb-32 relative z-10">
              <div className="flex items-center justify-between px-2">
                 <div className="flex items-center gap-4">
                    <div className="w-14 h-14 bg-white dark:bg-slate-900 rounded-[1.8rem] shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5 group active:scale-95 transition-all" onClick={() => setPage('profile')}>
                       <User className="text-slate-400 group-hover:text-brand-500" size={24}/>
                    </div>
                    <div>
                       <h3 className="text-xl font-black tracking-tight text-slate-800 dark:text-white leading-none">{timeGreeting}, {currentUser?.name.split(' ')[0]}!</h3>
                       <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1 flex items-center gap-2">
                          <CheckCircle2 size={12} className="text-emerald-500"/> {t('SECURE ACCOUNT', 'AKUN TERVERIFIKASI')}
                       </p>
                    </div>
                 </div>
                 <div className="flex gap-2">
                    <button onClick={() => setLang(lang === Language.EN ? Language.ID : Language.EN)} className="p-4 bg-white dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-white/5 text-slate-400 font-black text-[10px] active:scale-90 transition-all">
                        {lang}
                    </button>
                    <button onClick={() => setPage('profile')} className="p-4 bg-white dark:bg-slate-800 rounded-2xl border border-slate-100 dark:border-white/5 text-slate-400 relative active:scale-90 transition-all">
                        <Bell size={22}/>
                        <span className="absolute top-4 right-4 w-2 h-2 bg-rose-500 rounded-full border-2 border-white dark:border-slate-800"></span>
                    </button>
                 </div>
              </div>

              <PortalHero onAction={(p) => setPage(p)} lang={lang} />

              {latestPolicy ? (
                <div className="px-1">
                   <div className="p-8 bg-slate-900 rounded-[3rem] text-white relative overflow-hidden shadow-2xl group border border-white/5">
                      <div className="absolute top-0 right-0 p-10 opacity-5 rotate-12 group-hover:rotate-0 transition-transform duration-700">
                         {latestPolicy.type === 'CAR' ? <Car size={160}/> : <Plane size={160}/>}
                      </div>
                      <div className="relative z-10 space-y-8">
                         <div className="flex justify-between items-start">
                            <div className="space-y-1">
