              ) : (
                <div className="px-1">
                   <div className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 flex items-center justify-between shadow-sm">
                      <div className="flex items-center gap-4">
