                         </div>
                      </div>
                      <button onClick={() => setPage('products')} className="px-4 py-2 bg-brand-500 text-white rounded-xl text-[10px] font-black uppercase shadow-lg shadow-brand-500/20 active:scale-95 transition-all">{t('Start', 'Mulai')}</button>
                   </div>
                </div>
              )}

              <div className="grid grid-cols-2 gap-4 px-1">
                <div onClick={() => setPage('products')} className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-white/5 shadow-sm cursor-pointer group active:scale-95 transition-all">
                  <div className="w-12 h-12 bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 mb-6 transition-transform group-hover:scale-110"><ShoppingBag size={24}/></div>
                  <p className="font-black text-lg uppercase tracking-tight">{t('Buy', 'Beli')}</p>
                  <p className="text-[0.6rem] text-gray-400 font-bold uppercase tracking-widest mt-1.5">{t('Find Protection', 'Cari Proteksi')}</p>
                </div>
                <div onClick={() => setPage('claim')} className="p-8 bg-brand-500 rounded-[3rem] shadow-2xl shadow-brand-500/20 cursor-pointer group active:scale-95 transition-all text-white">
                  <div className="w-12 h-12 bg-white/20 rounded-2xl flex items-center justify-center text-white mb-6 transition-transform group-hover:rotate-12"><Zap size={24}/></div>
                  <p className="font-black text-lg uppercase tracking-tight">{t('Claim', 'Klaim')}</p>
                  <p className="text-[0.6rem] text-white/70 font-bold uppercase tracking-widest mt-1.5">{t('Fast AI Audit', 'Audit AI Cepat')}</p>
                </div>
              </div>

              <div className="space-y-4 px-1 pt-2">
                  <div className="flex justify-between items-center px-4">
                     <h3 className="text-xl font-black uppercase tracking-tight text-slate-800 dark:text-white">{t('Suggestions', 'Rekomendasi')}</h3>
                     <button onClick={() => setPage('products')} className="text-[10px] font-black uppercase text-brand-500 flex items-center gap-1">{t('View All', 'Semua')} <ChevronRight size={14}/></button>
                  </div>
                  <div className="grid grid-cols-2 gap-4">
                    {products.slice(0, 4).map(p => (
                      <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-5 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 flex flex-col gap-4 active:scale-95 transition-all shadow-sm cursor-pointer group hover:border-brand-500/30">
                        <div className={`w-11 h-11 ${p.color} bg-gray-50 dark:bg-white/5 rounded-2xl flex items-center justify-center group-hover:scale-110 transition-transform shadow-inner`}><p.icon size={20}/></div>
                        <div><h4 className="font-black text-xs uppercase leading-none mb-1.5">{p.label}</h4><p className="text-[0.6rem] text-gray-400 font-bold uppercase tracking-widest">{p.tech}</p></div>
                      </div>
                    ))}
                  </div>
              </div>
            </div>
          </PageTransition>
        );
      case 'products':
        return (
          <PageTransition>
            <div className="space-y-8 pb-24 pt-2">
              <h2 className="text-4xl font-black uppercase tracking-tighter px-2 text-slate-900 dark:text-white">{t('Our', 'Pilihan')} <span className="text-emerald-500">{t('Products', 'Asuransi')}</span></h2>
              <div className="grid gap-4">
                {products.map(p => (
                  <div key={p.id} onClick={() => setPage(`buy-${p.id}`)} className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 flex items-center justify-between active:scale-[0.98] transition-all cursor-pointer shadow-sm group hover:border-emerald-500/40">
                    <div className="flex items-center gap-6">
                      <div className={`w-16 h-16 bg-gray-50 dark:bg-white/5 ${p.color} rounded-[1.8rem] flex items-center justify-center shadow-inner transition-transform group-hover:scale-110`}><p.icon size={32}/></div>
                      <div><h4 className="font-black text-xl uppercase text-slate-800 dark:text-white leading-none mb-2">{p.title}</h4><p className="text-[10px] text-gray-400 font-bold uppercase tracking-[0.2em]">{p.tech}</p></div>
                    </div>
                    <ChevronRight className="text-gray-300 group-hover:text-emerald-500 transition-colors" size={24}/>
                  </div>
                ))}
              </div>
            </div>
          </PageTransition>
        );
      case 'claim': return <PageTransition><ClaimManager onComplete={() => setPage('home')} lang={lang} /></PageTransition>;
      case 'wallet': return <PageTransition><AgentsWallet lang={lang}/></PageTransition>;
      case 'profile': return <PageTransition><UserProfile currentUser={currentUser} lang={lang} onLogout={handleLogout} /></PageTransition>;
      case 'buy-car': return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
      case 'buy-travel': return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
      case 'buy-pa': return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
      case 'buy-mpar': return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
      case 'bot': return <HealthChat onBack={() => setPage('home')} lang={lang} />;
      default: return null;
    }
  };

  const isWizardFlow = currentPage.startsWith('buy-');

  const navItems = [
    { id: 'home', icon: HomeIcon, label: t('Home', 'Beranda') },
    { id: 'products', icon: ShoppingBag, label: t('Products', 'Produk') }, 
    { id: 'bot', icon: Bot, label: t('Assistant', 'Asisten') },
    { id: 'claim', icon: Zap, label: t('Claim', 'Klaim') },
    { id: 'profile', icon: UserCircle, label: t('Account', 'Akun') }
  ];

  return (
    <div className={`${darkMode ? 'dark bg-[#0a0a0a]' : 'bg-[#fafaf9]'} h-full transition-colors duration-700 font-sans flex flex-col relative overflow-hidden`}>
      <div className="absolute inset-0 pointer-events-none z-0 overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[120%] h-[120%] bg-gradient-to-br from-emerald-500/5 via-transparent to-primary-500/5 blur-[120px]"></div>
      </div>

      {!isWizardFlow && currentUser && (
        <header className="flex-shrink-0 h-24 glass-card px-8 flex items-center justify-between border-b border-gray-100 dark:border-white/5 z-[60] relative bg-white/60 dark:bg-black/20 backdrop-blur-xl transition-all duration-700">
          <div className="flex items-center gap-4 cursor-pointer group" onClick={() => setPage('home')}>
            <SurePathLogo className="w-12 h-12 group-hover:scale-110 transition-transform" />
            <div className="flex flex-col">
              <span className="font-black text-xl tracking-tighter uppercase leading-none text-slate-900 dark:text-white">Sure<span className="text-brand-500">Path</span></span>
              <span className="text-[10px] font-bold text-gray-400 dark:text-gray-500 uppercase tracking-[0.4em] mt-1.5 transition-colors duration-700">{currentUser?.name || 'Halo!'}</span>
            </div>
          </div>
          <div className="flex items-center gap-3">
            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-slate-800 rounded-2xl text-gray-400 dark:text-gray-500 hover:text-brand-500 transition-all duration-700 shadow-sm border border-slate-100 dark:border-white/5 active:rotate-45">
              {darkMode ? <Sun size={20}/> : <Moon size={20}/>}
            </button>
            <button onClick={handleLogout} className="p-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-rose-500 dark:hover:bg-rose-500 transition-all duration-700 shadow-xl active:scale-95 group">
               <LogOut size={20} className="group-hover:-translate-x-0.5 transition-transform"/>
            </button>
          </div>
        </header>
      )}

      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative transition-all duration-700 ${isWizardFlow ? 'p-0 h-screen' : (currentUser ? 'px-6 py-10' : '')}`}>
        {renderPortalContent()}
      </main>

      {!isWizardFlow && currentUser && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-22 bg-white/90 dark:bg-[#111]/90 backdrop-blur-2xl z-[70] flex items-center justify-around px-4 rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.15)] border border-slate-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-2 flex-1 py-4 transition-all duration-500 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-brand-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-600'}`}>
              <item.icon size={26} strokeWidth={2.5} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(16,185,129,0.5)]' : ''} />
              <span className={`text-[9px] font-black uppercase tracking-[0.2em] ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
            </button>
          ))}
        </nav>
      )}
