            <button onClick={() => setDarkMode(!darkMode)} className="p-3 bg-white dark:bg-slate-800 rounded-2xl text-gray-400 dark:text-gray-500 hover:text-primary-500 transition-all duration-700 shadow-xl border border-slate-100 dark:border-white/5 active:rotate-45">
