            </button>
            <button onClick={handleLogout} className="p-3 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl hover:bg-rose-500 dark:hover:bg-rose-500 transition-all duration-700 shadow-xl active:scale-95 group">
               <LogOut size={20} className="group-hover:-translate-x-0.5 transition-transform"/>
            </button>
          </div>
        </header>
      )}
      <main className={`flex-1 overflow-y-auto w-full no-scrollbar z-10 relative transition-all duration-700 ${isWizardFlow ? 'p-0 h-screen' : (currentUser ? 'px-6 py-10' : '')}`}>
        {renderPortalContent()}
      </main>
      {!isWizardFlow && currentUser && (
        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-22 bg-white/90 dark:bg-[#111]/90 backdrop-blur-2xl z-[70] flex items-center justify-around px-4 rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.15)] border border-slate-100 dark:border-white/10 max-w-xl mx-auto transition-all duration-500">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-2 flex-1 py-4 transition-all duration-500 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-600'}`}>
              <item.icon size={26} strokeWidth={2.5} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.5)]' : ''} />
              <span className={`text-[9px] font-black uppercase tracking-[0.2em] ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );
};

export default App;

