  { id: 'travel', title: lang === Language.EN ? 'Travel Insurance' : 'Asuransi Perjalanan', label: lang === Language.EN ? 'Travel Insurance' : 'Asuransi Perjalanan', icon: Plane, color: 'text-emerald-500', active: true, cat: 'Retail', tech: lang === Language.EN ? 'Instant Active' : 'Aktif Instan' },
  { id: 'pa', title: lang === Language.EN ? 'Personal Accident' : 'Kecelakaan Diri', label: lang === Language.EN ? 'Personal Accident' : 'Kecelakaan Diri', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: lang === Language.EN ? 'Fast Payout' : 'Santunan Cepat' },
  { id: 'mpar', title: lang === Language.EN ? 'Item Protection' : 'Proteksi Barang', label: lang === Language.EN ? 'Item Protection' : 'Proteksi Barang', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: lang === Language.EN ? 'Gadget & Electronics' : 'Elektronik & Gadget' },
