export const SecurityView = () => {
  const [pulse, setPulse] = useState(getSecurityPulse());
  const [threats, setThreats] = useState<ThreatNode[]>(getRecentThreats());
  const [activeTraffic, setActiveTraffic] = useState<number[]>(Array(40).fill(0).map(() => 20 + Math.random() * 40));

  const updatePulse = useCallback(() => {
    setPulse(getSecurityPulse());
    setActiveTraffic(prev => [...prev.slice(1), 20 + Math.random() * 60]);
    if (Math.random() > 0.95) {
      const newThreat = generateLiveThreat();
      setThreats(prev => [newThreat, ...prev.slice(0, 4)]);
      logAdminAction("SYSTEM_BOT", "SECURITY", "THREAT_MITIGATED", newThreat);
    }
  }, []);

  useEffect(() => {
    const interval = setInterval(updatePulse, 3000);
    return () => clearInterval(interval);
  }, [updatePulse]);

  return (
    <div className="space-y-8 animate-fade-in relative">
       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
          <StatCard label="Live Threats Blocked" value={pulse.threatsBlocked24h.toLocaleString()} trend="+6" icon={ShieldAlert} color="bg-rose-500/10 text-rose-500" />
          <StatCard label="Neural Payload" value={`${pulse.neuralLoad.toFixed(2)}%`} trend="-0.1%" icon={Cpu} color="bg-blue-500/10 text-blue-500" />
          <StatCard label="Gate Latency" value="0.22ms" icon={Zap} color="bg-primary-500/10 text-primary-500" />
          <StatCard label="Network Uptime" value="99.999%" icon={Globe} color="bg-emerald-500/10 text-emerald-500" />
       </div>
       <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <Card className="lg:col-span-2 h-[420px] flex flex-col">
             <div className="flex items-center gap-4 mb-10">
                <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500"><Terminal size={20}/></div>
                <h3 className="font-black uppercase tracking-widest text-sm">Matriks Traffic Real-time</h3>
             </div>
             <div className="flex-1 flex items-end gap-1 px-2 border-b border-white/5 pb-1">
                {activeTraffic.map((h, i) => (
                   <div key={i} className="flex-1 bg-primary-500 transition-all duration-700 rounded-t-sm" style={{ height: `${h}%`, opacity: 0.1 + (i / 40) * 0.9 }}></div>
