const AddUserForm = ({ onUserAdded }: { onUserAdded: () => void }) => {
    const [isExpanding, setIsExpanding] = useState(false);
    const [loading, setLoading] = useState(false);
    const [form, setForm] = useState({ name: '', email: '', role: UserRole.CUSTOMER });

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        try {
            const defaultCreds = await hashPassword('Surepath123!');
            const newUser: DBUser = {
                name: form.name,
                email: form.email,
                phone: '0812' + Math.floor(10000000 + Math.random() * 90000000),
                role: form.role,
                nodeId: `SP-${form.role.substring(0,3)}-${Math.floor(1000+Math.random()*9000)}`,
                trustScore: 90,
                memberSince: new Date().toISOString(),
                verified: true,
                passwordHash: defaultCreds.hash,
                salt: defaultCreds.salt
            };
            await db.users.add(newUser);
            await logAdminAction("ADMIN_SESSION", "SECURITY", "USER_CREATED", { email: form.email, role: form.role });
            setForm({ name: '', email: '', role: UserRole.CUSTOMER });
            setIsExpanding(false);
            onUserAdded();
        } catch (err) {
            alert("Error: Email mungkin sudah terdaftar.");
        } finally {
            setLoading(false);
        }
    };

    if (!isExpanding) return (
        <button onClick={() => setIsExpanding(true)} className="w-full py-6 border-2 border-dashed border-white/5 rounded-[2.5rem] flex items-center justify-center gap-4 text-gray-500 hover:text-primary-500 hover:border-primary-500/40 transition-all group">
            <UserPlus size={24} className="group-hover:scale-110 transition-transform"/><span className="text-xs font-black uppercase tracking-widest">Tambah Node User Baru</span>
        </button>
    );

    return (
        <Card className="border-primary-500/30 animate-pop-in">
            <div className="flex justify-between items-center mb-8">
                <h4 className="font-black uppercase tracking-widest text-sm">Registrasi Simpul Baru</h4>
                <button onClick={() => setIsExpanding(false)} className="p-2 bg-white/5 rounded-full hover:bg-rose-500 transition-all"><X size={18}/></button>
            </div>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-3 gap-6">
                <input required className="bg-white/5 border border-white/10 rounded-2xl px-5 py-3 text-xs outline-none focus:border-primary-500" placeholder="Nama Lengkap" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
                <input required type="email" className="bg-white/5 border border-white/10 rounded-2xl px-5 py-3 text-xs outline-none focus:border-primary-500" placeholder="Email Jaringan" value={form.email} onChange={e => setForm({...form, email: e.target.value})} />
                <select className="bg-white/5 border border-white/10 rounded-2xl px-5 py-3 text-xs outline-none focus:border-primary-500" value={form.role} onChange={e => setForm({...form, role: e.target.value as UserRole})}>
                    <option value={UserRole.CUSTOMER}>CUSTOMER</option>
                    <option value={UserRole.AGENT}>AGENT</option>
                    <option value={UserRole.ADMIN}>ADMIN</option>
                    <option value={UserRole.FINANCE}>FINANCE</option>
                </select>
                <div className="md:col-span-3">
                    <button type="submit" disabled={loading} className="w-full py-4 bg-primary-500 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl flex items-center justify-center gap-2">
                        {loading ? <Loader2 size={16} className="animate-spin"/> : <Check size={16}/>} Sinkronisasi Node
