export const BizAdminView = ({ isDashboard, section, userRole }: { isDashboard?: boolean, section?: string, userRole: UserRole }) => {
  const [users, setUsers] = useState<DBUser[]>([]);
  const [policies, setPolicies] = useState<Policy[]>([]);

  useEffect(() => {
    const fetchData = async () => {
        const allUsers = await db.users.toArray();
        const allPolicies = await db.policies.toArray();
        setUsers(allUsers);
        setPolicies(allPolicies);
    };
    fetchData();
  }, [section]);

  if (section === 'transactions') {
     return (
        <div className="space-y-8 animate-fade-in">
           <Card>
              <h3 className="font-black uppercase tracking-widest text-sm mb-6">Live Policy Deployment Traffic</h3>
              <div className="space-y-4">
                 {policies.map((p, i) => (
