               <div>
                  <h4 className={`font-black uppercase text-sm tracking-tight transition-all ${task.completed ? 'line-through text-gray-500' : 'text-white'}`}>{task.title}</h4>
                  <p className="text-[0.6rem] font-bold text-gray-500 uppercase tracking-widest mt-1">{task.desc}</p>
