            </div>
            <ChevronRight size={20} className={`text-gray-600 transition-all ${task.completed ? 'opacity-0' : 'group-hover:text-primary-500 group-hover:translate-x-1'}`}/>
          </button>
        ))}
      </div>

      <div className="pt-8 text-center">
         <p className="text-[0.55rem] font-black text-gray-600 uppercase tracking-[0.4em] animate-pulse">Syncing with HQ Directives Cluster</p>
      </div>
    </div>
  );
};

