        <nav className="flex-shrink-0 fixed bottom-8 inset-x-6 h-22 bg-white/90 dark:bg-[#111]/90 backdrop-blur-2xl z-[70] flex items-center justify-around px-6 rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.2)] border border-slate-200/50 dark:border-white/10 max-w-xl mx-auto transition-all duration-700">
          {navItems.map(item => (
            <button key={item.id} onClick={() => setPage(item.id)} className={`flex flex-col items-center gap-2 flex-1 py-4 transition-all duration-500 tap-feedback ${currentPage === item.id || (currentPage.startsWith('buy') && item.id === 'products') ? 'text-primary-500 scale-110 -translate-y-1' : 'text-gray-400 dark:text-gray-600'}`}>
              <item.icon size={26} strokeWidth={2.5} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(249,115,22,0.5)]' : ''} />
              <span className={`text-[0.5rem] font-black uppercase tracking-[0.2em] ${currentPage === item.id ? 'opacity-100' : 'opacity-60'}`}>{item.label}</span>
            </button>
          ))}
        </nav>
      )}
    </div>
  );

  // Separate App simulation from Full-screen Admin Dashboard
  if (!isMobile && (currentUser || appMode)) {
    // If Admin path was chosen, don't show the phone simulator
    if (portalPref === 'ADMIN' && isAdminRole) {
       return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
    }

    return (
      <div className="min-h-screen bg-[#01241d] flex items-center justify-center p-12 overflow-hidden relative transition-all duration-1000 ease-in-out">
        <div className="absolute inset-0 bg-neural-mesh opacity-100"></div>
        <div className="relative w-[440px] h-[880px] bg-white rounded-[5rem] border-[14px] border-[#023129] shadow-[0_60px_120px_-30px_rgba(0,0,0,0.6)] ring-[1px] ring-white/10 overflow-hidden group transition-all duration-700">
          <div className="h-full w-full overflow-hidden rounded-[3.8rem]">
             <AppWrapper />
          </div>
        </div>

        {/* Technical Side Details for Desktop Simulation */}
        <div className="absolute left-10 top-1/2 -translate-y-1/2 hidden xl:flex flex-col gap-6 w-80">
           <div className="p-10 bg-white/10 backdrop-blur-xl rounded-[3rem] border border-white/20 space-y-6 shadow-2xl">
              <div className="w-16 h-16 bg-emerald-500 rounded-3xl flex items-center justify-center text-white shadow-lg animate-float"><Terminal size={32}/></div>
              <h4 className="text-2xl font-black text-white uppercase tracking-tighter">Client Tunnel</h4>
              <p className="text-[0.7rem] text-gray-400 font-bold leading-relaxed uppercase tracking-[0.2em]">Active Session: {currentUser?.name || 'Guest Node'}. Link Status: Encrypted.</p>
              <div className="pt-2">
                 <span className="px-3 py-1 bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 rounded-full text-[0.6rem] font-black uppercase tracking-widest">{currentUser?.role || 'NEURAL_NODE'}</span>
              </div>
           </div>
        </div>
      </div>
    );
  }

  return <AppWrapper />;
};

