  { id: 'car', title: lang === Language.ID ? 'Asuransi Mobil' : 'Car Insurance', label: lang === Language.ID ? 'Asuransi Mobil' : 'Car Insurance', icon: Car, color: 'text-blue-500', active: true, cat: 'Retail', tech: lang === Language.ID ? 'Audit Visual AI' : 'AI Visual Audit' },
  { id: 'travel', title: lang === Language.ID ? 'Asuransi Perjalanan' : 'Travel Insurance', label: lang === Language.ID ? 'Asuransi Perjalanan' : 'Travel Insurance', icon: Plane, color: 'text-emerald-500', active: true, cat: 'Retail', tech: lang === Language.ID ? 'Aktivasi Instan' : 'Instant Activation' },
  { id: 'pa', title: lang === Language.ID ? 'Kecelakaan Diri' : 'Personal Accident', label: lang === Language.ID ? 'Kecelakaan Diri' : 'Personal Accident', icon: ShieldAlert, color: 'text-rose-500', active: true, cat: 'Retail', tech: lang === Language.ID ? 'Santunan Cepat' : 'Fast Payout' },
  { id: 'mpar', title: lang === Language.ID ? 'Proteksi Barang' : 'Item Protection', label: lang === Language.ID ? 'Proteksi Barang' : 'Item Protection', icon: Package, color: 'text-amber-500', active: true, cat: 'Retail', tech: lang === Language.ID ? 'Elektronik & Gadget' : 'Electronics & Gadgets' },
];

const App = () => {
  const [isLoaded, setIsLoaded] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [darkMode, setDarkMode] = useState(false);
  const [appMode, setAppMode] = useState(false); 
  const [authMode, setAuthMode] = useState<'LOGIN' | 'REGISTER'>('LOGIN');
  const [portalPref, setPortalPref] = useState<'MOBILE' | 'ADMIN'>('MOBILE');
  const [lang, setLang] = useState<Language>(Language.ID);
  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  const products = useMemo(() => INITIAL_PRODUCTS(lang), [lang]);

  useEffect(() => {
    seedDatabase();
    const savedSession = localStorage.getItem('SUREPATH_SESSION');
    const savedPref = localStorage.getItem('SUREPATH_PORTAL_PREF');

    if (savedPref) setPortalPref(savedPref as any);

    if (savedSession) {
      try {
        const user = JSON.parse(savedSession);
        setCurrentUser(user);
        setAppMode(true);
        db.policies.where('userId').equals(user.id).toArray().then(res => {
           if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
        });
      } catch (e) { localStorage.removeItem('SUREPATH_SESSION'); }
    }
  }, [currentPage]);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    localStorage.setItem('SUREPATH_PORTAL_PREF', portalPref);
    setAppMode(true);
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    localStorage.removeItem('SUREPATH_PORTAL_PREF');
    setAppMode(false);
    setPage('home');
  };

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  if (!isLoaded) return <WelcomeScreen onFinish={() => setIsLoaded(true)} lang={lang} />;

  const t = (en: string, id: string) => lang === Language.EN ? en : id;

  // 1. Dashboard View (HQ Admin) - Full screen desktop if preferred
  const isAdminRole = currentUser && [UserRole.MASTER_ADMIN, UserRole.ADMIN, UserRole.FINANCE, UserRole.INSURANCE_ADMIN].includes(currentUser.role);

  if (isAdminRole && portalPref === 'ADMIN') {
    return <AdminPortal onLogout={handleLogout} products={products} setProducts={() => {}} userRole={currentUser.role} />;
  }

  // 2. Landing Page View
  if (!isMobile && !appMode && !currentUser) {
    return (
      <div className={darkMode ? 'dark' : ''}>
