          lang={lang} 
          setLang={setLang} 
          darkMode={darkMode} 
          setDarkMode={setDarkMode} 
          currentPage={currentPage} 
          setPage={setPage}
          onAuthRequest={(mode) => { 
            setAuthMode(mode || 'LOGIN');
            setPortalPref('MOBILE'); // Default entering via navbar is mobile view
            setAppMode(true); 
            setPage('auth'); 
          }}
        />
        <DesktopWebsite 
          onEnterPortal={(mode) => { 
            setAuthMode(mode || 'REGISTER');
            setPortalPref('MOBILE');
            setAppMode(true); 
            setPage('auth'); 
          }} 
          onAdminAccess={() => { 
            setAuthMode('LOGIN');
            setPortalPref('ADMIN'); // Explicitly requesting admin dashboard
            setAppMode(true); 
            setPage('auth'); 
          }} 
          currentLang={lang} 
          onLangChange={setLang} 
        />
      </div>
    );
  }

  // 3. Auth Portal View
  if (!currentUser && (isMobile || appMode)) {
    return (
        <div className="min-h-screen bg-[#fafaf9] dark:bg-[#080707] flex items-center justify-center p-4">
            <div className="w-full max-w-md animate-fade-in">
                {portalPref === 'ADMIN' && (
                    <div className="mb-8 flex items-center justify-center gap-3 px-6 py-3 bg-primary-500/10 rounded-2xl border border-primary-500/20 text-primary-600 animate-pulse">
                        <Terminal size={18}/>
                        <span className="text-[0.65rem] font-black uppercase tracking-[0.2em]">HQ Admin Secure Access</span>
                    </div>
                )}
                <AuthGate onAuthSuccess={handleAuthSuccess} initialLang={lang} initialMode={authMode} />
                <button 
                    onClick={() => { setAppMode(false); setPage('home'); }} 
                    className="w-full mt-6 text-[0.6rem] font-black uppercase text-gray-400 hover:text-primary-500 tracking-[0.3em] transition-all"
                >
                    &larr; {t('Back to Landing Page', 'Kembali ke Beranda')}
                </button>
            </div>
        </div>
    );
  }

  const renderPortalContent = () => {
