const Navbar: React.FC<NavbarProps> = ({ lang, setLang, darkMode, setDarkMode, currentPage, setPage, onAuthRequest }) => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const menuItems = [
    { id: 'products-section', en: 'Neural Ecosystem', idn: 'Ekosistem Produk' },
    { id: 'how-it-works', en: 'How It Works', idn: 'Cara Kerja' },
    { id: 'about-page', en: 'Company', idn: 'Tentang Kami', isPage: true },
  ];

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  const handleNavClick = (item: any) => {
    if (item.isPage) {
        setPage('about');
        setIsOpen(false);
        window.scrollTo({top: 0, behavior: 'smooth'});
        return;
    }

    const element = document.getElementById(item.id);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
      setIsOpen(false);
    } else {
        setPage('home');
        setTimeout(() => {
            document.getElementById(item.id)?.scrollIntoView({ behavior: 'smooth' });
        }, 100);
    }
  };

  return (
    <nav className={`fixed top-0 left-0 right-0 z-[100] transition-all duration-500 ${
