            <span className="text-[9px] font-black text-slate-400 dark:text-slate-500 uppercase tracking-[0.3em] leading-none mt-1.5 hidden sm:block">
              {t('Accelerating Protection', 'Akselerasi Proteksi')}
            </span>
          </div>
        </div>

        <div className="hidden lg:flex items-center space-x-10">
          {menuItems.map((item) => (
            <button
              key={item.id}
              className={`text-slate-600 dark:text-slate-400 hover:text-brand-500 font-bold text-[13px] uppercase tracking-widest transition-all hover:scale-105 ${currentPage === 'about' && item.isPage ? 'text-brand-500' : ''}`}
              onClick={() => handleNavClick(item)}
            >
              {t(item.en, item.idn)}
            </button>
          ))}

          <div className="h-6 w-px bg-slate-200 dark:bg-white/10 mx-2"></div>

          <button 
            onClick={() => setLang(lang === Language.EN ? Language.ID : Language.EN)}
            className="flex items-center gap-2 px-4 py-2 bg-slate-100 dark:bg-white/5 rounded-xl text-slate-600 dark:text-slate-400 hover:text-brand-500 transition-all font-black text-[11px] uppercase tracking-widest"
          >
            <Languages size={16} className="text-brand-500"/>
            {lang === Language.ID ? 'ID | EN' : 'EN | ID'}
          </button>

          <button 
            onClick={() => onAuthRequest?.('LOGIN')}
            className="text-slate-600 dark:text-slate-400 hover:text-brand-500 font-bold text-[13px] uppercase tracking-widest transition-all flex items-center gap-2"
          >
            <Lock size={16} className="text-brand-500"/>
            {t('Sign In', 'Masuk')}
          </button>
        </div>

        <div className="hidden md:flex items-center space-x-6">
           <button 
