const WelcomeScreen = ({ onFinish, lang }: { onFinish: () => void, lang: Language }) => {
  const [progress, setProgress] = useState(0);
  const [messageIdx, setMessageIdx] = useState(0);

  const messages = lang === Language.EN ? [
    "Greeting Neural Server...",
    "Synchronizing Protection...",
    "Scanning Best Risk Rates...",
