interface DesktopWebsiteProps {
  onEnterPortal: (mode?: 'LOGIN' | 'REGISTER') => void;
  onAdminAccess: () => void;
  currentLang: Language;
  onLangChange: (l: Language) => void;
}

const DesktopWebsite: React.FC<DesktopWebsiteProps> = ({ onEnterPortal, currentLang }) => {
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  const handleMouseMove = (e: React.MouseEvent) => {
    const x = (e.clientX / window.innerWidth) - 0.5;
    const y = (e.clientY / window.innerHeight) - 0.5;
    setMousePos({ x, y });
  };

  return (
    <div 
      onMouseMove={handleMouseMove} 
      className="min-h-screen text-slate-900 dark:text-slate-100 font-sans transition-colors duration-700 overflow-x-hidden relative bg-[#fafaf9] dark:bg-[#0c0a09]"
    >
