      {/* 2. Features Section */}
      <Features currentLang={currentLang} />

      {/* 3. How It Works Section */}
      <HowItWorks currentLang={currentLang} />

      {/* 4. Product Section */}
      <Products onEnterPortal={onEnterPortal} currentLang={currentLang} />

