import React, { useState, useEffect } from 'react';
import { GoogleGenAI } from "@google/genai";
import { Play, Loader2, ShieldCheck, Zap, AlertCircle, RefreshCw, X, Film } from 'lucide-react';

interface VideoDemoProps {
  onClose: () => void;
  lang: 'ID' | 'EN';
}

export const VideoDemo: React.FC<VideoDemoProps> = ({ onClose, lang }) => {
  const [videoUrl, setVideoUrl] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [loadingStep, setLoadingStep] = useState(0);
  const [hasKey, setHasKey] = useState(false);

  const t = (en: string, id: string) => lang === 'EN' ? en : id;

  const loadingMessages = [
    t("Initializing Neural Engine...", "Menyiapkan Mesin Neural..."),
    t("Rendering Visual Audit Process...", "Me-render Proses Audit Visual..."),
    t("Syncing Protection Matrix...", "Sinkronisasi Matriks Proteksi..."),
    t("Finalizing Cinematic Demo...", "Menyelesaikan Demo Sinematik...")
  ];

  useEffect(() => {
    const checkKey = async () => {
      const selected = await window.aistudio.hasSelectedApiKey();
      setHasKey(selected);
    };
    checkKey();
  }, []);

  useEffect(() => {
    let interval: any;
    if (loading) {
      interval = setInterval(() => {
        setLoadingStep(s => (s + 1) % loadingMessages.length);
      }, 5000);
    }
    return () => clearInterval(interval);
  }, [loading]);

  const handleSelectKey = async () => {
    await window.aistudio.openSelectKey();
    setHasKey(true);
  };

  const generateDemoVideo = async () => {
    setLoading(true);
    try {
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      let operation = await ai.models.generateVideos({
        model: 'veo-3.1-fast-generate-preview',
        prompt: "A cinematic 3D high-tech demonstration of 'SurePath AI Distribution Engine'. A sleek smartphone interface scans a white modern SUV with glowing emerald green neural lines. Floating holographic UI elements show real-time risk data and cost calculations. The visual transitions to a glowing digital shield icon and a 'Claim Paid' notification. Soft tech aesthetic, clean indigo background, futuristic professional motion graphics.",
        config: {
          numberOfVideos: 1,
          resolution: '720p',
          aspectRatio: '16:9'
        }
      });

      while (!operation.done) {
        await new Promise(resolve => setTimeout(resolve, 10000));
        operation = await ai.operations.getVideosOperation({ operation: operation });
      }

      const downloadLink = operation.response?.generatedVideos?.[0]?.video?.uri;
      if (downloadLink) {
        const response = await fetch(`${downloadLink}&key=${process.env.API_KEY}`);
        const blob = await response.blob();
        setVideoUrl(URL.createObjectURL(blob));
      }
    } catch (error: any) {
      console.error(error);
      if (error.message?.includes("Requested entity was not found")) {
        setHasKey(false);
        alert(t("API Key expired or invalid. Please select a valid key.", "API Key tidak valid. Silakan pilih kembali."));
      } else {
        alert(t("Failed to generate video. Our neural engine is busy.", "Gagal membuat video. Mesin neural sedang padat."));
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 z-[1000] flex items-center justify-center p-4 md:p-10 bg-slate-950/90 backdrop-blur-2xl animate-fade-in">
      <div className="w-full max-w-5xl bg-white dark:bg-[#0c0c0c] rounded-[3rem] border border-white/10 shadow-[0_0_100px_rgba(16,185,129,0.15)] overflow-hidden flex flex-col relative max-h-[90vh]">

        {/* Header */}
        <div className="p-8 border-b border-black/5 dark:border-white/5 flex items-center justify-between">
          <div className="flex items-center gap-4">
            <div className="w-12 h-12 bg-primary-500/10 rounded-2xl flex items-center justify-center text-primary-500 shadow-inner">
               <Film size={24}/>
            </div>
            <div>
              <p className="text-[0.6rem] font-black uppercase text-gray-500 tracking-[0.3em] mb-1">AI Media Lab</p>
              <h3 className="text-xl font-black uppercase tracking-tighter text-slate-900 dark:text-white">
                SurePath <span className="text-primary-500">Engine Demo</span>
              </h3>
            </div>
          </div>
          <button onClick={onClose} className="p-2.5 bg-gray-100 dark:bg-white/5 rounded-xl hover:bg-rose-500 hover:text-white transition-all">
             <X size={20}/>
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 p-8 flex flex-col items-center justify-center overflow-y-auto no-scrollbar">
          {!hasKey ? (
            <div className="max-w-md text-center space-y-8 py-20">
               <div className="w-20 h-20 bg-amber-500/10 rounded-[2rem] flex items-center justify-center text-amber-500 mx-auto">
                  <AlertCircle size={40}/>
               </div>
               <div className="space-y-3">
                  <h4 className="text-2xl font-black uppercase tracking-tight">{t("API Key Required", "Butuh API Key")}</h4>
                  <p className="text-sm text-gray-500 font-medium leading-relaxed">
                    {t("To generate high-quality AI demonstration videos, you must use your own paid Gemini API Key. Visit ", "Untuk membuat video demo AI berkualitas tinggi, Anda harus menggunakan API Key Gemini berbayar milik sendiri. Kunjungi ")}
                    <a href="https://ai.google.dev/gemini-api/docs/billing" target="_blank" className="text-primary-500 underline">billing documentation</a>
                    {t(" for more info.", " untuk info lebih lanjut.")}
                  </p>
               </div>
               <button 
                 onClick={handleSelectKey}
                 className="w-full py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl active:scale-95 transition-all"
               >
                 {t("Select API Key", "Pilih API Key")}
               </button>
            </div>
          ) : loading ? (
            <div className="flex flex-col items-center justify-center gap-10 py-20 text-center">
               <div className="relative">
                  <div className="w-32 h-32 border-4 border-primary-500/20 rounded-full animate-spin-slow"></div>
                  <div className="absolute inset-0 flex items-center justify-center">
                     <Zap size={48} className="text-primary-500 animate-pulse"/>
                  </div>
               </div>
               <div className="space-y-4">
                  <p className="text-xl font-black uppercase tracking-[0.2em] text-slate-800 dark:text-white">
                    {loadingMessages[loadingStep]}
                  </p>
                  <p className="text-xs text-gray-400 font-bold uppercase tracking-widest">
                    {t("This may take 1-2 minutes. Stay tuned.", "Proses butuh 1-2 menit. Mohon menunggu.")}
                  </p>
               </div>
            </div>
          ) : videoUrl ? (
            <div className="w-full aspect-video bg-black rounded-[2.5rem] overflow-hidden shadow-2xl relative group">
               <video src={videoUrl} controls autoPlay className="w-full h-full object-cover" />
               <button 
                 onClick={() => setVideoUrl(null)}
                 className="absolute top-6 right-6 p-4 bg-black/40 backdrop-blur-md text-white rounded-2xl opacity-0 group-hover:opacity-100 transition-opacity"
               >
                 <RefreshCw size={20}/>
               </button>
            </div>
          ) : (
            <div className="max-w-xl text-center space-y-10 py-10">
               <div className="grid grid-cols-2 gap-4">
                  <div className="p-8 bg-gray-50 dark:bg-white/5 rounded-[3rem] border border-black/5 text-left space-y-3">
                     <ShieldCheck className="text-emerald-500" size={32}/>
                     <h5 className="font-black uppercase text-xs">{t("Visual Audit", "Audit Visual")}</h5>
                     <p className="text-[0.65rem] text-gray-500 font-medium">{t("AI-powered damage detection demonstration.", "Demo deteksi kerusakan berbasis AI.")}</p>
                  </div>
                  <div className="p-8 bg-gray-50 dark:bg-white/5 rounded-[3rem] border border-black/5 text-left space-y-3">
                     <Zap className="text-primary-500" size={32}/>
                     <h5 className="font-black uppercase text-xs">{t("Instant Payout", "Pencairan Instan")}</h5>
                     <p className="text-[0.65rem] text-gray-500 font-medium">{t("Real-time policy activation and claim settlement.", "Aktivasi polis dan pencairan klaim real-time.")}</p>
                  </div>
               </div>
               <div className="space-y-6">
                  <h4 className="text-3xl font-black uppercase tracking-tighter">{t("Ready to See the Future?", "Siap Lihat Masa Depan?")}</h4>
                  <p className="text-sm text-gray-500 font-medium max-w-sm mx-auto">{t("Generate a custom AI video demonstrating SurePath's end-to-end distribution engine capabilities.", "Buat video AI khusus yang mendemonstrasikan kapabilitas mesin distribusi end-to-end SurePath.")}</p>
                  <button 
                    onClick={generateDemoVideo}
                    className="px-12 py-6 bg-primary-500 text-white rounded-[2rem] font-black uppercase text-sm tracking-[0.3em] shadow-xl shadow-primary-500/25 active:scale-95 transition-all flex items-center justify-center gap-4 group mx-auto"
                  >
                    <Play size={20} className="fill-current"/> {t("Generate Demo Video", "Buat Video Demo")}
                  </button>
               </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Home, ShoppingBag, Zap, Info, Shield, Languages, Lock, Menu, X } from 'lucide-react';
