export const Navbar: React.FC<NavbarProps> = ({ lang, setLang, currentPage, setPage, onAuthRequest }) => {
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => setScrolled(window.scrollY > 50);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { id: 'home', icon: Home, label: lang === Language.EN ? 'Home' : 'Beranda' },
    { id: 'products-section', icon: ShoppingBag, label: lang === Language.EN ? 'Products' : 'Produk', isScroll: true },
    { id: 'claim', icon: Zap, label: lang === Language.EN ? 'Klaim AI' : 'Klaim AI' },
    { id: 'about-page', icon: Info, label: lang === Language.EN ? 'About' : 'Tentang', isPage: true },
  ];

  const handleNav = (item: any) => {
    if (item.isScroll) {
      document.getElementById(item.id)?.scrollIntoView({ behavior: 'smooth' });
    } else if (item.isPage) {
      setPage('about');
    } else {
      setPage(item.id);
    }
  };

  return (
    <div className="fixed bottom-10 left-1/2 -translate-x-1/2 z-[500] w-full max-w-fit px-6">
      <nav className="glass-dock px-6 py-4 rounded-[2.5rem] flex items-center gap-2 shadow-2xl">
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => handleNav(item)}
            className={`flex items-center gap-2 px-5 py-3 rounded-full transition-all group ${
              currentPage === item.id ? 'bg-primary-500 text-white' : 'text-gray-400 hover:text-white hover:bg-white/5'
            }`}
          >
            <item.icon size={20} />
            <span className={`text-[10px] font-black uppercase tracking-widest overflow-hidden transition-all duration-300 ${
              currentPage === item.id ? 'w-auto' : 'w-0 group-hover:w-auto'
            }`}>
              {item.label}
            </span>
          </button>
        ))}

        <div className="w-px h-6 bg-white/10 mx-2"></div>

        <button 
          onClick={() => setLang(lang === Language.EN ? Language.ID : Language.EN)}
          className="p-3 text-gray-400 hover:text-white transition-colors"
        >
          <Languages size={20} />
        </button>

        <button 
          onClick={() => onAuthRequest?.('LOGIN')}
          className="ml-2 bg-white text-black px-6 py-3 rounded-full text-[10px] font-black uppercase tracking-widest hover:bg-primary-500 hover:text-white transition-all active:scale-95"
        >
          {lang === Language.EN ? 'Sign In' : 'Masuk'}
        </button>
      </nav>
    </div>
  );
};

