  const [latestPolicy, setLatestPolicy] = useState<Policy | null>(null);

  const products = useMemo(() => INITIAL_PRODUCTS(lang), [lang]);

  useEffect(() => {
    // Sync Tailwind class
    if (darkMode) {
      document.documentElement.classList.add('dark');
