import React, { useState, useMemo, useEffect } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket, Users, HeartPulse, Receipt, Building2, Stethoscope } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, analyzeHealthReceipt, ClaimAnalysisData, DocumentSummary, HealthClaimData } from '../services/geminiService';
import { db, Claim } from '../db';
import { NeuralBot, NeuralProcessingView } from './car-wizard/WizardUI';
import { Language } from '../types';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const ClaimManager = ({ onComplete, lang }: { onComplete: () => void, lang: Language }) => {
  const [claimType, setClaimType] = useState<'AUTO' | 'HEALTH' | null>(null);
  const [step, setStep] = useState<'select' | 'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('select');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [healthResult, setHealthResult] = useState<HealthClaimData | null>(null);
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [photoBase64, setPhotoBase64] = useState<string>('');

  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));
  }, []);

  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);

      if (claimType === 'AUTO') {
        const response = await analyzeClaimPhoto(base64);
        if (response.success && response.data) {
          setClaimResult(response.data);
          setStep('result');
        } else {
          alert(t('Audit failed. Please use a clearer photo.', 'Cek gagal. Mohon gunakan foto yang lebih jelas.'));
          setStep('upload');
        }
      } else if (claimType === 'HEALTH') {
        const response = await analyzeHealthReceipt(base64);
        if (response.success && response.data) {
          setHealthResult(response.data);
          setStep('result');
        } else {
          alert(t('Receipt check failed.', 'Cek kuitansi gagal.'));
          setStep('upload');
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert(t("Tell us more (min. 20 chars).", "Ceritakan kronologi lebih detail (min. 20 karakter)."));
      return;
    }

    if (!currentUser) return;
    setIsSubmitting(true);

    try {
        const amount = claimType === 'AUTO' ? (claimResult?.totalEstimasi || 0) : (healthResult?.totalAmount || 0);

        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            thirdPartyInvolved: reportForm.thirdPartyInvolved,
            status: 'SUBMITTED',
            amountEstimated: amount,
            photos: [photoBase64],
            aiAnalysis: claimType === 'AUTO' ? claimResult : healthResult,
            createdAt: new Date().toISOString()
        };

        await db.claims.add(newClaim);
        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        alert(t("Failed to send claim.", "Gagal mengirim klaim."));
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center gap-3 mb-3">
      {showBack && (
        <button onClick={onBack} className="p-2 bg-slate-100 dark:bg-white/5 rounded-full hover:text-brand-500 transition-colors">
          <ChevronRight className="rotate-180" size={16}/>
        </button>
      )}
      <div className="w-7 h-7 bg-brand-500/10 rounded-lg flex items-center justify-center text-brand-500">
        <ShieldCheck size={16}/>
      </div>
      <h3 className="text-lg font-black uppercase tracking-tight">{title}</h3>
    </div>
  );

  if (step === 'select') {
    return (
      <div className="space-y-6 animate-fade-in flex flex-col h-full justify-center px-4">
        <div className="text-center mb-6">
           <h2 className="text-2xl font-black uppercase tracking-tighter text-slate-800 dark:text-white">
             {t('Instant', 'Lapor')} <span className="text-brand-500">{t('Claim', 'Klaim')}</span>
           </h2>
           <p className="text-xs text-slate-400 font-bold uppercase mt-2 tracking-widest">{t('Select insurance type', 'Pilih jenis asuransi')}</p>
        </div>
        <div className="grid gap-4">
           <button 
             onClick={() => { setClaimType('AUTO'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 shadow-lg flex items-center gap-6 group hover:border-brand-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-blue-50 dark:bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500"><Smartphone size={32}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight dark:text-white">{t('Car Claim', 'Klaim Mobil')}</h3>
                 <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-widest mt-1">{t('AI Photo Audit', 'Cek Foto via AI')}</p>
              </div>
           </button>
           <button 
             onClick={() => { setClaimType('HEALTH'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-slate-100 dark:border-white/5 shadow-lg flex items-center gap-6 group hover:border-brand-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-rose-50 dark:bg-rose-500/10 rounded-2xl flex items-center justify-center text-rose-500"><HeartPulse size={32}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight dark:text-white">{t('Health Claim', 'Klaim Kesehatan')}</h3>
                 <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-widest mt-1">{t('Scan Medical Bills', 'Cek Kuitansi Medis')}</p>
              </div>
           </button>
        </div>
      </div>
    );
  }

  if (step === 'upload') {
    return (
      <div className="space-y-3 animate-fade-in flex flex-col h-full justify-center">
        <Header title={claimType === 'AUTO' ? t("Car Claim", "Klaim Mobil") : t("Health Claim", "Klaim Kesehatan")} showBack onBack={() => setStep('select')} />
        <div className="aspect-[4/3] relative rounded-[2rem] overflow-hidden bg-slate-50 dark:bg-white/5 border-2 border-dashed border-brand-500/30 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-14 h-14 bg-brand-500/10 rounded-full flex items-center justify-center text-brand-500 mb-2 group-hover:scale-110 transition-transform">
            <Camera size={28} />
          </div>
          <p className="text-base font-black uppercase text-slate-400 group-hover:text-brand-500 transition-colors tracking-tight">
            {claimType === 'AUTO' ? t("Snap Damage", "Foto Kerusakan") : t("Snap Receipt", "Foto Kuitansi")}
          </p>
          <p className="text-[0.5rem] text-slate-400 mt-1 font-bold uppercase tracking-widest text-center px-4">
            {claimType === 'AUTO' ? t("Take a photo of the damaged area.", "Ambil foto bagian yang rusak.") : t("Upload hospital billing images.", "Unggah kuitansi rumah sakit.")}
          </p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleUpload} />
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[2.5rem] h-full flex flex-col items-center justify-center animate-pop-in bg-white dark:bg-midnight overflow-hidden">
        <NeuralProcessingView 
          label={t("Checking...", "Sedang Cek...")} 
          sublabel={t("Our AI is verifying the condition and estimating costs.", "AI kami sedang mengecek kondisi dan menghitung biaya.")}
        />
      </div>
    );
  }

  if (step === 'result') {
    return (
      <div className="space-y-4 animate-pop-in h-full flex flex-col pb-2">
        <Header title={t("AI Results", "Hasil Pengecekan AI")} showBack onBack={() => setStep('upload')} />

        <div className="p-6 bg-brand-500/5 rounded-[2rem] border-2 border-brand-500/20 relative flex-shrink-0">
           <p className="text-[0.55rem] font-black uppercase text-brand-500 tracking-[0.3em] mb-1">{t('ESTIMATED AMOUNT', 'ESTIMASI DANA')}</p>
           <h3 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white">
             {formatIDR(claimType === 'AUTO' ? claimResult!.totalEstimasi : healthResult!.totalAmount)}
           </h3>
        </div>

        <div className="flex-1 overflow-y-auto no-scrollbar space-y-4">
           <div className="p-5 bg-white dark:bg-white/5 rounded-2xl border border-black/5">
              <p className="text-[0.5rem] font-black text-slate-400 uppercase mb-2">{t('AI SUMMARY', 'RINGKASAN AI')}</p>
              <p className="text-xs font-medium leading-relaxed italic text-slate-700 dark:text-gray-300">
                "{claimType === 'AUTO' ? claimResult!.aiInsight : healthResult!.diagnosisSummary}"
              </p>
           </div>
        </div>

        <button onClick={() => setStep('reporting')} className="py-5 bg-slate-900 dark:bg-white text-white dark:text-midnight rounded-2xl font-black uppercase text-[0.65rem] tracking-widest shadow-lg flex items-center justify-center gap-3 active:scale-95 transition-all">
          {t('Next Step', 'Lanjut Lapor')} <ArrowRight size={16}/>
        </button>
      </div>
    );
  }

  if (step === 'reporting') {
    return (
      <div className="animate-fade-in flex flex-col h-full">
        <Header title={t("Details", "Detail Kejadian")} showBack onBack={() => setStep('result')} />
        <form onSubmit={handleFinalReport} className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <div className="space-y-1.5">
              <label className="text-[0.5rem] font-black uppercase tracking-widest text-slate-400 ml-1">{t('Date', 'Tanggal')}</label>
              <input type="date" required className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-black/5 text-[0.7rem] font-bold dark:text-white outline-none focus:border-brand-500 transition-all" value={reportForm.date} onChange={(e) => setReportForm({...reportForm, date: e.target.value})} />
            </div>
            <div className="space-y-1.5">
              <label className="text-[0.5rem] font-black uppercase tracking-widest text-slate-400 ml-1">{t('Time', 'Waktu')}</label>
              <input type="time" required className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-black/5 text-[0.7rem] font-bold dark:text-white outline-none focus:border-brand-500 transition-all" value={reportForm.time} onChange={(e) => setReportForm({...reportForm, time: e.target.value})} />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[0.5rem] font-black uppercase tracking-widest text-slate-400 ml-1">{t('Location', 'Lokasi Kejadian')}</label>
            <input type="text" required placeholder={t("Where did it happen?", "Di mana kejadiannya?")} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-black/5 text-[0.7rem] font-bold dark:text-white outline-none focus:border-brand-500 transition-all" value={reportForm.location} onChange={(e) => setReportForm({...reportForm, location: e.target.value})} />
          </div>

          <div className="space-y-1.5">
            <label className="text-[0.5rem] font-black uppercase tracking-widest text-slate-400 ml-1">{t('Incident History', 'Kronologi Singkat')}</label>
            <textarea required rows={4} placeholder={t("Tell us what happened...", "Ceritakan sedikit apa yang terjadi...")} className="w-full px-4 py-3 rounded-xl bg-slate-50 dark:bg-white/5 border border-black/5 text-[0.7rem] font-medium leading-tight dark:text-white outline-none focus:border-brand-500 transition-all resize-none" value={reportForm.chronology} onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})} />
          </div>
        </form>

        <button onClick={handleFinalReport} disabled={isSubmitting} className="mt-4 w-full py-5 bg-brand-500 text-white rounded-2xl font-black uppercase text-[0.65rem] tracking-[0.2em] shadow-xl flex items-center justify-center gap-2 active:scale-95 transition-all disabled:opacity-50">
          {isSubmitting ? <Loader2 className="animate-spin" size={14}/> : <Rocket size={14}/>}
          {t('Send Report', 'Kirim Laporan Sekarang')}
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-6 py-10 animate-pop-in flex flex-col h-full justify-center">
        <div className="w-24 h-24 bg-emerald-500 rounded-[2rem] mx-auto flex items-center justify-center text-white shadow-2xl">
          <CheckCircle2 size={48} strokeWidth={3} />
        </div>
        <div className="space-y-2 px-6">
          <h3 className="text-2xl font-black uppercase tracking-tighter dark:text-white">{t('Report Sent!', 'Laporan Terkirim!') }</h3>
          <p className="text-[0.7rem] text-slate-400 font-bold uppercase tracking-widest leading-relaxed">
            {t('Your claim is being processed. We will update you within 60 minutes.', 'Klaim Anda sedang diproses. Kami akan kabari hasilnya dalam 60 menit.')}
          </p>
        </div>
        <button onClick={onComplete} className="mx-6 py-5 bg-slate-900 dark:bg-white text-white dark:text-midnight rounded-2xl font-black uppercase text-[0.65rem] tracking-widest shadow-xl active:scale-95 transition-all">{t('Finish', 'Selesai')}</button>
      </div>
    );
  }

  return null;
};

