    <circle cx="55" cy="25" r="4" fill="white" />
  </svg>
);

const Navbar: React.FC<NavbarProps> = ({ lang, setLang, darkMode, setDarkMode, currentPage, setPage, onAuthRequest }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  const t = (en: string, id: string) => lang === Language.EN ? en : id;

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { id: 'home', icon: Home, label: t('Home', 'Beranda') },
    { id: 'products-section', icon: ShoppingBag, label: t('Products', 'Produk'), isScroll: true },
    { id: 'about-page', icon: Info, label: t('About', 'Tentang'), isPage: true },
  ];

  return (
    <div className="fixed top-0 left-0 right-0 z-[100] flex justify-center p-4 md:p-6">
      <nav className={`
        relative flex items-center justify-between px-6 py-3 rounded-[2rem] transition-all duration-500 w-full max-w-7xl
        ${isScrolled ? 'glass-titan shadow-2xl scale-[0.98]' : 'bg-transparent'}
      `}>
        {/* Brand */}
        <div 
          className="flex items-center gap-3 cursor-pointer group" 
          onClick={() => { setPage('home'); window.scrollTo({ top: 0, behavior: 'smooth' }); }}
        >
          <SurePathLogo className="w-8 h-8 group-hover:scale-110 transition-transform" />
          <span className="font-black text-xl tracking-tighter uppercase dark:text-white">Sure<span className="text-brand-500">Path</span></span>
        </div>

        {/* Desktop Links */}
        <div className="hidden lg:flex items-center gap-1">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => {
                  if(item.isScroll) document.getElementById(item.id)?.scrollIntoView({ behavior: 'smooth' });
                  else if(item.isPage) setPage('about');
                  else setPage(item.id);
              }}
              className={`px-5 py-2 rounded-full text-[11px] font-black uppercase tracking-widest transition-all ${currentPage === item.id ? 'text-brand-500 bg-brand-500/5' : 'text-slate-500 dark:text-slate-400 hover:text-brand-500'}`}
            >
              {item.label}
            </button>
          ))}
        </div>

        {/* Controls */}
        <div className="flex items-center gap-2">
          <div className="hidden md:flex items-center gap-1 bg-slate-100 dark:bg-white/5 p-1 rounded-full border border-black/5 dark:border-white/5">
            <button 
              onClick={() => setDarkMode(!darkMode)}
              className="p-2 rounded-full hover:bg-white dark:hover:bg-slate-800 transition-all text-slate-500 dark:text-slate-400"
            >
              {darkMode ? <Sun size={16} /> : <Moon size={16} />}
            </button>
            <button 
              onClick={() => setLang(lang === Language.EN ? Language.ID : Language.EN)}
              className="px-3 py-1 text-[10px] font-black uppercase text-slate-500 dark:text-slate-400 hover:text-brand-500"
            >
              {lang}
            </button>
          </div>

          <button 
            onClick={() => onAuthRequest?.('LOGIN')}
            className="flex items-center gap-2 px-6 py-2.5 bg-slate-900 dark:bg-white text-white dark:text-midnight rounded-full text-[11px] font-black uppercase tracking-widest hover:scale-105 active:scale-95 transition-all shadow-xl"
          >
            {t('Sign In', 'Masuk')} <LogIn size={14} />
          </button>

          <button 
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            className="lg:hidden p-2 text-slate-600 dark:text-slate-300"
          >
            {isMenuOpen ? <X size={24} /> : <Menu size={24} />}
          </button>
        </div>
      </nav>

      {/* Mobile Menu */}
      {isMenuOpen && (
        <div className="fixed inset-0 z-[99] bg-white dark:bg-midnight lg:hidden p-8 flex flex-col animate-fade-in">
            <div className="flex justify-between items-center mb-12">
                <SurePathLogo />
                <button onClick={() => setIsMenuOpen(false)}><X size={32}/></button>
            </div>
            <div className="space-y-6 flex-1">
                {navItems.map(item => (
                    <button key={item.id} className="block text-4xl font-black uppercase tracking-tighter text-slate-900 dark:text-white" onClick={() => { setIsMenuOpen(false); setPage(item.id); }}>
                        {item.label}
                    </button>
                ))}
            </div>
            <div className="pt-8 border-t border-black/5 dark:border-white/5 space-y-4">
                <div className="flex gap-4">
                    <button onClick={() => setDarkMode(!darkMode)} className="flex-1 p-4 bg-slate-100 dark:bg-white/5 rounded-2xl font-bold uppercase text-xs">Theme</button>
                    <button onClick={() => setLang(lang === Language.EN ? Language.ID : Language.EN)} className="flex-1 p-4 bg-slate-100 dark:bg-white/5 rounded-2xl font-bold uppercase text-xs">Language: {lang}</button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

