import React, { useState, useMemo } from 'react';
import { 
  User, Lock, Eye, EyeOff, ShieldCheck, ArrowRight, AlertCircle, RefreshCw, Smartphone, KeyRound, Sparkles, Terminal
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db } from '../db';
import { verifyPassword } from '../services/authService';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
  initialMode?: 'LOGIN' | 'REGISTER';
}

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID, initialMode = 'LOGIN' }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'ADMIN'>('LOGIN');
  const [lang] = useState<Language>(initialLang);
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({ email: '', password: '' });

  const t = (en: string, id: string) => lang === Language.EN ? en : id;

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setError(null);

    try {
      const user = await db.users.where('email').equals(formData.email).first();
      if (user && user.passwordHash && user.salt) {
        const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
        if (isValid) {
          onAuthSuccess(user);
        } else {
          setError(t("Incorrect password.", "Password salah."));
        }
      } else {
        setError(t("Account not found.", "Akun tidak ditemukan."));
      }
    } catch (err) {
      setError(t("Login error.", "Gagal masuk."));
    } finally {
      setLoading(false);
    }
  };

  const handleDemoAccess = async (role: UserRole) => {
    setLoading(true);
    const email = role === UserRole.MASTER_ADMIN ? 'master@surepath.ai' : 'user@surepath.ai';
    const user = await db.users.where('email').equals(email).first();
    setTimeout(() => {
        if(user) onAuthSuccess(user);
        setLoading(false);
    }, 1000);
  };

  return (
    <div className="w-full max-w-md mx-auto space-y-8 animate-fade-in">
      <div className="text-center space-y-3">
        <div className="inline-block p-4 bg-white dark:bg-[#111] rounded-[2rem] shadow-xl border border-slate-100 dark:border-white/5 mb-4">
           <SurePathLogo className="w-12 h-12" />
        </div>
        <h1 className="text-3xl font-black tracking-tighter uppercase dark:text-white">
            {mode === 'ADMIN' ? 'HQ Access' : t('Welcome', 'Selamat Datang')}
        </h1>
        <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest leading-none">
            {mode === 'ADMIN' ? 'SurePath Internal Terminal' : t('Secure Login System', 'Sistem Masuk Aman')}
        </p>
      </div>

      <div className="bg-white dark:bg-[#0c0c0c] rounded-[2.5rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5 space-y-6">
        <div className="flex bg-slate-100 dark:bg-white/5 p-1 rounded-2xl">
          <button onClick={() => setMode('LOGIN')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-brand-600 shadow-sm' : 'text-slate-400'}`}>{t('Member', 'Anggota')}</button>
          <button onClick={() => setMode('ADMIN')} className={`flex-1 py-3 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${mode === 'ADMIN' ? 'bg-white dark:bg-slate-700 text-brand-600 shadow-sm' : 'text-slate-400'}`}>{t('Admin', 'Admin')}</button>
        </div>

        {mode === 'ADMIN' ? (
            <div className="space-y-4 animate-fade-in">
                <div className="p-5 bg-primary-500/5 border border-primary-500/10 rounded-2xl space-y-4">
                    <div className="flex items-center gap-4">
                        <div className="w-10 h-10 bg-primary-500 rounded-xl flex items-center justify-center text-white"><Terminal size={20}/></div>
                        <div>
                            <p className="text-[11px] font-black uppercase dark:text-white">Testing Node</p>
                            <p className="text-[9px] font-bold text-slate-400 uppercase">Akses Dashboard Admin Cepat</p>
                        </div>
                    </div>
                    <button onClick={() => handleDemoAccess(UserRole.MASTER_ADMIN)} className="w-full py-4 bg-primary-500 text-white rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center justify-center gap-2">
                        {loading ? <RefreshCw className="animate-spin" size={14}/> : <Sparkles size={14}/>}
                        Masuk Sebagai Master Admin
                    </button>
                </div>
                <p className="text-[10px] text-center text-slate-400 font-medium">Gunakan akun ini untuk menguji fitur manajemen polis dan log keamanan.</p>
            </div>
        ) : (
            <form onSubmit={handleAuth} className="space-y-4 animate-fade-in">
                <div className="space-y-4">
                    <div className="relative group">
                        <User size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
                        <input 
                            required type="email" placeholder="Email Address"
                            className="w-full pl-12 pr-4 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm"
                            value={formData.email} onChange={(e) => setFormData({...formData, email: e.target.value})}
                        />
                    </div>
                    <div className="relative group">
                        <KeyRound size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-brand-500 transition-colors" />
                        <input 
                            required type={showPass ? 'text' : 'password'} placeholder="Password"
                            className="w-full pl-12 pr-12 py-4 bg-slate-50 dark:bg-white/[0.03] border-2 border-slate-100 dark:border-white/5 rounded-2xl outline-none transition-all font-bold text-sm"
                            value={formData.password} onChange={(e) => setFormData({...formData, password: e.target.value})}
                        />
                        <button type="button" onClick={() => setShowPass(!showPass)} className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300">
                            {showPass ? <EyeOff size={18}/> : <Eye size={18}/>}
                        </button>
                    </div>
                </div>

                {error && (
                    <div className="p-3 bg-rose-500/10 border border-rose-500/20 rounded-xl flex items-center gap-2 text-rose-500 text-[10px] font-bold">
                        <AlertCircle size={14}/> {error}
                    </div>
                )}

                <button type="submit" disabled={loading} className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-midnight rounded-xl font-black uppercase text-[10px] tracking-widest shadow-xl flex items-center justify-center gap-3">
                    {loading ? <RefreshCw className="animate-spin" size={16}/> : <ShieldCheck size={16}/>}
                    {t('Login Now', 'Masuk Sekarang')}
                </button>

                <div className="pt-4 border-t border-black/5 dark:border-white/5">
                    <button type="button" onClick={() => handleDemoAccess(UserRole.CUSTOMER)} className="w-full py-4 bg-emerald-500/10 text-emerald-600 rounded-xl font-black uppercase text-[10px] tracking-widest border border-emerald-500/20">
                        Demo: Masuk Sebagai Nasabah
                    </button>
                </div>
            </form>
        )}
      </div>

      <p className="text-center text-[10px] font-bold text-slate-400 uppercase tracking-widest">© 2025 SurePath Security Protocol</p>
    </div>
  );
};

export default AuthGate;

