        const user = parseSessionToken(savedToken);
        if (user) {
          setCurrentUser(user);
          setAppMode(true);
          db.policies.where('userId').equals(user.id).toArray().then(res => {
            if (res.length > 0) setLatestPolicy(res.sort((a,b) => b.id! - a.id!)[0]);
          });
        } else {
          localStorage.removeItem('SUREPATH_SESSION_TOKEN');
        }
      }
    };
    initializeApp();
