const Navbar = ({ currentPage, setPage }: { currentPage: string, setPage: (p: string) => void }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [mobileMenu, setMobileMenu] = useState(false);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { id: 'home', label: 'Beranda' },
    { id: 'products', label: 'Pilihan Asuransi' },
    { id: 'claims', label: 'Cara Klaim' },
    { id: 'about', label: 'Tentang Kami' },
  ];

  return (
    <nav className={`fixed top-0 left-0 right-0 z-[1000] transition-all duration-300 ${isScrolled ? 'bg-white/90 backdrop-blur-md py-4 shadow-sm' : 'bg-transparent py-6'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <SurePathLogo />

        <div className="hidden lg:flex items-center gap-10">
          {navItems.map(item => (
            <button 
              key={item.id}
              onClick={() => setPage(item.id)}
              className={`text-sm font-bold uppercase tracking-widest transition-colors ${currentPage === item.id ? 'text-emerald-600' : 'text-slate-500 hover:text-emerald-500'}`}
            >
              {item.label}
            </button>
          ))}
        </div>

        <div className="hidden lg:flex items-center gap-4">
          <button className="p-2 text-slate-400 hover:text-emerald-500 transition-colors">
            <Globe size={20} />
          </button>
          <button 
            onClick={() => setPage('auth')}
            className="flex items-center gap-2 px-6 py-3 bg-slate-900 text-white rounded-2xl text-xs font-bold uppercase tracking-widest hover:bg-emerald-600 transition-all shadow-md"
          >
            <User size={16} />
            Masuk Akun
          </button>
        </div>

        <button onClick={() => setMobileMenu(!mobileMenu)} className="lg:hidden p-2 text-slate-900">
          {mobileMenu ? <X size={28} /> : <Menu size={28} />}
        </button>
      </div>

      {mobileMenu && (
        <div className="lg:hidden absolute top-full left-0 right-0 bg-white border-t border-slate-100 p-8 shadow-2xl animate-fade-in flex flex-col gap-6">
          {navItems.map(item => (
            <button 
              key={item.id}
              onClick={() => { setPage(item.id); setMobileMenu(false); }}
              className="text-2xl font-black text-slate-900 text-left uppercase tracking-tighter"
            >
              {item.label}
            </button>
          ))}
          <button 
            onClick={() => { setPage('auth'); setMobileMenu(false); }}
            className="w-full py-5 bg-emerald-600 text-white rounded-2xl font-bold text-lg"
          >
            Masuk Akun
          </button>
        </div>
      )}
    </nav>
  );
};

