import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import Hero from './components/landing/Hero';
import Features from './components/landing/Features';
import AuthGate from './components/AuthGate';
import CarInsuranceWizard from './components/CarInsuranceWizard';
import TravelInsuranceWizard from './components/TravelInsuranceWizard';
import PAInsuranceWizard from './components/PAInsuranceWizard';
import MPARInsuranceWizard from './components/MPARInsuranceWizard';
import ClaimManager from './components/ClaimManager';
import UserProfile from './components/UserProfile';
import AgentsWallet from './components/AgentsWallet';
import HealthChat from './components/HealthChat';
import { Section, Button, Card, Badge } from './components/shared/UI';
import { db, seedDatabase } from './db';
import { Language } from './types';
import { Car, Plane, HeartPulse, Package, MessageCircle, ShieldCheck, ArrowRight } from 'lucide-react';

const App = () => {
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [lang, setLang] = useState<Language>(Language.ID);

  useEffect(() => {
    seedDatabase();
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setPage('home');
  };

  const renderProducts = () => {
    const products = [
      { id: 'car', name: 'Asuransi Mobil', icon: Car, color: 'text-blue-500', bg: 'bg-blue-50', desc: 'Lindungi kendaraan Anda dari lecet hingga kehilangan.' },
      { id: 'travel', name: 'Asuransi Travel', icon: Plane, color: 'text-emerald-500', bg: 'bg-emerald-50', desc: 'Perjalanan aman ke seluruh dunia, bebas rasa cemas.' },
      { id: 'health', name: 'Kecelakaan Diri', icon: HeartPulse, color: 'text-rose-500', bg: 'bg-rose-50', desc: 'Jaminan kesehatan saat hal tak terduga terjadi.' },
      { id: 'mpar', name: 'Barang Berharga', icon: Package, color: 'text-amber-500', bg: 'bg-amber-50', desc: 'Proteksi untuk gadget, elektronik, dan perabotan Anda.' }
    ];

    return (
      <Section id="products" className="bg-white">
        <div className="flex flex-col md:flex-row justify-between items-end mb-12 gap-6">
          <div className="space-y-4">
            <Badge variant="info">Proteksi Hari Ini</Badge>
            <h2 className="text-4xl md:text-5xl font-black text-slate-900 tracking-tighter leading-none">
              Pilih Apa yang Ingin <br/>
              <span className="text-emerald-600">Anda Lindungi.</span>
            </h2>
          </div>
          <Button variant="outline">Lihat Semua Produk</Button>
        </div>

        <div className="grid md:grid-cols-2 lg:grid-cols-4 gap-6">
          {products.map(p => (
            <Card key={p.id} className="group" onClick={() => setPage(`buy-${p.id}`)}>
              <div className={`w-14 h-14 rounded-2xl ${p.bg} ${p.color} flex items-center justify-center mb-8 shadow-inner group-hover:scale-110 transition-transform`}>
                <p.icon size={28} />
              </div>
              <h3 className="text-xl font-bold text-slate-900 mb-2">{p.name}</h3>
              <p className="text-sm text-slate-500 leading-relaxed font-medium mb-6">{p.desc}</p>
              <div className="flex items-center gap-2 text-emerald-600 font-bold text-xs uppercase tracking-widest">
                Mulai Daftar <ArrowRight size={14} />
              </div>
            </Card>
          ))}
        </div>
      </Section>
    );
  };

  const renderContent = () => {
    // If inside a wizard or manager, return that view
    if (currentPage === 'buy-car') return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-travel') return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-health') return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-mpar') return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'claims') return <ClaimManager onComplete={() => setPage('home')} lang={lang} />;
    if (currentPage === 'auth') return <AuthGate onAuthSuccess={handleAuthSuccess} />;
    if (currentPage === 'profile') return <UserProfile currentUser={currentUser} lang={lang} onLogout={handleLogout} />;
    if (currentPage === 'wallet') return <AgentsWallet lang={lang} />;
    if (currentPage === 'chat') return <HealthChat onBack={() => setPage('home')} lang={lang} />;

    // Main Landing Page Structure
    return (
      <main className="animate-fade-in">
        <Hero onAction={() => setPage('products')} />
        {renderProducts()}
        <Features />

        {/* Call to Action Section */}
        <Section className="bg-slate-900 text-white overflow-hidden rounded-[4rem] mx-6 md:mx-12 lg:mx-24 mb-20 relative">
          <div className="absolute top-0 right-0 p-20 opacity-10"><ShieldCheck size={300} /></div>
          <div className="max-w-3xl space-y-8 relative z-10">
            <h2 className="text-5xl md:text-6xl font-black tracking-tighter leading-none">
              Siap Merasakan <br/>
              <span className="text-emerald-400">Asuransi Masa Depan?</span>
            </h2>
            <p className="text-lg text-slate-400 font-medium">
              Bergabunglah bersama ribuan orang lainnya yang telah beralih ke SurePath. Cepat, aman, dan tanpa biaya tersembunyi.
            </p>
            <div className="flex gap-4">
              <Button size="lg" onClick={() => setPage('products')}>Daftar Sekarang</Button>
              <Button variant="ghost" className="text-white hover:bg-white/10" onClick={() => setPage('claims')}>Pelajari Klaim</Button>
            </div>
          </div>
        </Section>

        {/* Minimal Footer */}
        <footer className="py-20 px-6 border-t border-slate-100 text-center">
          <div className="flex flex-col items-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-8 h-8 bg-emerald-500 rounded-lg flex items-center justify-center text-white shadow-lg">
                <ShieldCheck size={18} />
              </div>
              <span className="font-extrabold text-xl tracking-tighter text-slate-900">Sure<span className="text-emerald-500">Path</span></span>
            </div>
            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest">© 2025 SurePath Insurtech. Terdaftar & Diawasi oleh OJK Indonesia.</p>
          </div>
        </footer>
      </main>
    );
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] font-sans selection:bg-emerald-100 selection:text-emerald-900">
      <Navbar currentPage={currentPage} setPage={setPage} />

      {renderContent()}

      {/* Floating Action Button for Chat Assistance */}
      {currentPage !== 'chat' && (
        <button 
          onClick={() => setPage('chat')}
          className="fixed bottom-10 right-10 w-16 h-16 bg-emerald-600 text-white rounded-full shadow-2xl flex items-center justify-center hover:scale-110 transition-transform active:scale-95 z-[500] group"
        >
          <MessageCircle size={28} />
          <div className="absolute right-full mr-4 bg-slate-900 text-white px-4 py-2 rounded-xl text-xs font-bold whitespace-nowrap opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none uppercase tracking-widest shadow-xl">
            Tanya Asisten SurePath
          </div>
        </button>
      )}
    </div>
  );
};

export default App;

