// Highly reusable Button component
// Fixed: Added React.FC typing and made children optional, added xl size and ghost variant
export const Button: React.FC<{ 
  children?: React.ReactNode, 
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost',
  size?: 'sm' | 'md' | 'lg' | 'xl',
  icon?: any,
  onClick?: () => void,
  className?: string,
  disabled?: boolean
}> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  icon: Icon, 
  onClick,
  className = "",
  disabled = false
}) => {
  const variants = {
    primary: "bg-emerald-600 text-white hover:bg-emerald-700 shadow-md hover:shadow-emerald-200",
    secondary: "bg-slate-900 text-white hover:bg-slate-800 shadow-md",
    outline: "bg-transparent border-2 border-slate-200 text-slate-700 hover:border-emerald-500 hover:text-emerald-600",
    ghost: "bg-transparent text-slate-500 hover:bg-slate-50"
  };

  const sizes = {
    sm: "px-4 py-2 text-xs",
    md: "px-8 py-4 text-sm font-bold",
    lg: "px-10 py-5 text-base font-bold",
    xl: "px-12 py-6 text-base font-bold"
  };

  return (
    <button 
      disabled={disabled}
      onClick={onClick}
      className={`rounded-2xl transition-all flex items-center justify-center gap-3 disabled:opacity-50 disabled:cursor-not-allowed ${variants[variant]} ${sizes[size as keyof typeof sizes] || sizes.md} ${className}`}
    >
      {children}
      {Icon && <Icon size={18} />}
    </button>
  );
};

