import AuthGate from './components/AuthGate';
import CarInsuranceWizard from './components/CarInsuranceWizard';
import TravelInsuranceWizard from './components/TravelInsuranceWizard';
import PAInsuranceWizard from './components/PAInsuranceWizard';
import MPARInsuranceWizard from './components/MPARInsuranceWizard';
import ClaimManager from './components/ClaimManager';
import UserProfile from './components/UserProfile';
import HealthChat from './components/HealthChat';
import { db, seedDatabase } from './db';
import { Language } from './types';

const App = () => {
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [lang, setLang] = useState<Language>(Language.ID);

  useEffect(() => {
    seedDatabase();
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) {
      try {
        setCurrentUser(JSON.parse(saved));
      } catch (e) {
        console.error("Session corrupted", e);
        localStorage.removeItem('SUREPATH_SESSION');
      }
    }

    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setPage('home');
  };

  const renderMainContent = () => {
    // Buy Wizards (Fullscreen Overlay)
    if (currentPage === 'buy-car') return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-travel') return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-pa') return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-mpar') return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;

    // Core App Features
    if (currentPage === 'claims') return <ClaimManager onComplete={() => setPage('home')} lang={lang} />;
    if (currentPage === 'help') return <HealthChat onBack={() => setPage('home')} lang={lang} />;
    if (currentPage === 'profile') return <UserProfile currentUser={currentUser} lang={lang} onLogout={handleLogout} />;
    if (currentPage === 'auth') return <AuthGate onAuthSuccess={handleAuthSuccess} />;

    // Device-Specific View
    if (isMobile) {
      if (!currentUser) return <AuthGate onAuthSuccess={handleAuthSuccess} />;
      return <MobilePortal currentUser={currentUser} setPage={setPage} lang={lang} />;
    } else {
      // For desktop, if logged in and on home, we still show landing but with 'Account' access
      // or we can redirect to a dashboard. For now, landing is the focus.
      return <DesktopLanding onStart={() => setPage(currentUser ? 'products' : 'auth')} lang={lang} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] font-sans text-slate-900 selection:bg-emerald-100 selection:text-emerald-900">
      {!isMobile && !currentPage.startsWith('buy-') && currentPage !== 'auth' && (
        <Navbar currentPage={currentPage} setPage={setPage} />
      )}

      <main className="animate-fade-in transition-all duration-700">
        {renderMainContent()}
      </main>

      {/* Modern Mobile Bottom Navigation Tab Bar */}
      {isMobile && currentUser && !currentPage.startsWith('buy-') && currentPage !== 'auth' && (
        <nav className="fixed bottom-8 left-6 right-6 h-22 bg-white/90 dark:bg-[#111]/90 backdrop-blur-2xl z-[70] flex items-center justify-around px-6 rounded-[3rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.2)] border border-slate-100 transition-all duration-500">
           {[
             { id: 'home', label: 'Beranda', icon: HomeIcon },
             { id: 'products', label: 'Produk', icon: ShoppingBagIcon },
             { id: 'claims', label: 'Klaim', icon: ZapIcon },
             { id: 'profile', label: 'Akun', icon: UserIcon }
           ].map(item => (
             <button 
               key={item.id}
               onClick={() => setPage(item.id)}
               className={`flex flex-col items-center gap-2 flex-1 py-4 transition-all duration-500 active:scale-90 ${currentPage === item.id ? 'text-emerald-600 scale-110 -translate-y-1' : 'text-slate-400'}`}
             >
               <item.icon size={26} strokeWidth={2.5} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(16,185,129,0.4)]' : ''} />
               <span className="text-[10px] font-black uppercase tracking-widest">{item.label}</span>
             </button>
           ))}
        </nav>
      )}
    </div>
  );
};

// Simplified SVG Icons for the Bottom Nav
const HomeIcon = ({ size, className, strokeWidth }: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>;
const ShoppingBagIcon = ({ size, className, strokeWidth }: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>;
const ZapIcon = ({ size, className, strokeWidth }: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/></svg>;
const UserIcon = ({ size, className, strokeWidth }: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M19 21v-2a4 4 0 0 0-4-4H9a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>;

export default App;

import React, { useState, useEffect } from 'react';
import { ShieldCheck, User, Globe, ChevronDown, LogOut } from 'lucide-react';

export const SurePathLogo = ({ className = "w-10 h-10" }: { className?: string }) => (
  <div className={`flex items-center gap-2 ${className}`}>
    <div className="w-10 h-10 bg-emerald-500 rounded-xl flex items-center justify-center text-white shadow-lg">
      <ShieldCheck size={24} />
    </div>
    <span className="font-black text-2xl tracking-tighter text-slate-900 uppercase">Sure<span className="text-emerald-500">Path</span></span>
  </div>
);

const Navbar = ({ currentPage, setPage }: { currentPage: string, setPage: (p: string) => void }) => {
  const [isScrolled, setIsScrolled] = useState(false);
  const [currentUser, setCurrentUser] = useState<any>(null);

  useEffect(() => {
    const handleScroll = () => setIsScrolled(window.scrollY > 20);
    window.addEventListener('scroll', handleScroll);

    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));

    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const navItems = [
    { id: 'home', label: 'Beranda' },
    { id: 'products', label: 'Pilihan Proteksi' },
    { id: 'claims', label: 'Jalur Klaim' },
    { id: 'about', label: 'Ekosistem Kami' },
  ];

  return (
    <nav className={`fixed top-0 left-0 right-0 z-[1000] transition-all duration-500 ${isScrolled ? 'bg-white/80 backdrop-blur-md py-4 shadow-sm border-b border-slate-100' : 'bg-transparent py-8'}`}>
      <div className="max-w-7xl mx-auto px-6 flex justify-between items-center">
        <div className="cursor-pointer" onClick={() => setPage('home')}>
           <SurePathLogo />
        </div>

        <div className="hidden lg:flex items-center gap-12">
          {navItems.map(item => (
            <button 
              key={item.id}
              onClick={() => setPage(item.id)}
              className={`text-[10px] font-black uppercase tracking-[0.25em] transition-all relative group ${currentPage === item.id ? 'text-emerald-600' : 'text-slate-500 hover:text-emerald-500'}`}
            >
              {item.label}
              <span className={`absolute -bottom-2 left-0 h-0.5 bg-emerald-500 transition-all duration-300 ${currentPage === item.id ? 'w-full' : 'w-0 group-hover:w-full'}`}></span>
            </button>
          ))}
        </div>

        <div className="hidden lg:flex items-center gap-6">
          <button className="text-slate-400 hover:text-emerald-500 transition-colors p-2 bg-slate-50 rounded-xl">
            <Globe size={18} />
          </button>

          {currentUser ? (
            <button 
               onClick={() => setPage('profile')}
               className="flex items-center gap-3 pl-2 pr-5 py-2 bg-white rounded-2xl border border-slate-100 shadow-sm hover:shadow-md transition-all active:scale-95 group"
            >
               <div className="w-9 h-9 bg-emerald-500 rounded-xl flex items-center justify-center text-white text-sm font-black uppercase">
                  {currentUser.name[0]}
               </div>
               <div className="text-left leading-none">
                  <p className="text-[10px] font-black uppercase text-slate-900">{currentUser.name.split(' ')[0]}</p>
                  <p className="text-[8px] font-bold uppercase text-slate-400 tracking-widest mt-1">Status: Secure</p>
               </div>
               <ChevronDown size={14} className="text-slate-300 group-hover:text-emerald-500 transition-colors"/>
            </button>
          ) : (
            <button 
              onClick={() => setPage('auth')}
              className="px-8 py-3.5 bg-slate-900 text-white rounded-2xl text-[10px] font-black uppercase tracking-[0.2em] hover:bg-emerald-600 transition-all shadow-xl active:scale-95"
            >
              Masuk Akun
            </button>
          )}
        </div>
      </div>
    </nav>
  );
};

export default Navbar;

import React, { useState, useMemo, useEffect } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket, Users, HeartPulse, Receipt, Building2, Stethoscope, RefreshCw } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, analyzeHealthReceipt, ClaimAnalysisData, DocumentSummary, HealthClaimData } from '../services/geminiService';
import { db, Claim } from '../db';
import { NeuralBot, NeuralProcessingView, AnimatedCheckmark } from './car-wizard/WizardUI';
import { Language } from '../types';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const DRAFT_KEY = 'SUREPATH_CLAIM_DRAFT';

const ClaimManager = ({ onComplete, lang }: { onComplete: () => void, lang: Language }) => {
  const [claimType, setClaimType] = useState<'AUTO' | 'HEALTH' | null>(null);
  const [step, setStep] = useState<'select' | 'upload' | 'analyzing' | 'result' | 'docUpload' | 'docSummary' | 'reporting' | 'success'>('select');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [healthResult, setHealthResult] = useState<HealthClaimData | null>(null);
  const [docSummary, setDocSummary] = useState<DocumentSummary | null>(null);
  const [isSummarizing, setIsSummarizing] = useState(false);
  const [activeTab, setActiveTab] = useState<'evidence' | 'reasoning' | 'steps'>('evidence');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [photoBase64, setPhotoBase64] = useState<string>('');

  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Translation helper
  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  // Load User and Draft on mount
  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));

    const draft = localStorage.getItem(DRAFT_KEY);
    if (draft) {
      try {
        const parsed = JSON.parse(draft);
        setClaimType(parsed.claimType);
        setStep(parsed.step === 'success' ? 'select' : parsed.step); // Don't resume into success step
        setClaimResult(parsed.claimResult);
        setHealthResult(parsed.healthResult);
        setPhotoBase64(parsed.photoBase64);
        if (parsed.reportForm) setReportForm(parsed.reportForm);
      } catch (e) {
        console.error("Failed to load draft", e);
      }
    }
  }, []);

  // Save Draft whenever state changes
  useEffect(() => {
    if (step !== 'success' && step !== 'select') {
      const draftData = {
        claimType,
        step,
        claimResult,
        healthResult,
        photoBase64,
        reportForm,
        lastUpdated: new Date().toISOString()
      };
      localStorage.setItem(DRAFT_KEY, JSON.stringify(draftData));
    }
  }, [claimType, step, claimResult, healthResult, photoBase64, reportForm]);

  const clearDraft = () => {
    localStorage.removeItem(DRAFT_KEY);
  };

  const resetClaim = () => {
    clearDraft();
    setClaimType(null);
    setStep('select');
    setClaimResult(null);
    setHealthResult(null);
    setPhotoBase64('');
    setReportForm({
      chronology: '',
      location: '',
      date: new Date().toISOString().split('T')[0],
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
      thirdPartyInvolved: false
    });
  };

  const dateLimits = useMemo(() => {
    const today = new Date();
    const max = today.toISOString().split('T')[0];
    const minDate = new Date();
    minDate.setDate(today.getDate() - 7);
    const min = minDate.toISOString().split('T')[0];
    return { min, max };
  }, []);

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);

      if (claimType === 'AUTO') {
        const response = await analyzeClaimPhoto(base64);
        if (response.success && response.data) {
          setClaimResult(response.data);
          setStep('result');
        } else {
          alert(response.error || t('Neural audit failed. Please use a clearer photo.', 'Audit neural gagal. Mohon gunakan foto yang lebih jelas.'));
          setStep('upload');
        }
      } else if (claimType === 'HEALTH') {
        const response = await analyzeHealthReceipt(base64);
        if (response.success && response.data) {
          setHealthResult(response.data);
          setStep('result');
        } else {
          alert(response.error || t('Medical receipt audit failed.', 'Audit neural kuitansi gagal.'));
          setStep('upload');
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const handleDocUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSummarizing(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await summarizeClaimDocument(base64);
      setIsSummarizing(false);
      if (response.success && response.data) {
        setDocSummary(response.data);
        setStep('docSummary');
      } else {
        alert(response.error || t('Failed to summarize document.', 'Gagal meringkas dokumen.'));
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert(t("Provide more chronology details (min. 20 characters).", "Berikan kronologi lebih detail (min. 20 karakter)."));
      return;
    }

    if (!currentUser) return;
    setIsSubmitting(true);

    try {
        const amount = claimType === 'AUTO' ? (claimResult?.totalEstimasi || 0) : (healthResult?.totalAmount || 0);

        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            thirdPartyInvolved: reportForm.thirdPartyInvolved,
            status: 'SUBMITTED',
            amountEstimated: amount,
            photos: [photoBase64],
            aiAnalysis: claimType === 'AUTO' ? claimResult : healthResult,
            createdAt: new Date().toISOString()
        };

        await db.claims.add(newClaim);

        // Log to Admin Audit
        await db.auditLogs.add({
          timestamp: new Date().toISOString(),
          actor: currentUser.name,
          domain: 'OPERATIONS',
          action: `NEW_CLAIM_SUBMITTED: ${claimType}`,
          payload: JSON.stringify({ amount })
        });

        clearDraft();
        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        console.error("Claim save failed", error);
        alert(t("Failed to save claim.", "Gagal menyimpan klaim."));
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center justify-between mb-4">
      <div className="flex items-center gap-3">
        {showBack && (
          <button onClick={onBack} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:text-primary-500 transition-colors">
            <ChevronRight className="rotate-180" size={16}/>
          </button>
        )}
        <div className="w-8 h-8 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500 shadow-inner">
          <ShieldCheck size={20}/>
        </div>
        <h3 className="text-lg font-black uppercase tracking-tight text-slate-800 dark:text-white">{title}</h3>
      </div>
      {(step !== 'select' && step !== 'success') && (
        <button onClick={resetClaim} className="flex items-center gap-2 px-3 py-1.5 bg-gray-100 dark:bg-white/5 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:text-rose-500 transition-all">
          <RefreshCw size={12}/> {t('Restart', 'Ulangi')}
        </button>
      )}
    </div>
  );

  if (step === 'select') {
    return (
      <div className="space-y-6 animate-fade-in flex flex-col h-full justify-center px-4">
        <div className="text-center mb-8">
           <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-800 dark:text-white">{t('Express', 'Lapor')} <span className="text-primary-500">{t('Claims', 'Klaim')}</span></h2>
           <p className="text-[10px] text-gray-500 dark:text-gray-400 font-bold uppercase mt-3 tracking-[0.2em]">{t('Select your protection node', 'Pilih asuransi yang ingin diklaim')}</p>
        </div>
        <div className="grid gap-5">
           <button 
             onClick={() => { setClaimType('AUTO'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-white/5 shadow-xl flex items-center gap-8 group hover:border-primary-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-blue-50 dark:bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 shadow-inner group-hover:scale-110 transition-transform"><Car size={36}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight text-slate-900 dark:text-white">{t('Vehicle', 'Kendaraan')}</h3>
                 <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">{t('AI Visual Damage Audit', 'Audit Kerusakan Visual AI')}</p>
              </div>
           </button>
           <button 
             onClick={() => { setClaimType('HEALTH'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-white/5 shadow-xl flex items-center gap-8 group hover:border-primary-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-rose-50 dark:bg-rose-500/10 rounded-2xl flex items-center justify-center text-rose-500 shadow-inner group-hover:scale-110 transition-transform"><HeartPulse size={36}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight text-slate-900 dark:text-white">{t('Health', 'Kesehatan')}</h3>
                 <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">{t('Neural Receipt Analysis', 'Analisa Kuitansi Neural')}</p>
              </div>
           </button>
        </div>
      </div>
    );
  }

  if (step === 'upload') {
    return (
      <div className="space-y-4 animate-fade-in flex flex-col h-full justify-center">
        <Header title={claimType === 'AUTO' ? t("Vehicle Claim", "Klaim Kendaraan") : t("Health Claim", "Klaim Kesehatan")} showBack onBack={() => setStep('select')} />
        <div className="aspect-[4/3] relative rounded-[3rem] overflow-hidden bg-gray-50 dark:bg-white/5 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-20 h-20 bg-primary-500/10 rounded-3xl flex items-center justify-center text-primary-500 mb-4 group-hover:scale-110 transition-transform">
            <Camera size={40} />
          </div>
          <p className="text-xl font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">
            {claimType === 'AUTO' ? t("Snap Evidence", "Ambil Foto") : t("Upload Billing", "Upload Billing")}
          </p>
          <p className="text-[10px] text-gray-400 dark:text-gray-500 mt-2 font-bold uppercase tracking-widest text-center px-8">
            {claimType === 'AUTO' ? t("Take a clear photo of the damaged area.", "Foto bagian kendaraan yang rusak dengan jelas.") : t("Upload medical receipts or hospital billing.", "Unggah kuitansi medis atau billing RS.")}
          </p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleUpload} />
        </div>
        <div className="grid grid-cols-2 gap-3 pt-2">
           <div className="p-5 rounded-2xl bg-white dark:bg-white/5 border border-black/5 flex items-center gap-4">
              <ShieldCheck className="text-emerald-500" size={20}/>
              <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Secure Protocol</span>
           </div>
           <div className="p-5 rounded-2xl bg-white dark:bg-white/5 border border-black/5 flex items-center gap-4">
              <Rocket className="text-primary-500" size={20}/>
              <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Fast-Path Link</span>
           </div>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[3rem] h-full flex flex-col items-center justify-center animate-pop-in bg-white dark:bg-midnight overflow-hidden">
        <NeuralProcessingView 
          label={claimType === 'AUTO' ? t("Visual Audit", "Audit Visual") : t("Data Extraction", "Ekstraksi Data")} 
          sublabel={claimType === 'AUTO' ? t("AI is analyzing panel integrity and repair costs...", "AI sedang menganalisa integritas panel dan biaya perbaikan...") : t("Neural OCR is parsing billing items...", "Neural OCR sedang memproses item billing...")}
        />
      </div>
    );
  }

  if (step === 'result') {
    if (claimType === 'AUTO' && claimResult) {
      return (
        <div className="space-y-4 animate-pop-in h-full flex flex-col pb-4">
          <Header title={t("Neural Audit Result", "Hasil Audit AI")} showBack onBack={() => setStep('upload')} />
          <div className="p-6 bg-primary-500/5 rounded-[3rem] border-2 border-primary-500/20 relative overflow-hidden flex-shrink-0 shadow-xl">
            <div className="absolute top-4 right-4">
