  const [isSubmitting, setIsSubmitting] = useState(false);

  // Translation helper
  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  // Load User and Draft on mount
  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));

    const draft = localStorage.getItem(DRAFT_KEY);
    if (draft) {
      try {
        const parsed = JSON.parse(draft);
        setClaimType(parsed.claimType);
        setStep(parsed.step === 'success' ? 'select' : parsed.step); // Don't resume into success step
        setClaimResult(parsed.claimResult);
        setHealthResult(parsed.healthResult);
        setPhotoBase64(parsed.photoBase64);
        if (parsed.reportForm) setReportForm(parsed.reportForm);
      } catch (e) {
        console.error("Failed to load draft", e);
      }
    }
  }, []);

  // Save Draft whenever state changes
  useEffect(() => {
    if (step !== 'success' && step !== 'select') {
      const draftData = {
        claimType,
        step,
        claimResult,
        healthResult,
        photoBase64,
        reportForm,
        lastUpdated: new Date().toISOString()
      };
      localStorage.setItem(DRAFT_KEY, JSON.stringify(draftData));
    }
  }, [claimType, step, claimResult, healthResult, photoBase64, reportForm]);

  const clearDraft = () => {
    localStorage.removeItem(DRAFT_KEY);
  };

  const resetClaim = () => {
    clearDraft();
    setClaimType(null);
    setStep('select');
    setClaimResult(null);
    setHealthResult(null);
    setPhotoBase64('');
    setReportForm({
      chronology: '',
      location: '',
      date: new Date().toISOString().split('T')[0],
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
      thirdPartyInvolved: false
    });
  };

  const dateLimits = useMemo(() => {
    const today = new Date();
    const max = today.toISOString().split('T')[0];
    const minDate = new Date();
    minDate.setDate(today.getDate() - 7);
    const min = minDate.toISOString().split('T')[0];
    return { min, max };
  }, []);

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);

      if (claimType === 'AUTO') {
        const response = await analyzeClaimPhoto(base64);
        if (response.success && response.data) {
          setClaimResult(response.data);
          setStep('result');
        } else {
          alert(response.error || t('Neural audit failed. Please use a clearer photo.', 'Audit neural gagal. Mohon gunakan foto yang lebih jelas.'));
          setStep('upload');
        }
      } else if (claimType === 'HEALTH') {
        const response = await analyzeHealthReceipt(base64);
        if (response.success && response.data) {
          setHealthResult(response.data);
          setStep('result');
        } else {
          alert(response.error || t('Medical receipt audit failed.', 'Audit neural kuitansi gagal.'));
          setStep('upload');
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const handleDocUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setIsSummarizing(true);
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      const response = await summarizeClaimDocument(base64);
      setIsSummarizing(false);
      if (response.success && response.data) {
        setDocSummary(response.data);
        setStep('docSummary');
      } else {
        alert(response.error || t('Failed to summarize document.', 'Gagal meringkas dokumen.'));
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 20) {
      alert(t("Provide more chronology details (min. 20 characters).", "Berikan kronologi lebih detail (min. 20 karakter)."));
      return;
    }

    if (!currentUser) return;
    setIsSubmitting(true);

    try {
        const amount = claimType === 'AUTO' ? (claimResult?.totalEstimasi || 0) : (healthResult?.totalAmount || 0);

        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            thirdPartyInvolved: reportForm.thirdPartyInvolved,
            status: 'SUBMITTED',
            amountEstimated: amount,
            photos: [photoBase64],
            aiAnalysis: claimType === 'AUTO' ? claimResult : healthResult,
            createdAt: new Date().toISOString()
        };

        await db.claims.add(newClaim);

        // Log to Admin Audit
        await db.auditLogs.add({
          timestamp: new Date().toISOString(),
          actor: currentUser.name,
          domain: 'OPERATIONS',
          action: `NEW_CLAIM_SUBMITTED: ${claimType}`,
          payload: JSON.stringify({ amount })
        });

        clearDraft();
        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        console.error("Claim save failed", error);
        alert(t("Failed to save claim.", "Gagal menyimpan klaim."));
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center justify-between mb-4">
      <div className="flex items-center gap-3">
        {showBack && (
          <button onClick={onBack} className="p-2 bg-gray-100 dark:bg-white/5 rounded-full hover:text-primary-500 transition-colors">
            <ChevronRight className="rotate-180" size={16}/>
          </button>
        )}
        <div className="w-8 h-8 bg-primary-500/10 rounded-lg flex items-center justify-center text-primary-500 shadow-inner">
          <ShieldCheck size={20}/>
        </div>
        <h3 className="text-lg font-black uppercase tracking-tight text-slate-800 dark:text-white">{title}</h3>
      </div>
      {(step !== 'select' && step !== 'success') && (
        <button onClick={resetClaim} className="flex items-center gap-2 px-3 py-1.5 bg-gray-100 dark:bg-white/5 rounded-xl text-[10px] font-black uppercase text-gray-400 hover:text-rose-500 transition-all">
          <RefreshCw size={12}/> {t('Restart', 'Ulangi')}
        </button>
      )}
    </div>
  );

  if (step === 'select') {
    return (
      <div className="space-y-6 animate-fade-in flex flex-col h-full justify-center px-4">
        <div className="text-center mb-8">
           <h2 className="text-3xl font-black uppercase tracking-tighter text-slate-800 dark:text-white">{t('Express', 'Lapor')} <span className="text-primary-500">{t('Claims', 'Klaim')}</span></h2>
           <p className="text-[10px] text-gray-500 dark:text-gray-400 font-bold uppercase mt-3 tracking-[0.2em]">{t('Select your protection node', 'Pilih asuransi yang ingin diklaim')}</p>
        </div>
        <div className="grid gap-5">
           <button 
             onClick={() => { setClaimType('AUTO'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-white/5 shadow-xl flex items-center gap-8 group hover:border-primary-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-blue-50 dark:bg-blue-500/10 rounded-2xl flex items-center justify-center text-blue-500 shadow-inner group-hover:scale-110 transition-transform"><Car size={36}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight text-slate-900 dark:text-white">{t('Vehicle', 'Kendaraan')}</h3>
                 <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">{t('AI Visual Damage Audit', 'Audit Kerusakan Visual AI')}</p>
              </div>
           </button>
           <button 
             onClick={() => { setClaimType('HEALTH'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-white/5 shadow-xl flex items-center gap-8 group hover:border-primary-500/50 transition-all active:scale-95"
           >
              <div className="w-16 h-16 bg-rose-50 dark:bg-rose-500/10 rounded-2xl flex items-center justify-center text-rose-500 shadow-inner group-hover:scale-110 transition-transform"><HeartPulse size={36}/></div>
              <div className="text-left">
                 <h3 className="font-black text-xl uppercase tracking-tight text-slate-900 dark:text-white">{t('Health', 'Kesehatan')}</h3>
                 <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">{t('Neural Receipt Analysis', 'Analisa Kuitansi Neural')}</p>
              </div>
           </button>
        </div>
      </div>
    );
  }

  if (step === 'upload') {
    return (
      <div className="space-y-4 animate-fade-in flex flex-col h-full justify-center">
        <Header title={claimType === 'AUTO' ? t("Vehicle Claim", "Klaim Kendaraan") : t("Health Claim", "Klaim Kesehatan")} showBack onBack={() => setStep('select')} />
        <div className="aspect-[4/3] relative rounded-[3rem] overflow-hidden bg-gray-50 dark:bg-white/5 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-20 h-20 bg-primary-500/10 rounded-3xl flex items-center justify-center text-primary-500 mb-4 group-hover:scale-110 transition-transform">
            <Camera size={40} />
          </div>
          <p className="text-xl font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">
            {claimType === 'AUTO' ? t("Snap Evidence", "Ambil Foto") : t("Upload Billing", "Upload Billing")}
          </p>
          <p className="text-[10px] text-gray-400 dark:text-gray-500 mt-2 font-bold uppercase tracking-widest text-center px-8">
            {claimType === 'AUTO' ? t("Take a clear photo of the damaged area.", "Foto bagian kendaraan yang rusak dengan jelas.") : t("Upload medical receipts or hospital billing.", "Unggah kuitansi medis atau billing RS.")}
          </p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleUpload} />
        </div>
        <div className="grid grid-cols-2 gap-3 pt-2">
           <div className="p-5 rounded-2xl bg-white dark:bg-white/5 border border-black/5 flex items-center gap-4">
              <ShieldCheck className="text-emerald-500" size={20}/>
              <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Secure Protocol</span>
           </div>
           <div className="p-5 rounded-2xl bg-white dark:bg-white/5 border border-black/5 flex items-center gap-4">
              <Rocket className="text-primary-500" size={20}/>
              <span className="text-[10px] font-black uppercase tracking-widest text-gray-500">Fast-Path Link</span>
           </div>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[3rem] h-full flex flex-col items-center justify-center animate-pop-in bg-white dark:bg-midnight overflow-hidden">
        <NeuralProcessingView 
          label={claimType === 'AUTO' ? t("Visual Audit", "Audit Visual") : t("Data Extraction", "Ekstraksi Data")} 
          sublabel={claimType === 'AUTO' ? t("AI is analyzing panel integrity and repair costs...", "AI sedang menganalisa integritas panel dan biaya perbaikan...") : t("Neural OCR is parsing billing items...", "Neural OCR sedang memproses item billing...")}
        />
      </div>
    );
  }

  if (step === 'result') {
    if (claimType === 'AUTO' && claimResult) {
      return (
        <div className="space-y-4 animate-pop-in h-full flex flex-col pb-4">
          <Header title={t("Neural Audit Result", "Hasil Audit AI")} showBack onBack={() => setStep('upload')} />
          <div className="p-6 bg-primary-500/5 rounded-[3rem] border-2 border-primary-500/20 relative overflow-hidden flex-shrink-0 shadow-xl">
            <div className="absolute top-4 right-4">
              <div className="px-3 py-1 bg-primary-500 text-white rounded-lg font-black text-[10px] uppercase tracking-widest">{claimResult.severity} Impact</div>
            </div>
            <p className="text-[10px] font-black uppercase text-primary-500 tracking-[0.3em] mb-2">{t('Est. Repair Cost', 'Estimasi Biaya')}</p>
            <h3 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white mb-2">{formatIDR(claimResult.totalEstimasi)}</h3>
            <p className="text-xs font-bold text-gray-600 dark:text-gray-300 leading-relaxed border-l-4 border-primary-500 pl-4 py-1 italic">"{claimResult.aiInsight}"</p>
          </div>

          <div className="flex bg-gray-100 dark:bg-white/5 p-1 rounded-2xl text-[10px] font-black uppercase tracking-widest border border-black/5 shadow-inner">
              <button onClick={() => setActiveTab('evidence')} className={`flex-1 py-3 rounded-xl transition-all ${activeTab === 'evidence' ? 'bg-white dark:bg-gray-800 shadow-md text-primary-500' : 'text-gray-400'}`}>{t('Analysis', 'Analisa')}</button>
              <button onClick={() => setActiveTab('reasoning')} className={`flex-1 py-3 rounded-xl transition-all ${activeTab === 'reasoning' ? 'bg-white dark:bg-gray-800 shadow-md text-primary-500' : 'text-gray-400'}`}>{t('Workshop', 'Bengkel')}</button>
          </div>

          <div className="flex-1 overflow-y-auto no-scrollbar space-y-3">
            {activeTab === 'evidence' && (
              <div className="animate-fade-in space-y-3">
                {claimResult.rincianPart?.map((p, i) => (
                  <div key={i} className="p-5 bg-white dark:bg-slate-900 rounded-[2rem] border border-black/5 flex items-center justify-between shadow-sm group hover:border-primary-500/30 transition-all">
                    <div className="flex-1">
                      <p className="font-black uppercase text-xs tracking-tight text-slate-800 dark:text-white leading-none mb-1.5">{p.namaPart}</p>
                      <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">{p.kondisi}</p>
                    </div>
                    <div className="text-right">
                      <p className="font-black text-xs text-primary-500">{formatIDR(p.estimasiBiaya)}</p>
                    </div>
                  </div>
                ))}
              </div>
            )}
            {activeTab === 'reasoning' && (
              <div className="p-6 space-y-6 animate-fade-in bg-white dark:bg-slate-900 rounded-[3rem] border border-black/5 shadow-lg">
                 <div className="space-y-2">
                    <p className="text-[10px] font-black text-primary-500 uppercase tracking-widest">{t('Technical Reasoning', 'Alasan Teknis')}</p>
                    <p className="text-sm font-medium leading-relaxed text-slate-700 dark:text-gray-300">{claimResult.technicalReasoning}</p>
                 </div>
                 <div className="p-5 bg-primary-50 dark:bg-primary-950/20 rounded-2xl border border-primary-100 dark:border-primary-900/30">
                    <div className="flex items-center gap-3 mb-2">
                       <Building2 size={16} className="text-primary-500"/>
                       <p className="text-[10px] font-black text-primary-600 uppercase tracking-widest">{t('Workshop Recommendation', 'Rekomendasi Bengkel')}</p>
                    </div>
                    <p className="text-sm font-black text-slate-800 dark:text-white uppercase">{claimResult.rekomendasiBengkel}</p>
                 </div>
              </div>
            )}
          </div>

          <button onClick={() => setStep('reporting')} className="py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3">
             {t('Continue to Report', 'Lanjut Lapor')} <ArrowRight size={18}/>
          </button>
        </div>
      );
    } else if (claimType === 'HEALTH' && healthResult) {
      return (
        <div className="space-y-4 animate-pop-in h-full flex flex-col pb-4">
           <Header title={t("Neural Receipt Audit", "Hasil Audit Kuitansi")} showBack onBack={() => setStep('upload')} />
           <div className="p-8 bg-rose-500/5 rounded-[3rem] border-2 border-rose-500/20 relative overflow-hidden flex-shrink-0 shadow-xl">
              <div className="absolute top-0 right-0 p-8 opacity-10"><HeartPulse size={120}/></div>
              <p className="text-[10px] font-black uppercase text-rose-500 tracking-[0.3em] mb-2">{t('Total Hospital Charge', 'Total Biaya RS')}</p>
              <h3 className="text-4xl font-black tracking-tighter text-slate-900 dark:text-white leading-none">{formatIDR(healthResult.totalAmount)}</h3>
              <div className="flex items-center gap-2 mt-6">
                 <div className="w-6 h-6 bg-emerald-500/10 text-emerald-500 rounded-lg flex items-center justify-center">
                    <CheckCircle2 size={14}/>
                 </div>
                 <span className="text-[10px] font-black text-emerald-600 uppercase tracking-widest">{t('Integrity Score:', 'Skor Integritas:')} {healthResult.confidenceScore}%</span>
              </div>
           </div>

           <div className="flex-1 overflow-y-auto no-scrollbar space-y-4">
              <div className="grid grid-cols-2 gap-4">
                 <div className="p-5 bg-white dark:bg-slate-900 rounded-3xl border border-black/5 shadow-sm">
                    <p className="text-[10px] font-black text-gray-400 uppercase mb-2 tracking-widest">{t('Provider', 'Faskes')}</p>
                    <p className="text-xs font-black uppercase flex items-center gap-2 text-slate-900 dark:text-white"><Building2 size={14} className="text-primary-500"/> {healthResult.hospitalName}</p>
                 </div>
                 <div className="p-5 bg-white dark:bg-slate-900 rounded-3xl border border-black/5 shadow-sm">
                    <p className="text-[10px] font-black text-gray-400 uppercase mb-2 tracking-widest">{t('Date', 'Tanggal')}</p>
                    <p className="text-xs font-black uppercase flex items-center gap-2 text-slate-900 dark:text-white"><Calendar size={14} className="text-primary-500"/> {healthResult.treatmentDate}</p>
                 </div>
              </div>

              <div className="p-6 bg-white dark:bg-slate-900 rounded-[2.5rem] border border-black/5 shadow-md">
                 <p className="text-[10px] font-black text-gray-400 uppercase mb-4 flex items-center gap-3 tracking-widest"><Stethoscope size={16} className="text-rose-500"/> {t('Diagnosis Narrative', 'Narasi Diagnosa')}</p>
                 <p className="text-sm font-medium leading-relaxed italic text-slate-700 dark:text-gray-300">"{healthResult.diagnosisSummary}"</p>
              </div>

              <div className="space-y-3">
                 <p className="text-[10px] font-black text-gray-400 uppercase ml-3 tracking-[0.2em]">{t('Billing Breakdown', 'Rincian Tagihan')}</p>
                 <div className="space-y-2">
                   {healthResult.billingItems?.map((item, idx) => (
                      <div key={idx} className="p-5 bg-gray-50/50 dark:bg-white/5 rounded-2xl flex justify-between items-center border border-black/5 transition-all hover:bg-white dark:hover:bg-white/[0.08]">
                         <span className="text-[11px] font-black uppercase text-slate-600 dark:text-gray-400 tracking-tight">{item.item}</span>
                         <span className="text-xs font-black text-slate-900 dark:text-white font-mono">{formatIDR(item.cost)}</span>
                      </div>
                   ))}
                 </div>
              </div>
           </div>

           <button onClick={() => setStep('reporting')} className="py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl transition-all active:scale-95 flex items-center justify-center gap-3">
             <Rocket size={18}/> {t('Authorize Reimbursement', 'Otorisasi Klaim')}
           </button>
        </div>
      );
    }
  }

  if (step === 'reporting') {
    return (
      <div className="animate-fade-in flex flex-col h-full">
        <Header title={t("Incident Registry", "Laporan Kejadian")} showBack onBack={() => setStep('result')} />
        <form onSubmit={handleFinalReport} className="flex-1 overflow-y-auto pr-1 no-scrollbar space-y-6">
          <div className="grid grid-cols-2 gap-4">
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-gray-500 ml-2">{t('Date of Event', 'Tanggal Kejadian')}</label>
              <div className="relative">
                <Calendar size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="date" required 
                  min={dateLimits.min} max={dateLimits.max}
                  className="w-full pl-11 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 text-sm outline-none focus:border-primary-500 font-bold transition-all shadow-sm" 
                  value={reportForm.date}
                  onChange={(e) => setReportForm({...reportForm, date: e.target.value})}
                />
              </div>
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black uppercase tracking-widest text-gray-500 ml-2">{t('Time', 'Waktu')}</label>
              <div className="relative">
                <Clock size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="time" required 
                  className="w-full pl-11 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 text-sm outline-none focus:border-primary-500 font-bold transition-all shadow-sm" 
                  value={reportForm.time}
                  onChange={(e) => setReportForm({...reportForm, time: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-gray-500 ml-2">{t('Event Location', 'Lokasi Kejadian')}</label>
            <div className="relative">
              <MapPin size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-primary-500" />
              <input 
                type="text" required placeholder={t("Detailed location...", "Alamat atau lokasi...")}
                className="w-full pl-11 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border border-black/5 text-sm outline-none focus:border-primary-500 font-bold transition-all shadow-sm" 
                value={reportForm.location}
                onChange={(e) => setReportForm({...reportForm, location: e.target.value})}
              />
            </div>
          </div>

          <div className="space-y-2">
            <label className="text-[10px] font-black uppercase tracking-widest text-gray-500 ml-2">{t('Event Chronology', 'Kronologi Kejadian')}</label>
            <textarea 
              required rows={4} placeholder={t("Describe what happened in detail (min 20 chars)...", "Ceritakan detail kejadian (minimal 20 karakter)...")}
              className="w-full px-5 py-4 rounded-[2rem] bg-white dark:bg-white/5 border border-black/5 text-sm outline-none focus:border-primary-500 resize-none font-medium leading-relaxed shadow-inner" 
              value={reportForm.chronology}
              onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})}
            />
            <p className={`text-[9px] font-bold uppercase tracking-widest ml-3 ${reportForm.chronology.length < 20 ? 'text-rose-400' : 'text-emerald-500'}`}>
               {reportForm.chronology.length}/20 chars
            </p>
          </div>

          <div className="pt-2">
            <label className={`flex items-center gap-5 p-6 bg-white dark:bg-white/5 border-2 rounded-[2.5rem] cursor-pointer transition-all shadow-sm ${reportForm.thirdPartyInvolved ? 'border-primary-500/40 bg-primary-500/[0.02]' : 'border-black/5'}`}>
              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 text-white shadow-lg shadow-primary-500/20' : 'bg-gray-100 dark:bg-white/10 text-gray-400 shadow-inner'}`}>
                <Users size={28}/>
              </div>
              <div className="flex-1">
                <p className="text-sm font-black uppercase tracking-tight text-slate-800 dark:text-white">{t('Third Party Involved?', 'Pihak Ketiga Terlibat?')}</p>
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest mt-1">{t('Check if other people/vehicles are involved.', 'Centang jika ada orang atau kendaraan lain.')}</p>
              </div>
              <div className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 border-primary-500 text-white shadow-md' : 'border-gray-200 dark:border-white/10'}`}>
                {reportForm.thirdPartyInvolved && <CheckCircle2 size={18} strokeWidth={3}/>}
              </div>
              <input 
                type="checkbox" 
                className="hidden" 
                checked={reportForm.thirdPartyInvolved}
                onChange={(e) => setReportForm({...reportForm, thirdPartyInvolved: e.target.checked})}
              />
            </label>
          </div>
        </form>

        <button 
          onClick={handleFinalReport} disabled={isSubmitting || reportForm.chronology.length < 20}
          className="mt-6 w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.3em] shadow-2xl flex items-center justify-center gap-3 disabled:opacity-30 transition-all active:scale-95 group overflow-hidden relative"
        >
          <div className="absolute inset-0 bg-primary-500 translate-y-full group-hover:translate-y-0 transition-transform duration-500 opacity-20"></div>
          {isSubmitting ? <Loader2 className="animate-spin" size={20}/> : <Rocket size={20} className="relative z-10"/>}
          <span className="relative z-10">{t('Initialize Neural Submission', 'Kirim Laporan Klaim')}</span>
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-8 py-10 animate-pop-in flex flex-col h-full justify-center items-center">
        <div className="relative">
           <div className="absolute inset-0 bg-emerald-500/20 blur-[60px] rounded-full animate-pulse scale-150"></div>
           <div className="w-28 h-28 bg-emerald-500 rounded-[2.5rem] flex items-center justify-center text-white shadow-2xl shadow-emerald-500/30 relative z-10">
             <CheckCircle2 size={64} strokeWidth={3} className="animate-pop-in" />
           </div>
        </div>
        <div className="space-y-4 px-6">
          <h3 className="text-4xl font-black uppercase tracking-tighter text-slate-900 dark:text-white leading-none">{t('Claim Success!', 'Klaim Berhasil!')}</h3>
          <p className="text-xs text-gray-500 dark:text-gray-400 leading-relaxed font-bold uppercase tracking-widest max-w-sm mx-auto">
            {t('Neural protocol initiated. Your report has been validated and synced with the insurance core system. Expect updates within', 'Protokol neural diaktifkan. Laporan Anda telah divalidasi dan disinkronkan ke sistem utama. Update akan tersedia dalam')} <span className="text-primary-500">60 {t('minutes', 'menit')}</span>.
          </p>
        </div>

        <div className="w-full max-w-sm p-6 rounded-[2.5rem] bg-gray-50 dark:bg-white/5 border border-black/5 text-left space-y-3 shadow-inner">
          <p className="text-[10px] font-black text-gray-400 uppercase tracking-[0.2em]">Deployment Ledger Hash</p>
          <p className="text-[11px] font-mono text-primary-500 break-all leading-tight opacity-80 uppercase">SP-NODE-{Date.now().toString().slice(-8)}-LEDGER</p>
          <div className="flex items-center gap-2 pt-2 border-t border-black/5 mt-2">
             <ShieldCheck size={14} className="text-emerald-500"/>
             <span className="text-[9px] font-black uppercase text-gray-400 tracking-widest">End-to-End Encrypted Registry</span>
          </div>
        </div>

        <button onClick={onComplete} className="w-full max-w-sm py-5 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.3em] shadow-xl transition-all active:scale-95 border border-white/10">{t('Back to Dashboard', 'Kembali ke Beranda')}</button>
      </div>
    );
  }

  return null;
};

export default ClaimManager;

