import React, { useState, useMemo, useEffect } from 'react';
import { Camera, BrainCircuit, CheckCircle2, Scan, Smartphone, ArrowRight, MapPin, Calendar, Clock, FileText, AlertCircle, Loader2, FileSearch, Trash2, ShieldCheck, ChevronRight, Info, Rocket, Users, HeartPulse, Receipt, Building2, Stethoscope, RefreshCw } from 'lucide-react';
import { analyzeClaimPhoto, summarizeClaimDocument, analyzeHealthReceipt, ClaimAnalysisData, DocumentSummary, HealthClaimData } from '../services/geminiService';
import { db, Claim } from '../db';
import { NeuralBot, NeuralProcessingView } from './car-wizard/WizardUI';
import { Language } from '../types';

const formatIDR = (num: number) => {
  return new Intl.NumberFormat('id-ID', {
    style: 'currency', currency: 'IDR', minimumFractionDigits: 0
  }).format(num);
};

interface ReportForm {
  chronology: string;
  location: string;
  date: string;
  time: string;
  thirdPartyInvolved: boolean;
}

const DRAFT_KEY = 'SUREPATH_CLAIM_DRAFT';

const ClaimManager = ({ onComplete, lang }: { onComplete: () => void, lang: Language }) => {
  const [claimType, setClaimType] = useState<'AUTO' | 'HEALTH' | null>(null);
  const [step, setStep] = useState<'select' | 'upload' | 'analyzing' | 'result' | 'reporting' | 'success'>('select');
  const [claimResult, setClaimResult] = useState<ClaimAnalysisData | null>(null);
  const [healthResult, setHealthResult] = useState<HealthClaimData | null>(null);
  const [activeTab, setActiveTab] = useState<'evidence' | 'reasoning' | 'steps'>('evidence');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [photoBase64, setPhotoBase64] = useState<string>('');
  const [reportForm, setReportForm] = useState<ReportForm>({
    chronology: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
    thirdPartyInvolved: false
  });
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Translation helper
  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  // Load persistence: user session and draft claim
  useEffect(() => {
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) setCurrentUser(JSON.parse(saved));

    const draft = localStorage.getItem(DRAFT_KEY);
    if (draft) {
      try {
        const parsed = JSON.parse(draft);
        setClaimType(parsed.claimType);
        setStep(parsed.step === 'success' ? 'select' : parsed.step);
        setClaimResult(parsed.claimResult);
        setHealthResult(parsed.healthResult);
        setPhotoBase64(parsed.photoBase64);
        if (parsed.reportForm) setReportForm(parsed.reportForm);
      } catch (e) {
        console.error("Draft corrupted", e);
      }
    }
  }, []);

  // Save draft whenever state changes
  useEffect(() => {
    if (step !== 'success' && step !== 'select') {
      const draftData = {
        claimType,
        step,
        claimResult,
        healthResult,
        photoBase64,
        reportForm,
        lastUpdated: new Date().toISOString()
      };
      localStorage.setItem(DRAFT_KEY, JSON.stringify(draftData));
    }
  }, [claimType, step, claimResult, healthResult, photoBase64, reportForm]);

  const resetClaim = () => {
    localStorage.removeItem(DRAFT_KEY);
    setClaimType(null);
    setStep('select');
    setClaimResult(null);
    setHealthResult(null);
    setPhotoBase64('');
    setReportForm({
      chronology: '',
      location: '',
      date: new Date().toISOString().split('T')[0],
      time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit', hour12: false }),
      thirdPartyInvolved: false
    });
  };

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setStep('analyzing');
    const reader = new FileReader();
    reader.onload = async () => {
      const base64 = reader.result as string;
      setPhotoBase64(base64);

      if (claimType === 'AUTO') {
        const response = await analyzeClaimPhoto(base64);
        if (response.success && response.data) {
          setClaimResult(response.data);
          setStep('result');
        } else {
          alert(response.error || t('Neural audit failed.', 'Audit neural gagal.'));
          setStep('upload');
        }
      } else if (claimType === 'HEALTH') {
        const response = await analyzeHealthReceipt(base64);
        if (response.success && response.data) {
          setHealthResult(response.data);
          setStep('result');
        } else {
          alert(response.error || t('Receipt parsing failed.', 'Parsing kuitansi gagal.'));
          setStep('upload');
        }
      }
    };
    reader.readAsDataURL(file);
  };

  const handleFinalReport = async (e: React.FormEvent) => {
    e.preventDefault();
    if (reportForm.chronology.length < 10) {
      alert(t("Provide more chronology details.", "Berikan kronologi lebih detail."));
      return;
    }

    if (!currentUser) return;
    setIsSubmitting(true);

    try {
        const amount = claimType === 'AUTO' ? (claimResult?.totalEstimasi || 0) : (healthResult?.totalAmount || 0);

        const newClaim: Claim = {
            userId: currentUser.id,
            date: reportForm.date,
            time: reportForm.time,
            location: reportForm.location,
            chronology: reportForm.chronology,
            thirdPartyInvolved: reportForm.thirdPartyInvolved,
            status: 'SUBMITTED',
            amountEstimated: amount,
            photos: [photoBase64],
            aiAnalysis: claimType === 'AUTO' ? claimResult : healthResult,
            createdAt: new Date().toISOString()
        };

        await db.claims.add(newClaim);
        localStorage.removeItem(DRAFT_KEY);

        setTimeout(() => {
            setIsSubmitting(false);
            setStep('success');
        }, 1500);
    } catch (error) {
        console.error("Claim save failed", error);
        alert(t("Failed to submit claim.", "Gagal mengirim klaim."));
        setIsSubmitting(false);
    }
  };

  const Header = ({ title, showBack = false, onBack = () => {} }: { title: string, showBack?: boolean, onBack?: () => void }) => (
    <div className="flex items-center justify-between mb-6">
      <div className="flex items-center gap-4">
        {showBack && (
          <button onClick={onBack} className="p-3 bg-gray-50 dark:bg-white/5 rounded-2xl hover:text-primary-500 transition-colors border border-black/5">
            <ChevronRight className="rotate-180" size={20}/>
          </button>
        )}
        <div className="w-10 h-10 bg-primary-500/10 rounded-xl flex items-center justify-center text-primary-500 shadow-inner">
          <ShieldCheck size={24}/>
        </div>
        <h3 className="text-xl font-black uppercase tracking-tight text-slate-900 dark:text-white">{title}</h3>
      </div>
      {(step !== 'select' && step !== 'success') && (
        <button onClick={resetClaim} className="p-3 bg-gray-50 dark:bg-white/5 rounded-2xl text-gray-400 hover:text-rose-500 transition-all border border-black/5">
           <RefreshCw size={20}/>
        </button>
      )}
    </div>
  );

  if (step === 'select') {
    return (
      <div className="space-y-10 animate-fade-in flex flex-col h-full justify-center px-4">
        <div className="text-center space-y-4">
           <Badge variant="brand">{t('Neural Claim Acceleration', 'Akselerasi Klaim Neural')}</Badge>
           <h2 className="text-4xl font-black uppercase tracking-tighter text-slate-900 dark:text-white leading-tight">{t('Submit', 'Laporkan')} <span className="text-primary-500">{t('Express Claim', 'Klaim Kilat')}</span></h2>
           <p className="text-sm text-gray-500 font-bold uppercase tracking-widest max-w-xs mx-auto opacity-60">{t('Zero paperwork. Pure visual AI.', 'Tanpa kertas. AI visual murni.')}</p>
        </div>
        <div className="grid gap-5">
           <button 
             onClick={() => { setClaimType('AUTO'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-white/5 shadow-xl flex items-center gap-8 group hover:border-primary-500 transition-all active:scale-95"
           >
              <div className="w-20 h-20 bg-blue-50 dark:bg-blue-500/10 rounded-3xl flex items-center justify-center text-blue-500 group-hover:scale-110 transition-transform shadow-inner"><Car size={40}/></div>
              <div className="text-left">
                 <h3 className="font-black text-2xl uppercase tracking-tight">{t('Vehicle', 'Kendaraan')}</h3>
                 <p className="text-xs font-bold text-gray-400 uppercase tracking-[0.2em] mt-2">{t('Visual AI damage audit', 'Audit kerusakan visual AI')}</p>
              </div>
           </button>
           <button 
             onClick={() => { setClaimType('HEALTH'); setStep('upload'); }}
             className="p-8 bg-white dark:bg-slate-900 rounded-[3rem] border border-slate-100 dark:border-white/5 shadow-xl flex items-center gap-8 group hover:border-primary-500 transition-all active:scale-95"
           >
              <div className="w-20 h-20 bg-rose-50 dark:bg-rose-500/10 rounded-3xl flex items-center justify-center text-rose-500 group-hover:scale-110 transition-transform shadow-inner"><HeartPulse size={40}/></div>
              <div className="text-left">
                 <h3 className="font-black text-2xl uppercase tracking-tight">{t('Health', 'Kesehatan')}</h3>
                 <p className="text-xs font-bold text-gray-400 uppercase tracking-[0.2em] mt-2">{t('Neural receipt extraction', 'Ekstraksi kuitansi neural')}</p>
              </div>
           </button>
        </div>
      </div>
    );
  }

  if (step === 'upload') {
    return (
      <div className="space-y-6 animate-fade-in flex flex-col h-full justify-center">
        <Header title={claimType === 'AUTO' ? t("Vehicle Audit", "Audit Kendaraan") : t("Medical Audit", "Audit Medis")} showBack onBack={() => setStep('select')} />
        <div className="aspect-square md:aspect-video relative rounded-[3rem] overflow-hidden bg-gray-50 dark:bg-white/5 border-2 border-dashed border-primary-500/20 flex flex-col items-center justify-center group cursor-pointer shadow-inner">
          <div className="w-24 h-24 bg-primary-500/10 rounded-[2rem] flex items-center justify-center text-primary-500 mb-6 group-hover:scale-110 transition-transform shadow-xl">
            <Camera size={48} />
          </div>
          <p className="text-2xl font-black uppercase text-gray-400 group-hover:text-primary-500 transition-colors tracking-tight">
            {claimType === 'AUTO' ? t("Snap Evidence", "Ambil Foto") : t("Upload Receipt", "Unggah Kuitansi")}
          </p>
          <p className="text-xs text-gray-400 dark:text-gray-500 mt-3 font-bold uppercase tracking-widest text-center px-12 opacity-60">
            {claimType === 'AUTO' ? t("Take a clear photo of the damaged part.", "Foto bagian yang rusak dengan jelas.") : t("Upload your medical hospital billing.", "Unggah tagihan kuitansi rumah sakit.")}
          </p>
          <input type="file" className="absolute inset-0 opacity-0 cursor-pointer" onChange={handleUpload} />
        </div>
        <div className="p-6 bg-amber-500/5 border border-amber-500/10 rounded-[2.5rem] flex gap-5">
           <Info size={24} className="text-amber-500 shrink-0"/>
           <p className="text-xs font-bold uppercase tracking-wide text-amber-600 leading-relaxed">
             {t("Neural protocol requires high clarity. Ensure good lighting for 60s processing.", 
                "Protokol neural membutuhkan kejernihan tinggi. Pastikan pencahayaan cukup untuk proses 60 detik.")}
           </p>
        </div>
      </div>
    );
  }

  if (step === 'analyzing') {
    return (
      <div className="glass-card rounded-[3rem] h-full flex flex-col items-center justify-center animate-pop-in bg-white dark:bg-midnight overflow-hidden">
        <NeuralProcessingView 
          label={claimType === 'AUTO' ? t("Neural Damage Audit", "Audit Kerusakan Neural") : t("Neural Data Extraction", "Ekstraksi Data Neural")} 
          sublabel={t("Analyzing evidence matrix via SurePath cluster...", "Menganalisa matriks bukti melalui SurePath cluster...")}
        />
      </div>
    );
  }

  if (step === 'result') {
    if (claimType === 'AUTO' && claimResult) {
      return (
        <div className="space-y-6 animate-pop-in h-full flex flex-col pb-6">
          <Header title={t("Audit Results", "Hasil Audit")} showBack onBack={() => setStep('upload')} />
          <div className="p-8 bg-slate-900 rounded-[3rem] text-white relative overflow-hidden shadow-2xl">
            <div className="absolute top-0 right-0 p-10 opacity-10 rotate-12"><Activity size={160}/></div>
            <div className="relative z-10 space-y-6">
               <div className="flex justify-between items-center">
                  <p className="text-[0.6rem] font-black uppercase text-primary-400 tracking-[0.4em]">{t('Estimated Repair', 'Estimasi Perbaikan')}</p>
                  <Badge variant="success" className="bg-white/10 text-white border-white/20">{claimResult.severity} Impact</Badge>
               </div>
               <h3 className="text-5xl font-black tracking-tighter leading-none">{formatIDR(claimResult.totalEstimasi)}</h3>
               <p className="text-sm font-medium text-slate-400 italic leading-relaxed border-l-2 border-primary-500 pl-4 py-1">"{claimResult.aiInsight}"</p>
            </div>
          </div>

          <div className="flex bg-gray-100 dark:bg-white/5 p-1.5 rounded-2xl text-[0.6rem] font-black uppercase tracking-widest shadow-inner border border-black/5">
              <button onClick={() => setActiveTab('evidence')} className={`flex-1 py-3 rounded-xl transition-all ${activeTab === 'evidence' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400 opacity-60'}`}>{t('Analysis', 'Analisa')}</button>
              <button onClick={() => setActiveTab('reasoning')} className={`flex-1 py-3 rounded-xl transition-all ${activeTab === 'reasoning' ? 'bg-white dark:bg-gray-800 shadow-xl text-primary-500' : 'text-gray-400 opacity-60'}`}>{t('Workshop', 'Bengkel')}</button>
          </div>

          <div className="flex-1 overflow-y-auto no-scrollbar space-y-3">
            {activeTab === 'evidence' && (
              <div className="animate-fade-in space-y-3">
                {claimResult.rincianPart?.map((p, i) => (
                  <div key={i} className="p-6 bg-white dark:bg-white/5 rounded-[2rem] border border-black/5 flex items-center justify-between hover:border-primary-500/30 transition-all shadow-sm">
                    <div>
                      <p className="font-black uppercase text-sm tracking-tight text-slate-900 dark:text-white">{p.namaPart}</p>
                      <p className="text-[0.55rem] font-bold text-gray-400 uppercase tracking-widest mt-1">{p.kondisi}</p>
                    </div>
                    <p className="font-black text-sm text-primary-500">{formatIDR(p.estimasiBiaya)}</p>
                  </div>
                ))}
              </div>
            )}
            {activeTab === 'reasoning' && (
              <div className="p-8 bg-white dark:bg-white/5 rounded-[3rem] border border-black/5 shadow-inner space-y-8 animate-fade-in">
                 <div className="space-y-3">
                    <div className="flex items-center gap-3 text-primary-500">
                       <Zap size={18}/>
                       <span className="text-[0.6rem] font-black uppercase tracking-widest">{t('Neural Logic', 'Logika Neural')}</span>
                    </div>
                    <p className="text-sm font-medium text-slate-600 dark:text-slate-400 leading-relaxed italic">{claimResult.technicalReasoning}</p>
                 </div>
                 <div className="p-6 bg-primary-500/5 rounded-2xl border border-primary-500/10 flex justify-between items-center">
                    <div>
                       <p className="text-[0.5rem] font-black uppercase text-gray-400 tracking-widest">{t('Recommended Center', 'Pusat Rekomendasi')}</p>
                       <p className="text-lg font-black uppercase tracking-tighter text-primary-600 dark:text-primary-400">{claimResult.rekomendasiBengkel}</p>
                    </div>
                    <Building2 size={24} className="text-primary-500 opacity-50"/>
                 </div>
              </div>
            )}
          </div>

          <button onClick={() => setStep('reporting')} className="w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-sm tracking-[0.3em] shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
             {t('Initialize Final Report', 'Lanjut Laporan Akhir')} <ArrowRight size={20}/>
          </button>
        </div>
      );
    } else if (claimType === 'HEALTH' && healthResult) {
       return (
        <div className="space-y-6 animate-pop-in h-full flex flex-col pb-6">
           <Header title={t("Medical Verification", "Verifikasi Medis")} showBack onBack={() => setStep('upload')} />
           <div className="p-8 bg-rose-500/5 border-2 border-rose-500/10 rounded-[3rem] relative overflow-hidden shadow-xl">
              <div className="absolute top-0 right-0 p-10 opacity-10"><HeartPulse size={140}/></div>
              <div className="relative z-10 space-y-6">
                 <div>
