                <input 
                  type="date" required 
                  min={dateLimits.min} max={dateLimits.max}
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-slate-100 dark:border-white/5 text-sm outline-none focus:border-primary-500 font-bold shadow-inner" 
                  value={reportForm.date}
                  onChange={(e) => setReportForm({...reportForm, date: e.target.value})}
                />
              </div>
            </div>
            <div className="space-y-1.5">
              <label className="text-[0.55rem] font-black uppercase tracking-widest text-gray-400 ml-2">{t('Event Time', 'Waktu Kejadian')}</label>
              <div className="relative">
                <Clock size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-primary-500 pointer-events-none" />
                <input 
                  type="time" required 
                  className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-slate-100 dark:border-white/5 text-sm outline-none focus:border-primary-500 font-bold shadow-inner" 
                  value={reportForm.time}
                  onChange={(e) => setReportForm({...reportForm, time: e.target.value})}
                />
              </div>
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[0.55rem] font-black uppercase tracking-widest text-gray-400 ml-2">{t('Location Registry', 'Lokasi TKP')}</label>
            <div className="relative">
              <MapPin size={16} className="absolute left-4 top-1/2 -translate-y-1/2 text-primary-500" />
              <input 
                type="text" required placeholder={t("Detailed coordinate or address...", "Alamat atau koordinat detail...")}
                className="w-full pl-12 pr-4 py-4 rounded-2xl bg-white dark:bg-white/5 border-2 border-slate-100 dark:border-white/5 text-sm outline-none focus:border-primary-500 font-bold shadow-inner" 
                value={reportForm.location}
                onChange={(e) => setReportForm({...reportForm, location: e.target.value})}
              />
            </div>
          </div>

          <div className="space-y-1.5">
            <label className="text-[0.55rem] font-black uppercase tracking-widest text-gray-400 ml-2">{t('Narrative Chronology', 'Narasi Kronologi')}</label>
            <textarea 
              required rows={4} placeholder={t("Describe the flow of event in detail...", "Ceritakan detail kejadian secara kronologis...")}
              className="w-full px-6 py-4 rounded-[2rem] bg-white dark:bg-white/5 border-2 border-slate-100 dark:border-white/5 text-sm outline-none focus:border-primary-500 resize-none font-medium leading-relaxed shadow-inner" 
              value={reportForm.chronology}
              onChange={(e) => setReportForm({...reportForm, chronology: e.target.value})}
            />
          </div>

          <div className="pt-2">
            <label className={`flex items-center gap-5 p-6 bg-white dark:bg-white/5 border-2 rounded-[2.5rem] cursor-pointer transition-all shadow-xl ${reportForm.thirdPartyInvolved ? 'border-primary-500/50 bg-primary-500/5' : 'border-slate-50'}`}>
              <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 text-white shadow-lg shadow-primary-500/20' : 'bg-gray-100 dark:bg-white/10 text-gray-400 shadow-inner'}`}>
                <Users size={28}/>
              </div>
              <div className="flex-1">
                <p className="text-sm font-black uppercase tracking-widest text-slate-800 dark:text-white">{t('Third Party Mismatch', 'Melibatkan Pihak Ke-3?')}</p>
                <p className="text-[0.55rem] font-bold text-gray-400 uppercase mt-1 leading-tight">{t('Check if other assets/people are involved.', 'Centang jika ada orang atau aset lain terlibat.')}</p>
              </div>
              <div className={`w-8 h-8 rounded-xl border-2 flex items-center justify-center transition-all ${reportForm.thirdPartyInvolved ? 'bg-primary-500 border-primary-500 shadow-lg' : 'border-slate-200 dark:border-white/10'}`}>
                {reportForm.thirdPartyInvolved && <CheckCircle2 size={18} className="text-white" strokeWidth={3}/>}
              </div>
              <input 
                type="checkbox" 
                className="hidden" 
                checked={reportForm.thirdPartyInvolved}
                onChange={(e) => setReportForm({...reportForm, thirdPartyInvolved: e.target.checked})}
              />
            </label>
          </div>
        </form>

        <button 
          onClick={handleFinalReport} disabled={isSubmitting}
          className="mt-6 w-full py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2rem] font-black uppercase text-sm tracking-[0.3em] shadow-2xl flex items-center justify-center gap-4 disabled:opacity-50 transition-all active:scale-95 group relative overflow-hidden"
        >
          <div className="absolute inset-0 bg-primary-500 translate-y-full group-hover:translate-y-0 transition-transform duration-500 opacity-20"></div>
          {isSubmitting ? <Loader2 className="animate-spin" size={24}/> : <Rocket size={24} className="relative z-10"/>}
          <span className="relative z-10">{t('Submit to Neural Core', 'Kirim ke Sistem Pusat')}</span>
        </button>
      </div>
    );
  }

  if (step === 'success') {
    return (
      <div className="text-center space-y-10 py-10 animate-pop-in flex flex-col h-full justify-center items-center">
        <div className="relative">
           <div className="absolute inset-0 bg-emerald-500/20 blur-[60px] rounded-full animate-pulse scale-150"></div>
           <div className="w-32 h-32 bg-emerald-500 rounded-[3rem] flex items-center justify-center text-white shadow-[0_30px_60px_rgba(16,185,129,0.4)] relative z-10 border-4 border-white dark:border-[#0f172a]">
             <CheckCircle2 size={72} strokeWidth={2.5} className="animate-pop-in" />
           </div>
        </div>
        <div className="space-y-4 px-8">
          <h3 className="text-4xl font-black uppercase tracking-tighter text-slate-900 dark:text-white leading-none">{t('Transmission', 'Laporan')} <span className="text-emerald-500">{t('Success', 'Berhasil')}</span></h3>
          <p className="text-sm text-gray-500 dark:text-gray-400 leading-relaxed font-bold uppercase tracking-widest max-w-sm">
            {t('Your claim node has been validated and synced. Expect updates within', 'Simpul klaim Anda telah divalidasi dan disinkronkan. Update status dalam')} <span className="text-primary-500">60 {t('minutes', 'menit')}</span>.
          </p>
        </div>
        <div className="w-full max-w-sm p-6 rounded-[2.5rem] bg-gray-50 dark:bg-white/5 border border-black/5 text-left space-y-3 shadow-inner">
          <p className="text-[0.6rem] font-black text-gray-400 uppercase tracking-[0.4em]">Ledger Node Hash</p>
          <p className="text-xs font-mono text-primary-500 break-all leading-tight opacity-80">SP-TRANS-{Date.now().toString().slice(-8)}-MESH</p>
        </div>
        <button onClick={onComplete} className="w-full max-w-sm py-6 bg-slate-900 dark:bg-white text-white dark:text-black rounded-[2.5rem] font-black uppercase text-sm tracking-[0.3em] shadow-2xl transition-all active:scale-95 border border-white/10">{t('Back to Matrix', 'Kembali ke Beranda')}</button>
      </div>
    );
  }

  return null;
};

