export const Button: React.FC<{ 
  children?: React.ReactNode, 
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'brand',
  size?: 'sm' | 'md' | 'lg' | 'xl',
  icon?: any,
  onClick?: () => void,
  className?: string,
  disabled?: boolean
}> = ({ 
  children, 
  variant = 'primary', 
  size = 'md', 
  icon: Icon, 
  onClick,
  className = "",
  disabled = false
}) => {
  const variants = {
    primary: "bg-slate-900 text-white hover:bg-slate-800 shadow-xl",
    brand: "bg-emerald-600 text-white hover:bg-emerald-700 shadow-xl shadow-emerald-600/20",
    secondary: "bg-white text-slate-900 border border-slate-200 hover:bg-slate-50",
    outline: "bg-transparent border-2 border-slate-200 text-slate-900 dark:text-white hover:border-emerald-500 hover:text-emerald-600",
    ghost: "bg-transparent text-slate-500 hover:bg-slate-100"
  };

  const sizes = {
    sm: "px-5 py-2 text-[10px] font-bold",
    md: "px-7 py-3 text-xs font-bold",
    lg: "px-9 py-4 text-sm font-black tracking-widest",
    xl: "px-11 py-5 text-base font-black tracking-widest"
  };

  return (
    <button 
      disabled={disabled}
      onClick={onClick}
      className={`rounded-2xl transition-all flex items-center justify-center gap-3 active:scale-[0.98] disabled:opacity-50 uppercase ${variants[variant]} ${sizes[size]} ${className}`}
    >
      {children}
      {Icon && <Icon size={18} strokeWidth={2.5} />}
    </button>
  );
};

