import React, { useState, useEffect } from 'react';
import Navbar from './components/Navbar';
import DesktopLanding from './components/DesktopLanding';
import MobilePortal from './components/MobilePortal';
import AuthGate from './components/AuthGate';
import CarInsuranceWizard from './components/CarInsuranceWizard';
import TravelInsuranceWizard from './components/TravelInsuranceWizard';
import PAInsuranceWizard from './components/PAInsuranceWizard';
import MPARInsuranceWizard from './components/MPARInsuranceWizard';
import ClaimManager from './ClaimManager';
import UserProfile from './UserProfile';
import HealthChat from './components/HealthChat';
import { db, seedDatabase } from './db';
import { Language } from './types';

const App = () => {
  const [isMobile, setIsMobile] = useState(window.innerWidth < 1024);
  const [currentPage, setPage] = useState('home');
  const [currentUser, setCurrentUser] = useState<any>(null);
  const [lang, setLang] = useState<Language>(Language.ID);

  useEffect(() => {
    seedDatabase();
    const saved = localStorage.getItem('SUREPATH_SESSION');
    if (saved) {
      try {
        setCurrentUser(JSON.parse(saved));
      } catch (e) {
        console.error("Session corrupted", e);
        localStorage.removeItem('SUREPATH_SESSION');
      }
    }

    const handleResize = () => setIsMobile(window.innerWidth < 1024);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const handleAuthSuccess = (user: any) => {
    setCurrentUser(user);
    localStorage.setItem('SUREPATH_SESSION', JSON.stringify(user));
    setPage('home');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('SUREPATH_SESSION');
    setPage('home');
  };

  const renderMainContent = () => {
    if (currentPage === 'buy-car') return <CarInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-travel') return <TravelInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-pa') return <PAInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;
    if (currentPage === 'buy-mpar') return <MPARInsuranceWizard onComplete={() => setPage('home')} currentUser={currentUser} lang={lang} />;

    if (currentPage === 'claims') return <ClaimManager onComplete={() => setPage('home')} lang={lang} />;
    if (currentPage === 'help') return <HealthChat onBack={() => setPage('home')} lang={lang} />;
    if (currentPage === 'profile') return <UserProfile currentUser={currentUser} lang={lang} onLogout={handleLogout} />;
    if (currentPage === 'auth') return <AuthGate onAuthSuccess={handleAuthSuccess} />;

    if (isMobile) {
      if (!currentUser) return <AuthGate onAuthSuccess={handleAuthSuccess} />;
      return <MobilePortal currentUser={currentUser} setPage={setPage} lang={lang} />;
    } else {
      return <DesktopLanding onStart={() => setPage(currentUser ? 'products' : 'auth')} lang={lang} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] font-sans text-slate-900 selection:bg-emerald-100 selection:text-emerald-900">
      {!isMobile && !currentPage.startsWith('buy-') && currentPage !== 'auth' && (
        <Navbar currentPage={currentPage} setPage={setPage} />
      )}

      <main className="animate-fade-in transition-all duration-700">
        {renderMainContent()}
      </main>

      {isMobile && currentUser && !currentPage.startsWith('buy-') && currentPage !== 'auth' && (
        <nav className="fixed bottom-8 left-6 right-6 h-22 bg-white/95 dark:bg-[#111]/95 backdrop-blur-2xl z-[70] flex items-center justify-around px-6 rounded-[2.5rem] shadow-[0_40px_80px_-20px_rgba(0,0,0,0.2)] border border-slate-100 transition-all duration-500">
           {[
             { id: 'home', label: 'Home', icon: HomeIcon },
             { id: 'products', label: 'Beli', icon: ShoppingBagIcon },
             { id: 'claims', label: 'Klaim', icon: ZapIcon },
             { id: 'profile', label: 'Akun', icon: UserIcon }
           ].map(item => (
             <button 
               key={item.id}
               onClick={() => setPage(item.id)}
               className={`flex flex-col items-center gap-2 flex-1 py-4 transition-all duration-500 active:scale-90 ${currentPage === item.id ? 'text-emerald-600 scale-110 -translate-y-1' : 'text-slate-400'}`}
             >
               <item.icon size={26} strokeWidth={2.5} className={currentPage === item.id ? 'drop-shadow-[0_0_12px_rgba(16,185,129,0.4)]' : ''} />
               <span className="text-[10px] font-black uppercase tracking-widest">{item.label}</span>
             </button>
           ))}
        </nav>
      )}
    </div>
  );
};

const HomeIcon = ({ size, className, strokeWidth }: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>;
const ShoppingBagIcon = ({ size, className, strokeWidth }: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M6 2 3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4Z"/><path d="M3 6h18"/><path d="M16 10a4 4 0 0 1-8 0"/></svg>;
const ZapIcon = ({ size, className, strokeWidth }: any) => <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M13 2 3 14h9l-1 8 10-12h-9l1-8z"/></svg>;
