export const ApprovalsView = () => {
    const [pending, setPending] = useState<Policy[]>([]);
    useEffect(() => { db.policies.where('status').equals('PENDING').toArray().then(setPending); }, []);

    const handleApprove = async (id: number) => {
        await db.policies.update(id, { status: 'ACTIVE' });
        setPending(prev => prev.filter(p => p.id !== id));
    };

    return (
        <Card>
           <h3 className="text-sm font-black uppercase tracking-widest mb-8">Persetujuan Polis Tertunda</h3>
           {pending.length === 0 ? (
              <div className="py-20 text-center opacity-30">
