              <div className="grid gap-4">
                 {pending.map(p => (
                    <div key={p.id} className="p-6 bg-white/5 rounded-[2.5rem] border border-white/5 flex items-center justify-between">
                       <div className="flex items-center gap-5">
                          <div className="w-14 h-14 bg-amber-500/10 rounded-2xl flex items-center justify-center text-amber-500"><ShieldAlert size={28}/></div>
