                             <p className="text-[0.55rem] font-bold text-gray-500 uppercase tracking-widest">{p.type} • {formatIDR(p.premium)}</p>
                          </div>
                       </div>
                       <div className="flex gap-3">
                          <button className="p-4 bg-rose-500/10 text-rose-500 rounded-2xl hover:bg-rose-500 hover:text-white transition-all"><XCircle size={20}/></button>
                          <button onClick={() => handleApprove(p.id!)} className="p-4 bg-emerald-500/10 text-emerald-500 rounded-2xl hover:bg-emerald-500 hover:text-white transition-all"><CheckCircle size={20}/></button>
