export const SecurityView = () => {
    const [pulse, setPulse] = useState(getSecurityPulse());
    const [threats, setThreats] = useState<ThreatNode[]>(getRecentThreats());
    const [traffic, setTraffic] = useState<number[]>(Array(40).fill(0).map(() => 20 + Math.random() * 40));

    useEffect(() => {
        const interval = setInterval(() => {
            setPulse(getSecurityPulse());
            setTraffic(prev => [...prev.slice(1), 10 + Math.random() * 80]);
            if (Math.random() > 0.9) {
                setThreats(prev => [generateLiveThreat(), ...prev.slice(0, 4)]);
