import React, { useState, useEffect, useMemo } from 'react';
import { 
  User, Lock, Eye, EyeOff, ArrowRight, 
  Globe, ShieldCheck, RefreshCw, 
  Sparkles, BadgeCheck, KeyRound, 
  Zap, UserCircle, AlertCircle, Check
} from 'lucide-react';
import { SurePathLogo } from './Navbar';
import { Language, UserRole } from '../types';
import { db, User as DBUser } from '../db';
import { hashPassword, verifyPassword, validatePasswordStrength, REGEX, createSessionToken } from '../services/authService';
import { NeuralBot } from './car-wizard/WizardUI';

interface AuthGateProps {
  onAuthSuccess: (user: any) => void;
  initialLang?: Language;
  initialMode?: 'LOGIN' | 'REGISTER';
}

const ValidationStatus: React.FC<{ met: boolean, label: string }> = ({ met, label }) => (
    <div className={`flex items-center gap-2 transition-all ${met ? 'text-emerald-500' : 'text-slate-400'}`}>
        <div className={`w-3 h-3 rounded-full flex items-center justify-center ${met ? 'bg-emerald-500/10' : 'bg-slate-100 dark:bg-white/5'}`}>
            <Check size={8} strokeWidth={4} className={met ? 'opacity-100' : 'opacity-0'} />
        </div>
        <span className="text-[0.6rem] font-bold uppercase tracking-widest">{label}</span>
    </div>
);

const AuthGate: React.FC<AuthGateProps> = ({ onAuthSuccess, initialLang = Language.ID, initialMode = 'LOGIN' }) => {
  const [mode, setMode] = useState<'LOGIN' | 'REGISTER' | 'VERIFY'>(initialMode as any);
  const [showPass, setShowPass] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [otp, setOtp] = useState('');
  const [generatedOtp, setGeneratedOtp] = useState('');
  const [statusMsg, setStatusMsg] = useState('Secure Environment Active');
  const [lang, setLang] = useState<Language>(initialLang);

  const [formData, setFormData] = useState({ name: '', email: '', phone: '', password: '' });

  const t = (en: string, idn: string) => lang === Language.EN ? en : idn;

  useEffect(() => {
    setMode(initialMode as any);
  }, [initialMode]);

  const passwordStrength = useMemo(() => validatePasswordStrength(formData.password), [formData.password]);
  const isEmailValid = useMemo(() => REGEX.EMAIL.test(formData.email), [formData.email]);
  const isPhoneValid = useMemo(() => REGEX.PHONE.test(formData.phone), [formData.phone]);

  const canRegister = useMemo(() => {
      return formData.name.length > 2 && isEmailValid && isPhoneValid && passwordStrength.score === 4;
  }, [formData.name, isEmailValid, isPhoneValid, passwordStrength]);

  const canLogin = useMemo(() => {
      return isEmailValid && formData.password.length > 0;
  }, [isEmailValid, formData.password]);

  const handleDemoAccess = async () => {
    setLoading(true);
    setStatusMsg(t('Opening Demo Node...', 'Membuka Node Demo...'));
    setError(null);

    try {
      const user = await db.users.where('email').equals('user@surepath.ai').first();
      if (user) {
        setStatusMsg(t('Demo Authenticated!', 'Akses Demo Terbuka!'));
        const token = createSessionToken(user);
        setTimeout(() => onAuthSuccess({ ...user, token }), 1000);
      } else {
        setError(t("Demo user not initialized. Please refresh.", "User demo belum siap. Silakan refresh."));
        setLoading(false);
      }
    } catch (err) {
      setError(t("Technical connection error.", "Terjadi kendala saat memuat demo."));
      setLoading(false);
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    if (mode === 'REGISTER' && !canRegister) return;
    if (mode === 'LOGIN' && !canLogin) return;

    setLoading(true);
    setError(null);
    setStatusMsg(t('Verifying Neural Link...', 'Memverifikasi Identitas...'));

    try {
      if (mode === 'LOGIN') {
        const user = await db.users.where('email').equals(formData.email).first();
        if (user && user.passwordHash && user.salt) {
          const isValid = await verifyPassword(formData.password, user.passwordHash, user.salt);
          if (isValid) {
            setStatusMsg(t('Success! Access Granted.', 'Berhasil Masuk!'));
            const token = createSessionToken(user);
            setTimeout(() => onAuthSuccess({ ...user, token }), 800);
          } else {
            setError(t("Incorrect password provided.", "Kata sandi yang Anda masukkan salah."));
            setLoading(false);
          }
        } else {
          setError(t("Email not registered in matrix.", "Email belum terdaftar di sistem."));
          setLoading(false);
        }
      } else {
        const existing = await db.users.where('email').equals(formData.email).first();
        if (existing) {
          setError(t("Email already exists in system.", "Email ini sudah digunakan dalam sistem."));
          setLoading(false);
          return;
        }
        // Mocking verification code delivery
        const newOtp = Math.floor(100000 + Math.random() * 900000).toString();
        setGeneratedOtp(newOtp);
        console.log("SURPATH_OTP_DEBUG:", newOtp);
        setTimeout(() => {
          setMode('VERIFY');
          setLoading(false);
          setStatusMsg(t('Verification code sent!', 'Kode verifikasi telah dikirim!'));
        }, 1500);
      }
    } catch (err) {
      console.error("Auth Logic Error", err);
      setError(t("Internal node failure.", "Terjadi kendala teknis. Coba lagi ya."));
      setLoading(false);
    }
  };

  const finalizeRegistration = async () => {
    setLoading(true);
    setStatusMsg(t('Provisioning your node...', 'Menyiapkan node kamu...'));
    try {
      const { hash, salt } = await hashPassword(formData.password);
      const newUser: DBUser = {
        name: formData.name,
        email: formData.email,
        phone: formData.phone,
        passwordHash: hash,
        salt: salt,
        role: UserRole.CUSTOMER,
        nodeId: `SP-NODE-${Math.floor(1000 + Math.random() * 8999)}`,
        verified: true,
        trustScore: 85,
        memberSince: new Date().toISOString()
      };
      const id = await db.users.add(newUser);
      const userWithId = { ...newUser, id };
      const token = createSessionToken(userWithId);
      onAuthSuccess({ ...userWithId, token });
    } catch (err) {
      console.error("Reg Error", err);
      setError(t("Node creation failed.", "Gagal membuat node akun."));
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#fafaf9] dark:bg-[#080707] flex flex-col items-center p-6 relative overflow-hidden transition-all duration-700">
      <div className="absolute top-[-5%] right-[-10%] w-[500px] h-[500px] bg-primary-500/5 rounded-full blur-[100px] pointer-events-none"></div>

      <div className="w-full max-w-md flex flex-col items-center space-y-8 flex-1 relative z-10 pt-10">
        <div className="flex flex-col items-center text-center">
          <div className="relative mb-6">
            <div className="p-6 bg-white dark:bg-[#111] rounded-[2.5rem] shadow-xl border border-slate-100 dark:border-white/5 relative group transition-all">
               <SurePathLogo className="w-16 h-16 relative z-10 group-hover:scale-105 transition-transform" />
            </div>
            <div className="absolute -bottom-3 -right-3 w-12 h-12 bg-white dark:bg-black rounded-2xl shadow-xl flex items-center justify-center border border-slate-100 dark:border-white/5">
                <NeuralBot mood={loading ? 'thinking' : (passwordStrength.score > 2 ? 'happy' : 'scanning')} className="w-8 h-8" />
            </div>
          </div>
          <h1 className="text-3xl font-black tracking-tighter uppercase text-slate-900 dark:text-white leading-none">Sure<span className="text-primary-500">Path</span></h1>
          <p className="text-[0.6rem] font-bold text-slate-400 uppercase tracking-[0.3em] mt-3">{statusMsg}</p>
        </div>

        <div className="w-full bg-white dark:bg-[#0c0c0c] rounded-[3rem] p-8 shadow-2xl border border-slate-100 dark:border-white/5 overflow-hidden transition-all">
          {mode === 'VERIFY' ? (
            <div className="space-y-8 text-center animate-pop-in py-4">
              <div className="space-y-2">
                <h3 className="text-xl font-black uppercase tracking-tight">{t('Verify Access', 'Konfirmasi Akses')}</h3>
                <p className="text-[0.65rem] text-slate-400 font-bold uppercase tracking-widest">{t('Enter the 6-digit simulation code.', 'Masukkan 6 digit kode simulasi.')}</p>
              </div>
              <input 
                type="tel" maxLength={6} placeholder="000000"
                className="w-full bg-transparent border-b-2 border-slate-200 dark:border-white/10 text-center text-4xl font-black tracking-[0.4em] text-primary-500 outline-none focus:border-primary-500 transition-all font-mono"
                value={otp} onChange={(e) => { setOtp(e.target.value.replace(/\D/g,'')); setError(null); }}
              />
              <button 
                onClick={async () => otp === generatedOtp ? await finalizeRegistration() : setError(t("Verification mismatch.", "Kode verifikasi tidak cocok."))} 
                disabled={otp.length < 6 || loading} 
                className="w-full py-4 bg-slate-900 dark:bg-white text-white dark:text-black rounded-2xl font-black uppercase text-xs tracking-[0.2em] shadow-xl active:scale-95 disabled:opacity-30 transition-all"
              >
                {t('Initialize Node', 'Inisialisasi Node')}
              </button>
              <p className="text-[0.55rem] font-bold text-gray-400 uppercase">DEBUG_OTP: {generatedOtp}</p>
            </div>
          ) : (
            <div className="space-y-6">
              <div className="flex bg-slate-100 dark:bg-white/[0.05] p-1.5 rounded-2xl mb-2 border border-slate-200 dark:border-white/5 shadow-inner">
                <button type="button" onClick={() => { setMode('LOGIN'); setError(null); }} className={`flex-1 py-3 rounded-xl text-[0.6rem] font-black uppercase tracking-widest transition-all ${mode === 'LOGIN' ? 'bg-white dark:bg-slate-700 text-primary-600 shadow-sm' : 'text-gray-400 opacity-60'}`}>{t('LOG IN', 'MASUK')}</button>
