export const ApprovalsView = () => {
    const [pending, setPending] = useState<Policy[]>([]);
    useEffect(() => { 
        db.policies.where('status').equals('PENDING').toArray().then(setPending); 
    }, []);

    const handleApprove = async (id: number) => {
        await db.policies.update(id, { status: 'ACTIVE' });
        setPending(prev => prev.filter(p => p.id !== id));
        await db.auditLogs.add({
            timestamp: new Date().toISOString(),
            actor: 'HQ-SYSTEM',
            domain: 'OPERATIONS',
            action: `Policy Approved Node-${id}`,
            payload: '{}'
        });
    };

    return (
        <Card className="text-white">
           <div className="flex justify-between items-center mb-10">
              <div>
                 <h3 className="text-sm font-black uppercase tracking-widest text-primary-500">Antrean Persetujuan Polis</h3>
                 <p className="text-[0.55rem] font-bold text-gray-500 uppercase tracking-widest mt-1">Menunggu Audit Manual</p>
              </div>
              <Badge color="yellow">{pending.length} Pending</Badge>
           </div>

           {pending.length === 0 ? (
              <div className="py-24 text-center opacity-30 flex flex-col items-center gap-4">
                 <ClipboardCheck size={64} strokeWidth={1.5} className="text-gray-500"/>
                 <div className="space-y-1">
                    <p className="text-xs font-black uppercase tracking-widest">Queue is Clear</p>
                 </div>
              </div>
           ) : (
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                 {pending.map(p => (
                    <div key={p.id} className="p-6 bg-white/5 rounded-[2.5rem] border border-white/5 flex items-center justify-between group hover:border-primary-500/20 transition-all">
                       <div className="flex items-center gap-5">
                          <div className="w-16 h-16 bg-amber-500/10 rounded-2xl flex items-center justify-center text-amber-500 shadow-inner group-hover:scale-105 transition-transform"><ShieldAlert size={32}/></div>
                          <div>
                             <p className="font-black text-sm uppercase text-white">{p.policyNumber}</p>
                             <p className="text-[0.55rem] font-bold text-gray-500 uppercase tracking-widest mt-1">{p.type} • {formatIDR(p.premium)}</p>
                          </div>
                       </div>
                       <div className="flex flex-col gap-2">
                          <button onClick={() => handleApprove(p.id!)} className="p-4 bg-emerald-500/10 text-emerald-500 rounded-2xl hover:bg-emerald-500 hover:text-white transition-all shadow-lg active:scale-90"><CheckCircle size={22}/></button>
                       </div>
                    </div>
                 ))}
              </div>
           )}
        </Card>
    );
};

