        await logAdminAction('HQ-ADMIN', 'OPERATIONS', `Manual User Registry: ${userForm.email}`, { role: userForm.role });

        setIsAddingUser(false);
        setUserForm({ name: '', email: '', phone: '', password: '', role: UserRole.CUSTOMER });
        fetchData();
