export const InventoryView = () => {
    const [providers, setProviders] = useState<DBProvider[]>([]);
    const [editingId, setEditingId] = useState<string | null>(null);
    const [editForm, setEditForm] = useState<Partial<DBProvider>>({});
    const [isAdding, setIsAdding] = useState(false);

    const loadProviders = async () => {
        const all = await db.providers.toArray();
        setProviders(all);
    };

    useEffect(() => { loadProviders(); }, []);

    const handleEdit = (p: DBProvider) => {
        setEditingId(p.id);
        setEditForm(p);
    };

    const handleSave = async () => {
        if (!editForm.id) return;
        await db.providers.put(editForm as DBProvider);
        setEditingId(null);
        loadProviders();
        await db.auditLogs.add({
            timestamp: new Date().toISOString(),
            actor: 'HQ-ADMIN',
            domain: 'INVENTORY',
            action: `Provider ${editForm.name} Updated`,
            payload: JSON.stringify(editForm)
        });
    };

    const handleAdd = async () => {
        const newId = `PROV-${Date.now()}`;
        const newProv: DBProvider = {
            id: newId,
            name: editForm.name || 'New Provider',
            logo: 'Shield', // Set as string identifier
            adminFee: editForm.adminFee || 50000,
            stampDuty: 10000,
            rating: 4.5,
            isActive: true,
            features: ['AI Protection', '24/7 Support'],
            advantages: ['Quick Process'],
            disadvantages: ['New on Platform'],
            extraCoinsPercent: 10
        };
        await db.providers.add(newProv);
        setIsAdding(false);
        setEditForm({});
        loadProviders();
    };

    const toggleStatus = async (p: DBProvider) => {
        await db.providers.update(p.id, { isActive: !p.isActive });
        loadProviders();
    };

    return (
        <div className="space-y-8 animate-fade-in text-white">
            <div className="flex justify-between items-end">
                <div>
                    <h2 className="text-3xl font-black uppercase tracking-tighter">Product <span className="text-primary-500">Orchestrator</span></h2>
                    <p className="text-xs text-gray-500 font-bold uppercase tracking-widest mt-1">Kelola Partner Asuransi & Tarif Global</p>
                </div>
                <button 
                  onClick={() => { setIsAdding(true); setEditForm({ name: '', adminFee: 50000 }); }} 
                  className="px-8 py-4 bg-emerald-500 hover:bg-emerald-600 text-white rounded-2xl font-black uppercase text-[0.65rem] tracking-widest shadow-xl transition-all active:scale-95 flex items-center gap-3"
                >
                    <Plus size={18}/> Tambah Perusahaan
                </button>
            </div>

            <div className="grid grid-cols-1 gap-6">
                {providers.map(p => (
                    <Card key={p.id} className={`${!p.isActive ? 'opacity-50 grayscale' : ''}`}>
                        <div className="flex flex-col lg:flex-row justify-between gap-8">
                            <div className="flex items-center gap-6">
                                <div className="w-20 h-20 bg-white/5 rounded-3xl flex items-center justify-center text-primary-500 border border-white/10 shadow-inner">
                                    <ProviderIcon name={p.logo} size={40}/>
                                </div>
                                <div className="space-y-2">
                                    {editingId === p.id ? (
                                        <input 
                                            className="bg-white/10 border border-white/20 rounded-xl px-4 py-2 text-xl font-black uppercase outline-none focus:border-primary-500"
                                            value={editForm.name}
                                            onChange={e => setEditForm({...editForm, name: e.target.value})}
                                        />
                                    ) : (
                                        <h3 className="text-2xl font-black uppercase tracking-tighter">{p.name}</h3>
                                    )}
                                    <div className="flex items-center gap-3">
                                        <Badge color={p.isActive ? 'emerald' : 'rose'}>{p.isActive ? 'Active Node' : 'Standby'}</Badge>
                                        <span className="text-[0.55rem] font-mono text-gray-500">ID: {p.id}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="grid grid-cols-2 sm:grid-cols-4 gap-6 flex-1">
                                <div className="space-y-1">
                                    <p className="text-[0.5rem] font-black text-gray-500 uppercase tracking-widest">Admin Fee</p>
                                    {editingId === p.id ? (
                                        <input 
                                            type="number"
                                            className="w-full bg-white/10 border border-white/20 rounded-lg px-2 py-1 text-xs font-black outline-none"
                                            value={editForm.adminFee}
                                            onChange={e => setEditForm({...editForm, adminFee: parseInt(e.target.value)})}
                                        />
                                    ) : (
                                        <p className="text-sm font-black text-white">{formatIDR(p.adminFee)}</p>
                                    )}
                                </div>
                                <div className="space-y-1">
                                    <p className="text-[0.5rem] font-black text-gray-500 uppercase tracking-widest">Extra Reward</p>
